INSERT INTO public.clubs (name, category, category_bucket, description, email, instagram, website) VALUES
  ('Artistic Swimming at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The goal of the Artistic Swimming at UC San Diego is to provide students who are beginning to competitive synchronized swimmers with a warm and encouraging atmosphere. Our goals are to give students an opportunity to improve their swimming abilities, participate in an unique and creative sport, create close bonds with their peers, and also have the opportunity to compete in the artistic swimming community. Our purpose is to offer students the opportunity to explore the art and discipline of synchronized swimming, regardless of, their prior experience. By participating in our club, students will gain enhanced physical fitness, teamwork and collaboration, leadership and personal development, artistic expression, and competition experience.', ''), NULLIF('agervaciodenda@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Asayake Taiko', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('To promote awareness of taiko on the UC San Diego campus and in the San Diego community through performances and other events. To help promote awareness of taiko at a national level through cooperation with other organizations such as other taiko groups.', ''), NULLIF('asayaketaiko@gmail.com', ''), NULLIF('@asayake_taiko', ''), NULLIF('', '')),
  ('ArtSpark', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('ArtSpark is a vibrant and welcoming community dedicated to nurturing the skills of aspiring artists. Our purpose is to provide a supportive and collaborative environment where student artists can make new friends, refine their craft, develop portfolio works, explore new art mediums, meet professionals, and gain knowledge for their future careers. Through workshops, guest artist speakers, field trips (to local art resource establishments), we aim to bridge the gap between academic art studies and the professional art industry. We will feature interactive projects, spotlight opportunities, and collaborate with other orgs. Whatever your major, skill level, or degree of commitment to a formal artistic career, ArtSpark is here for you to grow, connect, and thrive!', ''), NULLIF('artspark@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Ascend at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of Ascend UC San Diego is to empower and develop Pan-Asian and ally student leaders by providing professional development, mentorship, and networking opportunities. As part of Ascend, the largest Pan-Asian business professional organization in North America, our chapter seeks to prepare UCSD students for success in their academic, personal, and career pursuits. We aim to foster inclusive leadership, build connections with professionals and corporations, and create a supportive community that celebrates diversity while equipping members with the skills and experiences necessary to thrive in the global workforce.', ''), NULLIF('ascendatucsd@outlook.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Ascension Competitive Dance Team', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Ascension was founded in 1999 and embraces the principles of community in order to create a family for our members. As one of UCSD''''s longest-running competitive dance teams, we strive to become better than the team we were yesterday by learning from and inspiring one another.', ''), NULLIF('ascensionatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Asha For Education at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The primary objectives of this organization are: 1. to support social development projects targeting the education of underprivileged children in India by raising funds, and 2. to promote awareness about the educational resources available for underprivileged children in India.', ''), NULLIF('sd@ashanet.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Asian American Christian Fellowship', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The mission of Asian American Christian Fellowship (AACF) is to reach into the university and collegiate community, primarily to those who are Asian Pacific Americans, with the life-changing message of Jesus Christ. You don''''t need to be Asian, or American, or Christian to come check us out and join our community!! :)', ''), NULLIF('aacfatucsd@aacf.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Asian and Pacific Islander Student Alliance (APSA)', NULLIF('Student Affirmative Actions Committee (SAAC)', ''), NULLIF('Cultural', ''), NULLIF('We, the students of University of California at San Diego (UCSD), come together to provide a forum to deal with the problems and concerns of UCSD Asian and Pacific-Islander (API) students, especially those deemed “underrepresented” by the Student Affirmative Action Committee (SAAC); to try to create an environment where issues such as those political, educational, cultural and social can be addressed; to increase awareness about our API history and heritage within the university and the community; to unite as a community resource to represent a common voice and thereby empower ourselves; and to serve as a support network for building bonds and addressing differences between students. The Asian and Pacific-Islander Student Alliance is a non-profit organization.', ''), NULLIF('apsaatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Asians & Pacific Islanders for the Arts and Humanities (APIAH)', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The purpose of the Asians & Pacific Islanders for the Arts and Humanities (APIAH) shall be as follows: 1. Provide support and a close-knit community for Asian & Pacific Islander scholars/students/creatives studying or interested in the Arts and Humanities. 2. Promote creative opportunities for API scholars across the UCSD campus and beyond. 3. Raise awareness and de-stigmatize the study of the Arts and Humanities for API looking to major and minor. 5. Bring together API identifying undergraduate and graduate students studying different disciplines. 6. Support API transfers majoring and minoring in the Arts and Humanities. 7. Increase the presence of API in higher education.', ''), NULLIF('apiah@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('ASL Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The ASL Club at UC San Diego strives to promote the use of American Sign Language while also spreading awareness of the culture of the Deaf and Hard-of-Hearing community. Our goal is to create a safe space for new and existing signers to expand their knowledge of ASL/Deaf culture and connect with other students who seek to advance in the language and understanding of the culture. Throughout the upcoming quarters, we plan to host weekly meetings, social events, activities off-campus, and more all conducted in ASL.', ''), NULLIF('aslclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Association for Computing Machinery (ACM)', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('To foster a community devoted to computing and help students interested in the field develop their technical skills and professional networks.', ''), NULLIF('acmatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Association for Women in Mathematics', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Specific goals for this chapter are to 1. build community for women in mathematics, 2. provide mentorship for UC San Diego’s women in mathematics, 3. attract more diverse candidates to our graduate programs, and 4. create and maintain connections with other chapters of AWM. We believe achieving our goals will directly and positively impact our ability to support, retain, and attract talented women in our mathematics programs.', ''), NULLIF('awm@math.ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Association of Latino Professionals For America (ALPFA)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Association of Latino Professionals For America (ALPFA) is a pre-professional organization that is aimed to empower Latinos through career rediness and recruitment opportunities. We welcome all students to take advantage of our career prep workshops, panels, and recruitment opportunities so all students can have an equitable opportunity to reach their career aspirations!', ''), NULLIF('alpfa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Association of Muslims in Politics and Law', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Association of Muslims in Politics and Law (AMPL) is dedicated to empowering Muslims in the fields of law and governance through education, mentorship, and advocacy. We provide a platform for discussing legal and political issues, supporting aspiring lawyers and policymakers, and promoting justice and ethical leadership. By fostering engagement and representation, we aim to strengthen Muslim participation in shaping fair and inclusive legal and political systems.', ''), NULLIF('amplatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Association of Student Pharmacists (ASP) at UC San Diego Skaggs School of Pharmacy and Pharmaceutical Sciences (SSPPS)', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of this association shall be the development, promotion, and enhancement of the knowledge of pharmacy in the community, all in harmony with the educational interests of the University of California, San Diego Skaggs School of Pharmacy.', ''), NULLIF('aspatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Astronomy Club at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Astronomy Club at UC San Diego aims to promote an interest in astronomy and astrophysics among UC San Diego undergraduates. Our organization will focus on the exploration of the universe. We hope to help students interested in astronomy get to know each other and facilitate their access to professional faculty.', ''), NULLIF('astronomyclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Baha''''i Club at UC San Diego', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The purpose of this association shall be to further the tenets of the Bahá’í Faith, to invite those interested to investigate the Faith for themselves; to promote the unity of mankind; and to foster understanding, love and fellowship on this campus by sponsoring such things as lectures, information tables, service projects, discussions, informal gatherings, social activities and public meetings. This association shall not endorse any partisan or political group on a campus level or otherwise.', ''), NULLIF('bahaiclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Ballet Folklórico El Arcoíris Del Sur', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Our organization hopes to provide an inclusive and safe community to participate in the art of dancing Ballet Folklórico . We will facilitate an environment for learning and growing throughout the year by teaching different regions. Our goal is to host a end of the year showcase to encourage our dancers to share Mexican culture with the UCSD and surrounding community', ''), NULLIF('elarcoirisdelsur@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Association of Writers at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('We want to build a supportive and encouraging atmosphere for people who are interested in creative writing of all forms.', ''), NULLIF('associationofwritersclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Azerbaijani Student Association at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Azerbaijani Student Association at UC San Diego builds an inclusive community for Azerbaijani students and anyone interested in the culture. Our purpose is to promote diversity through open, accessible cultural events (Novruz, food, music, film), and support academics with study groups, mentoring, and speaker sessions. We aim to regularly collaborate with other cultural and professional clubs on campus to co-host programs, share resources, and create real cross-cultural learning and career connections.', ''), NULLIF('khajibayli@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Bangladeshi Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('We aim to help create a strong community with all the UCSD Bangladeshi and Bengali identifying students and allies to bring awareness and appreciation to Bangladeshi culture through various social, cultural, and educational events. Previously named Bangali Student Association.', ''), NULLIF('bangalistudents@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('BAPS Campus Fellowship', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('BAPS Campus Fellowship is a social and religious organization, which based on the teachings of Bhagwan Swaminarayan, and under the guidance of Param Pujya Mahant Swami Maharaj, will provide a means for students to learn more about the Swaminarayan way of life. Through group discussions, seminars, and social events, BAPS Campus Fellowship will garner and enrich these Swaminarayan values within its members, and provide them a valuable opportunity to stay connected to their cultural roots and better understand their beliefs. BAPS Campus Fellowship is an organization approved by the Bochasanwasi Shri Akshar Purushottam Swaminarayan Sanstha, Inc., a leading denomination of the Swaminarayan faith (hereinafter “BAPS”), and will represent itself in a way that is consistent with the guidelines set forth by BAPS.', ''), NULLIF('vmpatel@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Beat @ UC San Diego, The', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('To provide a fun and lively atmosphere to continue our passion for a cappella music at the collegiate level; to immerse members into the a cappella community on-campus and beyond; to strengthen and improve vocal and musical ability; to provide entertaining performances; and to foster close-knit relationships within the group.', ''), NULLIF('thebeatatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Ballet Folklorico la Joya de Mexico', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('BFLJDM is a traditional Mexican Folklorico group that is open to all UCSD affiliates regardless if they have previous dance experience or not. We strive to create a welcoming and fun environment free of judgment where we encourage members of our community to learn and engage in dances of our Mexican culture. Providing many performance opportunities throughout the year to showcase what our members learn. Spreading the beauty and knowledge keeping the tradition alive as UCSD''''s first established folklorico group.', ''), NULLIF('bfljdm@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Brain Exercise Initiative, The', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Brain Exercise Initiative is a student run non-profit organization that uses math, reading and writing as a form of cognitive development for the elderly. It is found that simple math exercises and reading aloud for just 30 minutes a day can have a positive impact on memory for those with Alzheimer''''s. This is currently being done extensively in Japan. It was discovered by a Japanese doctor, Ryuta Kawashima, and consists of math exercises and reading aloud of short stories. Done for just 30 minutes a day, 5 times a week, improvements in Alzheimer’s patients have been observed. It is currently being done in 1,400 care homes with 15,000 Alzheimer''''s patients all over Japan and has had great success. Many individuals showed improvements in communication and behavior. Some went from being bedridden to sitting in a chair or walking. Some showed improvement in controlling their bowel movement. Additionally, they began to feel happier.', ''), NULLIF('bei@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Brain Hub', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Brain Hub is dedicated to advancing the knowledge and passion for neuroscience, clinical aspects of brain and behavior, and the underlying biology. Our primary objectives encompass creating a dynamic, student-driven community by facilitating networking among students passionate about these fields. We aim to provide valuable study and career advice and mentorship from faculty and staff to ensure academic success. Our organization will host exclusive events with renowned companies and scientists, offering unique opportunities for students to engage with real-world applications and cutting-edge research. Brain Hub aspires to foster a nurturing environment that empowers students to explore, understand, and contribute to the fascinating world of brain science and its clinical implications.', ''), NULLIF('kbilokur@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('BRASA', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('BRASA at UC San Diego connects Brazilian and non-Brazilian students to the richness of Brazilian culture. Regardless of whether students arrive fueled by an existing passion or newfound curiosity, BRASA warmly invites all to engage and foster cross-cultural exchanges that enrich our campus. We also provide a supportive community for Brazilian students navigating international education.', ''), NULLIF('brasa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Brazilian Jiu-jitsu at UC San Diego', NULLIF('Martial Arts/Combatives/Weaponry', ''), NULLIF('Sports', ''), NULLIF('To foster self-confidence, promote a healthy lifestyle, and cultivate self-defense abilities among the student community at UC San Diego through the learning of modern grappling martial arts.', ''), NULLIF('bjjatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Breakin'''' Club- Body Rock', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Established in 2003, Bodyrock at UCSD is the first and only breaking club. Our goal is to promote the hip hop culture by teaching breaking to beginners, providing practice space for local bboys and bgirls, and showcasing our skills through performances and battles. Bodyrock hopes to entertain and inspire with our combination of athleticism and musicality.', ''), NULLIF('bodyrock@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Breaking Bread', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Breaking Bread at UCSD aims to donate baked goods to service members overseas, hospitals, children, and those who would otherwise be unable to access a baked good for their birthday or other special occasion. This club would also work to teach kids about nutrition and healthy cooking through easy to follow recipes and by introducing better eating habits. All in all, this club seeks to give back to the community through food.', ''), NULLIF('breakingbreadatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Bridges International', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The purpose of the Chapter, as articulated in the Charter, is to build movements of people who are transformed by Jesus Christ. The student-led movement seeks to introduce students to Jesus Christ, help them to grow in their faith, encourage them to live life passionately under the lordship of Christ, and inspire commitment to advancing the purposes of God in the world.', ''), NULLIF('bridgessd@bridgesinternational.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Beautiful Mind Project @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Beautiful Mind Project aims to promote well-rounded and intersectional understandings of mental health in the UC San Diego community, which includes the Muslim community and other student organizations. BMP seeks to destigmatize mental health by fostering conversations about mental health and facilitating access to mental health services for Muslim students. BMP seeks to accomplish these goals by utilizing Islamic principles as a source of and inspiration for mental wellness. By providing diverse, accessible resources, the Beautiful Mind Project advocates for its members a lifestyle that emphasizes the delicate balance between mental, spiritual, and physical health.', ''), NULLIF('bmpatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Bridging the Gap', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Helping underrepresented pre-health students gain knowledge and resources on their pre-health journeys. Bridging the Gap is a part of the Health and Medical Professions Preparation Program (HMP3).', ''), NULLIF('hmp3.bridgingthegap.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Business Club', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Business Club at UC San Diego is part of the Business Club network which is present in other schools such as Harvard, UC Berkeley, UCLA and USC. The purpose of this club is to provide a platform for students to connect with successful professionals. We host events with various businesses, professionals and other chapters pertaining to business and networking. Our events vary from industry to industry in order to allow people of different career paths to connect with professionals from their industry.', ''), NULLIF('businessclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('BURSA(Burmese Students Association)', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('1. The purpose of this organization is to: a. Assist new incoming UC San Diego students from Myanmar (Burma) in the transition to a new environment b. Foster a sense of community between students from Myanmar c. Foster and encourage interaction between members d. Raise awareness of Myanmar and its culture among the general student population e. Help connect Burmese students with the international and domestic student community at UC San Diego f. Create a fun atmosphere within the club g. Help non-Burmese members of the club learn more about Myanmar culture and its traditions', ''), NULLIF('bursa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Break, The', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('The Break is UC San Diego’s first and only nonpartisan political review publication. We aim to produce original journalism, enabling students to review ongoing developments in the world without an ideological lens — digging deeper beyond surface-level frameworks that often drive the political conversations of today. We publish articles, op-eds, and other forms of content covering various local, domestic, and international issues. The goal of The Break is to be the spark of conversation, to ignite intrigue and curiosity within individuals, and to encourage critical thinking by presenting diverse perspectives and nuanced analysis. By fostering a space where ideas can be explored without preconceived biases, The Break aspires to cultivate a community of informed and engaged citizens who are not only aware of the complexities of the world but also motivated to actively participate in shaping its future.', ''), NULLIF('thebreak@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Business Leaders Association', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Business Leaders Association at UC San Diego is dedicated to providing students with the resources and opportunities to explore and grow within all aspects of business. Our organization empowers students by offering valuable insights into fields such as entrepreneurship, innovation, marketing, consulting, finance, and beyond. We strive to create a collaborative environment where students can network with like-minded peers, learn from industry professionals, and develop the skills necessary to achieve their career aspirations. By fostering a diverse community of future business leaders, the Business Leaders Association equips its members with the tools, experiences, and connections needed to succeed in their professional journeys and drive positive change in the world of business.', ''), NULLIF('bla@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Business Council', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Business Council is organized to foster an integrated business community at UC San Diego between student organizations, administrative bodies, and outside parties.', ''), NULLIF('businesscouncilatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('California Public Interest Research Group @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Mission statement: Students have the power to shape the future we will inherit. We work with professional staff at colleges and universities to make sure our peers have the skills, opportunities and training they need to create a better, more sustainable future for all of us. Our chapters provide the training, professional support and resources students need to tackle climate change, protect public health, revitalize our democracy, feed the hungry and more. Students have been at the forefront of social change throughout history, from civil rights, to voting rights to protecting the environment. For nearly 50 years we’ve helped students to get organized, mobilized and energized so they can continue to be on the cutting edge of positive change.', ''), NULLIF('kathryn.gonzalez-valle@publicinterestnetwork.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('California Society of Health-System Pharmacists- at UC San Diego Student Chapter', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The mission of the California Society of Health-System Pharmacists- at UC San Diego Student Chapter is to make students aware of pharmacy practice in health systems and the potential of this setting for expanding the base of pharmacy practice, provide information to students about career directions in and credentials needed for pharmacy practice in health systems.', ''), NULLIF('iramiscal@health.ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Cambodian Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('We, a non-profit organization called the Cambodian Student Association (CSA) of the University of California, San Diego (UCSD), believe that by (1) building and strengthening identification of the Cambodian culture among fellow members, students and community at large, (2) offering consistent academic, social and moral encouragement through activities and community service and (3) developing social networks that will assist us during our time in college and in our lives thereafter, we will have established rare relationships and support systems based on common principles and values with fellow members who share common interests.', ''), NULLIF('csa.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Camp Kesem', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Camp Kesem at UC San Diego provides a free summer camp to children ages 6-18 in the San Diego community who have/had a parent with cancer.', ''), NULLIF('campkesem.atucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Campus Outreach at UC San Diego', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('Campus Outreach seeks to encourage the spiritual growth and flourishing of the UC San Diego campus through investigating Jesus, building friendships, and having fun. This club is non-profit and open to all.', ''), NULLIF('sea.choi@campusoutreach.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Cantonese Culture Club', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Embrace and educate the UC San Diego community about Cantonese culture and Cantonese language.', ''), NULLIF('dhyumcha@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Care2Share at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Care2Share at UC San Diego is guided by the following goals: To provide relief to the disadvantaged communities of Vietnam. To give the forgotten people of Vietnam the power they need to rise out of poverty through free medical services and other forms of financial support. To provide service opportunities to undergraduate students at UC San Diego. To raise awareness of the living conditions the ethnic communities of Vietnam must endure that are a result of their society’s purposeful ignorance of their existence.', ''), NULLIF('care2shareatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Caribbean and Afro-Latinx Student Association at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Caribbean and Afro-Latinx Student Association at UC San Diego is dedicated to transcending boundaries through education, celebration, and empowerment. Our mission is to enrich the campus community by providing a platform for the vibrant cultures and experiences of the Caribbean and Afro-Latinx diaspora. We strive to illuminate the rich tapestry of Caribbean and Afro-Latinx heritage through educational initiatives, cultural events, and dialogue. By amplifying voices, stories, and talents, we aim to foster understanding, appreciation, and solidarity within and beyond our university walls. As stewards of history and agents of change, we aim to leave a lasting legacy on UC San Diego, marking our presence with a resounding "we were here." We are committed to building a more inclusive and equitable campus where all voices are heard and valued.', ''), NULLIF('lsd001@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Careers in Student Affairs Club', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Careers in Student Affairs Club is a non-profit organization whose purpose is to explore and promote educational and career opportunities in the field of Higher Education, specifically in Student Affairs. We strive to help UC San Diego students and members achieve their academic, professional, and personal goals by providing shared information and opportunities to connect with current graduate students and administrators in the field.', ''), NULLIF('csac@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Catalyst at UC San Diego, The', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('The Catalyst is a digital paper series based at UC San Diego which aims to give voices to undergraduate students who have a passion for research. We welcome any and all students who are interested in publishing their work, and we are dedicated to fostering a diverse community of interdisciplinary scholarship; this includes expanding to include students from other institutions. We emphasize helping new students find their path in research, and aim to help publish new (and especially underrepresented) scholars. We do not discriminate based on race, color, national origin, religion, sex, gender, disability, age, medical condition, ancestry, marital status, citizenship, or sexual orientation. We are an academic organization connected to UC San Diego Undergraduate Research Hub.', ''), NULLIF('thecatalystatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Catholic Community - Newman Center Parish', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('We are students, alumni, faculty and staff at UC San Diego, as well as young adults and residents of the surrounding area who celebrate life together as the Catholic Community at UC San Diego. We feel at home in this community and are free to experience Christ''''s presence in the Word, in the Eucharist and in each other. Hospitality and welcome are hallmarks of our community. We are passionate about living the Gospel in the context of our Catholic faith.', ''), NULLIF('tritoncatholic@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('CAYS Fellowship', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('CAYS Fellowship is a student organization dedicated to outreach and apologetics, welcoming anyone who desires to learn more about Christ and the Bible, regardless of their background or prior knowledge. We invite people with difficult questions for in-depth conversations and wish to promote thoughtfulness on the motivations behind all that they do! Through Bible studies, Q&A panels, and fellowship activities, we strive to create an open and engaging environment where all are invited to explore and grow in their understanding.', ''), NULLIF('guotimothy03@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('333Jugglers', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('333Jugglers'''' main purpose is to create a safe social environment for learning and practicing juggling.', ''), NULLIF('333jugglers@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('528 @UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Our mission is to support positive and collaborative study for the MCAT. We will have two approaches to complete our mission and would like to have the following groups available: 1) Academic accountability silent study sessions. 2) MCAT Mastery Sessions whereby participants present a particularly challenging question from one of the seven topics, and present it to the larger group allowing each student to focus on a wide variety of topics in a realistic impromptu setting.', ''), NULLIF('mjulian@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('4N01 Dance Team', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('The purpose of 4N01 Dance Team is female empowerment through the medium of dance. We strongly emphasize the physical, emotional, and mental well-being of our members, as well as consider ourselves ambassadors for the betterment of all womankind. 4N01 challenges its members to go beyond their comfort zone, whether in dance or in life, and grow. 4N01 provides a safe zone where women can voice their opinions and receive advice or feedback from anyone else on the team. We come together as a family to take on any forces that may challenge us as individuals and as a team.', ''), NULLIF('x4n01x@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Academy of Managed Care Pharmacy (AMCP at UC San Diego)', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('AMCP at UCSD is an organization that aims to promote sound managed care pharmacy principles through education and professional development of its student pharmacist members and to encourage the education and support the advancement of managed care pharmacy. The purpose of the organization is to enhance the common academic and professional interests of the Chapter members, offer professional opportunities and leadership within managed care pharmacy, and establish, develop, promote, and conduct educational programs relating to and improving health, especially as it relates to the delivery of pharmacy services through managed care pharmacy.', ''), NULLIF('tew002@health.ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('A Lutheran Ministry Social (ALMS)', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To provide a safe and welcoming community for Lutheran and other Christian students to mingle and socialize amongst fellow peers sponsored by University Lutheran Church.', ''), NULLIF('alms@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Acamazing', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Acamazing is a co-ed a cappella group which seeks to foster a fun and engaging environment for singers and aspiring singers to create music without the use of instruments. We aim to nurture the musical talent of students at UC San Diego and to entertain ourselves, the UCSD community, and the general public. Additionally, as a result of membership within Acamazing, we hope that all members gain a better understanding of music and enrich their own musicality while building lasting friendships with their fellow members.', ''), NULLIF('acamazing@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Action for Lung Health', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of Action for Lung Health is to spread awareness and perform outreach for lung health in San Diego. Specifically, we aim to spread awareness and do outreach for lung cancer and lung disease. We will advocate to reduce tobacco use and for cleaner air in general as part of our mission and we will give students opportunities to get actively involved in lung health as well', ''), NULLIF('actionforlunghealth@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Active Minds', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Active Minds at UC San Diego is a student-led organization dedicated to advancing mental health awareness, education, and advocacy. Our purpose is to reduce stigma, encourage open dialogue, and connect students with resources that promote mental well-being. Through educational events, workshops, and peer support initiatives, we aim to cultivate a supportive and inclusive campus environment where all students feel empowered to prioritize their mental health.', ''), NULLIF('aactiveminds.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Aequora Ballet Company', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('The purpose of Aequora Ballet Company at UC San Diego is to provide a means for dancers to continue to cultivate their passion for dance while pursuing higher education. The organization will emphasize both classical and contemporary ballet in a recreational manner. The organization is geared toward intermediate-advanced level dancers. Members of the organization will foster dance and team-building skills through weekly rehearsals and a performance in the spring, along with other potential performance opportunities.', ''), NULLIF('aequoraballet@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Afghan Student Association (ASA)', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Our purpose is to unite students of Afghan background for cultural support, inclusion, and to learn about the complexities of our country’s history as well as provide a safe space for students to express their cultural and personal identity despite the negative associations we have faced in the news', ''), NULLIF('asadegi@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('AI Alignment at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('1) To help mitigate the full range of AI risks through building the AI safety community at UC San Diego. 2) To broaden AI horizons at UC San Diego through representation from non-computational disciplines such as the social sciences.', ''), NULLIF('ebu@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Aikido Labs', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('To bring together students of different STEM fields, with interested members in structural engineering, bioengineering, neuroscience, physics, data science, Molecular biology, etc. & to offer leadership experience and project based learning while also providing valuable research experience. The organization will allow participants to contribute to the field they’re researching, and learn valuable skills to apply to many different fields in STEM.', ''), NULLIF('nvenna@4ikido.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Chi Omega', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('Our purpose is to promote friendship, leadership, learning, and service amongst our members.', ''), NULLIF('axo.sd.president@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Epsilon Delta Pre-Health Professional Honor Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('A pre-health honor society with the purpose of connecting future health professionals and recognizing their achievements in their pursuit of a career in health. Activities include volunteering, educational programs and speakers at bi-weekly meetings including doctors, nurses, patients, medical students, pharmaceutical students, and more.', ''), NULLIF('aedatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Epsilon Omega, Eta', NULLIF('Multicultural Greek Council (MGC) - Fraternity', ''), NULLIF('Fraternity', ''), NULLIF('To unite men who strive to achieve high standards of achievement in all aspects of life, and who share in the need of promoting Armenian history, language, and culture.', ''), NULLIF('eta@alphaepsilonomega.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Epsilon Phi', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('To establish and maintain sisterhood of college/university women for social, educational, charitable and other non-profit purposes while taking pride in our Jewish founding.', ''), NULLIF('aephi.bh.president@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Epsilon Pi', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('Alpha Epsilon Pi''''s role is to encourage Jewish students to remain dedicated to Jewish ideals, values, and ethics and to develop members that effectively help to make UCSD a more inclusive and welcoming campus for all students, regardless of faith or cultural background. We rely on a variety of events and programs to help grow our community and to benefit UCSD and the San Diego community.', ''), NULLIF('aepiatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Gamma Alpha', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('Alpha Gamma Alpha''''s Zeta Chapter was established in 2007 at the University of California, San Diego. The sisters of Alpha Gamma Alpha work towards the advancement of Armenian causes, the greater San Diego community and our community here at UCSD. Our mission is to spread and further the Armenian culture and aid in Armenian causes as we guide fellow sisters in academics, life decisions, and social relationships while building life-long ties. For more information on becoming part of Alpha Gamma Alpha''''s legacy, contact the sisters at ucsdaga@gmail.com or visit us at alphagammaalpha.ucsd.edu', ''), NULLIF('agaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Ahlul-Bayt Student Association', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The Ahlul-Bayt Student Association’s mission is to cater to the spiritual and educational needs of Muslim students at UC San Diego, particularly those who have been marginalized in other spaces. Every aspect of ABSA at UC San Diego will align with the teachings of the Qur’an and sunnah of the Prophet Muhammad (s) and his Ahlul-Bayt (a). The organization aims to maintain an inclusive environment and to retain members in order to nurture a diverse generation of Muslims who are cognizant and pragmatic members of society.', ''), NULLIF('absaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Airsoft at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Foster a community of airsoft players that are passionate about the sport.', ''), NULLIF('Airsoft@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Kappa Psi', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The object and purpose of Alpha Kappa Psi Fraternity, Inc. (the "Fraternity") shall be to further the individual welfare of its members; to foster scientific research in the fields of commerce, accounts and finance; to educate the public to appreciate and demand higher ideals therein; and to promote and advance in institutions of college rank courses leading to degrees in business administration.', ''), NULLIF('sdakpsi@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Lambda Mu', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('Our mission is to connect, build, and sustain a lifelong brotherhood as the first Muslim-interest fraternity in America through excellence in character, excellence in service, excellence in intellectual standard, excellence in spirituality, and excellence in creativity amongst all members, chapters, conglomerates, and associates.', ''), NULLIF('alm@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Miracle Foundation (AMF) @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Alpha Miracle Foundation is a 501(c)(3) non-profit humanitarian organization. We are a public charity that provides assistance to both our local communities in Downtown San Diego and internationally. We strive to improve the lives of our charity''''s recipients through our many causes, including helping the homeless, fighting poverty, and feeding children.', ''), NULLIF('amf@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Beta Alpha Psi', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Accounting, Finance, and Information Technology honorary organization.', ''), NULLIF('chapter.leadership@bapatucsdrady.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Beta Theta Pi', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('To develop men of principle for a principled life.', ''), NULLIF('betathetapiatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Betty Boarders', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To create an inclusive and supportive community for women interested in surfing that is conducive to learning and fun.', ''), NULLIF('surfbettyboarders@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('BioConnect', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('BioConnect is an organization that aims to create a space where students passionate about ensuring equity in biology education at UC San diego can sharpen their communication and leadership skills by leading small group problem-solving sessions focused on specific biology courses. Club members will improve their biology knowledge/skills by facilitating the teaching of course content while mentoring fellow students and engaging with professors.', ''), NULLIF('bioconnectatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Bioengineering Graduate Society', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Bioengineering Graduate Society (BEGS) aims to be an interface for bioengineering graduate students at UC San Diego, their department, and the local community. Since its creation in 1994, the BEGS mission is to foster professional, educational, and social development opportunities through relationships with industry, alumni, and students. BEGS is a graduate student-run organization with the aid of the Bioengineering Department.', ''), NULLIF('begs@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Biological Sciences Student Association', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The primary purpose of the non-profit Biological Sciences Student Association (BSSA) is to unify biology majors through volunteering, academic, and social activities that enhance their overall experience as biology students at UCSD. We provide them with resources and support which may further their success throughout the undergraduate and graduate years and assist the transition to life beyond the degree. Additionally, the BSSA welcomes new undergraduates to the world of biology, encouraging the initiation of biological and scientific research both at UCSD and the surrounding institutions, creating accessible connections to mentors within the field of biological sciences and healthcare while also providing resources to learn about other positions in the biological sciences field.', ''), NULLIF('bssa.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Biology Undergraduate and Master''''s Mentorship Program', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('UCSD is an incubator for brilliance and innovation, especially in the Biology Department. Our senior investigators and students are among the brightest and come from all walks of life. While Biology is a revolutionary field, our face is often a misrepresentation of the global human population. Time and time again we have seen that the most effective problem-solving will be executed by diverse thinkers. Our primary aim is to ensure that ALL undergraduate and Master''''s students are equipped with an awareness of their place in science and the strength to stand in that place and advance to higher heights.', ''), NULLIF('bummp@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('BioScholars Program at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('BioScholars is a learning community dedicated to providing undergraduate students: - support for student transition to UC San Diego and the Division of Biological Sciences - exploration of issues and opportunities in the sciences and professions - understanding of the diversity of UC San Diego and the field of science - opportunities to enhance leadership skills - guidance to resources to assist students on their science journey - preparation of academic and career goals', ''), NULLIF('bioscholars@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Kappa Alpha Sorority Inc., Mu Iota', NULLIF('National Pan-Hellenic Council Organizations (NPHC)', ''), NULLIF('Greek Life', ''), NULLIF('Alpha Kappa Alpha Sorority’s mission is to cultivate and encourage high scholastic and ethical standards, to promote unity and friendship among college women, to study and help alleviate problems concerning girls and women in order to improve their social stature, to maintain a progressive interest in college life, and to be of “Service to All Mankind.”', ''), NULLIF('muiota1908@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Bird Club at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('To create a community of bird lovers and provide educational and social opportunities in ornithology, birding, and other affiliated activities. We collaborate with wildlife and conservation organizations in San Diego to protect and advocate for local birds and their habitats.', ''), NULLIF('birdclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Black Girls Rock Fitness Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Black Girls Rock! Fitness Club is a community dedicated to empowering Black women to prioritize their mental and physical health. We believe that when you look good, you feel good, and through fitness, we foster both inner strength and outer confidence. Our mission is to break down barriers in underrepresented fitness spaces, creating an environment where Black women can feel supported, inspired, and seen. With a focus on health, sisterhood, and self-care, we aim to cultivate a safe and inclusive space that encourages every Black woman to thrive and gain in every way that matters.', ''), NULLIF('blackgirlsrockfitnessclub@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Black Business Association', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Black Business Association at UC San Diego is the premier Black professional organization and business network on campus, dedicated to empowering students through professional development, mentorship, entrepreneurship, and career networking opportunities. Our mission is to promote professional and personal development at the undergraduate and postgraduate levels for the UC San Diego community and its surrounding areas. We aim to equip Black students with the tools and resources necessary to thrive in business industries while fostering leadership, innovation, and confidence. BBA members join a vibrant community of driven students pursuing careers and interests across various business fields. The organization celebrates diversity and welcomes students of all backgrounds while centering the advancement, representation, and success of Black students in business. Through our commitment to mentorship, inclusion, and empowerment, we strive to create pathways for lasting impact and generational excellence.', ''), NULLIF('bbaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Black Pre-Medical Society at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of this organization is to bring together a community of unique students of, and allies to, the Black Diaspora interested in pre-health professions on campus. We aim to provide educational resources, leadership opportunities, and volunteer opportunities to students who have limited support for applying to pre-health schools. These students include, but are not limited to: black students, allies of the black community, first generation college students, students considering a health profession, students pursuing a major in departments other than biology and chemistry, students belonging to other demographics that are underserved in health professions, students who decided to be pre-health in their later years, and students returning to school after several years in the workforce and considering a health profession. However, all students interested in health professions are welcomed to join.', ''), NULLIF('bpms@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Black Student Union', NULLIF('Student Affirmative Actions Committee (SAAC)', ''), NULLIF('Cultural', ''), NULLIF('Conceived in 1967, the Black Student Union at UC San Diego is charged with four fundamental responsibilities: 1. Access, retention, and yield programming to inspire, enlighten, to build unity, to challenge, and to perpetuate the ideologies of the Black Student Union at UCSD. 2. To support the efforts of those organizations which perpetuate the ideologies of the Black Student Union. 3. To assist in providing an environment that is conducive to academic excellence amongst the Black student population. 4. To be accountable through representation.', ''), NULLIF('bsuatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Black Triton Association', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To connect and support Black scholar-athletes at UC San Diego.', ''), NULLIF('blacktritons@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Bleeding Hearts Poetry Collective', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('We aim to foster a community of poetry lovers who come and share their written work on paper and/or performance with their peers. No experience or poetry-writing skills are required, you can just attend and interact with the art of your peers. It is a safe space to just engage with other poems! While targeting community-building we will create workshops to strengthen the craft and passion for poetry of the members of this student organization.', ''), NULLIF('bleedinghearts.pc@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Blind Snakes Disabled Students Empowerment Group', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('We are a student-led organization dedicated to improving access, inclusion, and support for disabled and marginalized communities, both on campus and in the surrounding area. Our initiatives have included providing free testing materials to all students, hosting a free food day in collaboration with the campus food co-op, volunteering monthly with Lunch at the Park in Chicano Park to prepare and distribute meals, and distributing Know Your Rights cards throughout South Bay San Diego, from San Ysidro to Chula Vista. Currently, we are collaborating with another organization to establish a dedicated disabled student space on campus, ensuring that disabled students feel empowered, supported, and have a strong sense of belonging at UC San Diego. Inspired by the values and movements of POC, disability, and queer community leaders from the 1960s and ’70s, we strive to build solidarity, provide direct support, and create community-driven solutions that make a tangible difference in students’ lives.', ''), NULLIF('blindsnakesdseg@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Blockchain at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Foster a community of blockchain enthusiasts and become the hub for blockchain education, research, and innovation at UC San Diego.', ''), NULLIF('basd@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Blossom Together at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Blossom Together is established for the expressed purpose of providing water, hunger, and medical relief to developing countries, specifically in Africa.', ''), NULLIF('blossomtgtatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Biomedical Engineering Society (BMES)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To provide students passionate about bioengineering and life sciences with opportunities to experience what the San Diego community has to offer, with an emphasis on serving those from underrepresented backgrounds. To nurture a philosophy of growth by providing a supportive space in which all members are given the ability to develop together, both personally and professionally.', ''), NULLIF('bmes@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('BLVCKOUT', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Our dance team aims to foster a community of passion, creativity, and cultural appreciation through the powerful and expressive styles of K-pop and girls'''' hip-hop. We strive to create a supportive space for dancers to grow together, share their love for music, and inspire confidence and self-expression in each other. With each performance, we celebrate the vibrant and energetic spirit of these genres, building a team that embraces inclusivity, artistry, and the joy of dance.', ''), NULLIF('snamgung@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Board Games Club, Long and Boring at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Board Games Club, Long and Boring at UC San Diego ( Long and Boring Board Games Club at UC San Diego) aims to provide an environment for students and community members of UC San Diego to play, discuss, and compete in strategic contemporary board games. This club seeks to introduce longer, strategy intensive board games to board gamers of all levels from experienced to novice. It is the club’s aim to host board game sessions on a weekly basis, communicating details of the events on Discord.', ''), NULLIF('longboardgamesclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Omega Campus Ministry', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('A diverse and thriving community of believers who strive to encourage one another daily and help each other follow Jesus, while also seeking to make Him known to others around campus. Connected to a Bible-based local and international church.', ''), NULLIF('kat017@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Boardgames and Boba @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To establish a welcoming campus organization dedicated to fostering a vibrant community of card game and board game enthusiasts. Our primary goal is to unite students through enjoyable gaming experiences while enhancing the social atmosphere by offering refreshing boba tea to all members, creating a relaxed and inclusive environment.', ''), NULLIF('boardgamesandboba@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Boogie Board Club @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The Boogie Board Club at UC San Diego is dedicated to building a fun and inclusive community centered around the joy of boogie boarding and beach life. Our mission is to bring students together to enjoy San Diego’s coastline — especially La Jolla Shores and Black’s Beach — through regular boogie boarding sessions, beach days, and social activities. When the waves are good, we’ll post on social media to notify members of spontaneous boogie boarding meetups. In addition to riding waves, our members will also enjoy hanging out at the beach together, playing games, relaxing, and listening to music. The club emphasizes both the thrill of boogie boarding and the laid-back social vibe of the beach, making it a space for beginners and experienced riders alike to connect and have fun. Everyone is welcome!', ''), NULLIF('boogieboardclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Phi', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('Alpha Phi is a sisterhood of outstanding women supporting one another in lifelong achievement.', ''), NULLIF('maddylilien@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpine Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To foster a community of people who enjoy spending time in the outdoors, where members can learn to enjoy and respect the mountains, share gear and expertise, train together, find adventure partners and plan trips and outings for rock climbing, mountaineering, backcountry skiing, trail running, backpacking or any other activity in the hills.', ''), NULLIF('alpineclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Alpha Omicron Pi', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('The object of Alpha Omicron Pi Women’s Fraternity shall be to encourage a spirit of Fraternity and love among its members; to stand at all times for character, dignity, scholarship, and college loyalty; to strive for and support the best interest of the colleges and universities in which chapters are installed, and in no way to disregard, injure, or sacrifice those interests for the sake of prestige or advancement of the Fraternity or any of its chapters.', ''), NULLIF('aoiiatucsd.vpoperations@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Amateur Radio Club at UC San Diego (KK6UC)', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purpose of the Amateur Radio Club at UC San Diego, licensed through the Federal Communications Commission (FCC) as KK6UC and officially affiliated with the American Radio Relay League (ARRL), is to provide UCSD students and staff with tools and opportunities to explore and enjoy the hobby of amateur radio. KK6UC is a member-focused club that can host licensing classes, teach different modes of radio, participate in contests, collaborate with other amateur radio organizations, and perform general experimental wireless communications. The club was founded on campus as WA6DOT (later KI6FTQ) in fall 1965 by Michael C. Ransom WB6KMH (now AI6II) and run for many years by Brian Kantor WB6CYT. The club has a new UHF repeater atop Atkinson Hall and is finishing installing a new Winlink gateway.', ''), NULLIF('kk6uc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Advertising Federation at UC San Diego (AdWave)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The American Advertising Federation at UC San Diego (Adwave) provides an educational and professional platform for students to develop their abilities for an advertising and/or marketing career. We compete nationally in the AAF National Student Advertising Competition. Adwave aims to inspire and bring together the brightest and most creative minds at UCSD.', ''), NULLIF('contact@adwaveatucsd.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Institute of Aeronautics and Astronautics', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To act as a pre-professional society to promote interest and encourage involvement in projects and activities in the fields of aeronautics and astronautics.', ''), NULLIF('aiaaatucsd@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Chemical Society Student Affiliates (ACSSA)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('To serve chemistry majors at UC San Diego by providing a friendly environment for the intellectual exploration of relevant industrial chemistry and chemical research topics. We aim to provide students interested in science with networking, outreach and volunteering opportunities that will help them define their goals, choose their career path and pursue their intended career.', ''), NULLIF('acssa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Institute of Chemical Engineers (AIChE)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To provide chemical engineering students with the most beneficial experience at UCSD through industry, career-building, and social events. We seek to promote academic, social, and professional growth for the chemical engineering community.', ''), NULLIF('aiche@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Medical Student Association', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('AMSA at UC San Diego is dedicated to providing valuable resources for pre-medical students here at UCSD, as well as presenting opportunities for involvement in the health-care community. We provide a wide variety of events from networking with physicians to community service opportunities to our annual health fair for the underserved San Diego community as well as socials for our pre-med members.', ''), NULLIF('amsa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Pacific Health Foundation @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The American Pacific Health Foundation (APHF) aims to establish a presence at UCSD to promote health education and provide free health screenings to underserved populations in San Diego. The goal of the organization is to advance health and wellness, particularly for vulnerable groups. These include screenings for chronic conditions like hepatitis B and C, diabetes, hypertension, and more, fostering proactive health management within the community. The organization focuses on raising awareness and addressing health disparities among underserved and vulnerable populations. By joining APHF, members will have the opportunity to contribute to impactful public health initiatives, gain hands-on experience in healthcare outreach, and develop leadership skills, especially through volunteer programs designed for students and community members. Establishing APHF at UCSD will provide members with the chance to participate in meaningful community service while also receiving valuable educational and professional development experiences in the health sector.', ''), NULLIF('volunteer@aphfsd.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Medical Women''''s Association', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The American Medical Women’s Association aims to foster an enriching environment for women in science and the medical profession. We hope to give back to the community through a variety of events spreading awareness about women’s health issues.', ''), NULLIF('amwaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Pharmacists Association APhA-ASP at UC San Diego SSPPS', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Our mission is to be the collective voice of student pharmacists, to provide opportunities for professional growth, and to envision and actively promote the future of pharmacy. We are dedicated to increasing health awareness and addressing the health concerns of the San Diego community.', ''), NULLIF('sspps.apha.asp@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Statistical Association at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('American Statistical Association at UC San Diego is a community for graduate students in the Math and Biostats Department specializing in statistics, designed to foster communication, collaboration, and mutual support. The organization also seeks to build meaningful connections with peers in economics, global policy, and data science, promoting interdisciplinary engagement.', ''), NULLIF('amstatstudents@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Animation Club', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('Our Animation Club is dedicated to fostering creativity, collaboration, and a deep appreciation for the art of animation. Our primary goal is to provide a platform for individuals who share a passion for animation to come together, learn, network and grow as artists and storytellers.', ''), NULLIF('animation@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Anime & Manga Enthusiasts at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To engender a supportive atmosphere in which students are introduced to Japanese anime in a community setting and enjoy weekly social activities throughout the school year, including our annual Animefest convention.', ''), NULLIF('animeclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Arab Heritage Leadership & Network at UCSD', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of this organization is to empower Arab students by fostering academic, cultural, and professional growth within an inclusive community. The club seeks to create a supportive environment where Arab and non-Arab students alike can celebrate their shared heritage, strengthen their leadership skills, and develop meaningful connections across campus. Through educational workshops, networking events, and community engagement, the organization promotes academic excellence, cultural understanding, and collaboration among students pursuing diverse career paths. By working closely with student organizations, cultural centers, and local community groups, the organization strives to build a unified network that uplifts Arab voices and cultivates pride, representation, and mutual support within the broader university community.', ''), NULLIF('Ahlan.at.UCSD@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Anthropology Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of this club is to be a hub for those interested in the field of anthropology and its various sub-disciplines as well as to educate its members, share resources, engage with the anthropology department, and to be a space to socialize.', ''), NULLIF('anthroclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Book Club', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purpose of this organization is to join together students who share a passion for reading. Through regular book discussions, events, and reading, we have 3 main goals. To engage critically with literature across genres, cultures, and organizations. To build a community by creating an inclusive, welcoming space where students can connect and expand their knowledge through shared ideas and discussions. And to encourage student engagement by hosting interactive meetings and maintaining a discord/instagram/other social media, which allows easy access and communication.', ''), NULLIF('bookclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('BPSHI (Bhagat Puran Singh Health Initative)', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our mission to empower communities through preventive care and educational measures relies on a universal standard of care and a culture of professionalism across all chapters, allowing us to engage respectfully and effectively with the communities we serve through health care.', ''), NULLIF('bpshi.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Argentine Tango Club', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('We aim to create a friendly atmosphere to promote and encourage Tango at UC San Diego and in the greater San Diego area.', ''), NULLIF('jbirnick@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('American Society of Mechanical Engineers @UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Our purpose is to bridge the gap between academic learning and real-world application by hosting workshops, industry events, and networking opportunities that prepare our members for successful engineering careers.', ''), NULLIF('asme@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Armenian Pre-Health Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('This organization is dedicated towards educating undergraduate students about different pre-health routes through hosting guest speakers (doctors, medical students, researchers, etc) and providing valuable tools and information to guide students through the processes of taking standardized tests, applying for professional health schools, and getting involved in research.', ''), NULLIF('armenianprehealthatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Armenian Pre-Law Student Association', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Creating an club/environment where students who are pre-law can gather to learn, communicate, connect, and help each other on their road to pre-law. This is specific to Armenian students, where we can share cultural values and connect with professionals in our field.', ''), NULLIF('aplsa.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Art Beat @ UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of the club is to provide Boys and Girls Club members with fun ways to learn about human anatomy, health, and medicine through creative, interactive endeavors. By merging art with science education, the club anticipates promoting curiosity, healthy lifestyles, and medical and scientific careers. Our goal is to create an interactive learning environment where participants are able to learn about the human body, express their creativity, and develop a greater appreciation of health and wellness in a fun way.', ''), NULLIF('artbeatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Armenian Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('To promote an understanding of the Armenian culture and foster awareness about issues of concern in the Diaspora and the Homeland to the campus community of UC San Diego.', ''), NULLIF('asa.atucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Architecture at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Architecture at UC San Diego strives to create an inclusive space for students to build their skills within the architecture/urban design field and meet other students interested in architecture/urban design, given that UC San Diego does not offer an architecture program.', ''), NULLIF('archatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Cognitive Science Student Association', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Welcome a rapidly growing undergraduate community of students interested in cognitive science into an inclusive environment with resources for academic growth, professional development, and social engagement, while directly involving the Cognitive Science faculty.', ''), NULLIF('cssa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('College Republicans at UC San Diego', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('The College Republicans at UC San Diego strive to enhance principles of the Republican Party in the UC San Diego community. We encourage the advancement of the Republican Party through aiding elections at all levels of government. Further we promote a forum for political discussion open to all viewpoints. We also seek to serve the UCSD community through various volunteer efforts. The College Republicans at UC San Diego aims to build leadership abilities in students to serve the community and party.', ''), NULLIF('CRsatUCSD@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('ColorStack @ UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('ColorStack’s mission is to increase the number of Black and Latinx Computer Science graduates that go on to start rewarding technical careers.', ''), NULLIF('colorstackatucsd@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Coalition PAC @ UC San Diego', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('Coalition PAC seeks to empower young people to engage in civic life, organize their communities, and support working-class voices in politics. In addition, Coalition PAC educates members and the community on issues of equity, justice, and democracy. Finally, Coalition PAC provides opportunities for members to develop leadership skills through activism, organizing, and political engagement.', ''), NULLIF('coalitionatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Colleges Against Cancer', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('At UCSD, Colleges Against Cancer is dedicated to uniting students, faculty, and the broader Triton community in the fight against cancer through advocacy, education, and fundraising. Our mission is to foster a campus culture of awareness and proactive engagement, empowering the American Cancer Society to contribute to groundbreaking cancer research and support services. Central to our efforts is the annual Relay for Life event, a powerful, community-driven initiative where participants join together to celebrate survivors, remember loved ones lost, and fight back against cancer. Through Relay for Life, we create an inspiring and supportive environment where individuals of all backgrounds can make a meaningful impact. By organizing this event and other related activities, we aim to raise vital funds for cancer research, promote cancer prevention strategies, and support those affected by the disease. Our ultimate goal is to build a future where cancer is no longer a threat but a challenge we have overcome together. Through our commitment, we seek to inspire hope, drive change, and leave a lasting legacy of compassion and action in the battle against cancer.', ''), NULLIF('cac.at.ucsd@gmail.com', ''), NULLIF('@cac.at.ucsd', ''), NULLIF('', '')),
  ('Comfort Tone', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Comfort Tone aims to provide a fun and safe space for students to sing and meet other fellow singers. We will be teaching singing techniques to students who are interested in a cappella! Everyone is welcome to join! No prior music background is required, and no auditions are either! If you''''re interested, you''''re more than welcome to just show up to a rehearsal any time! All of the info will be in our Discord server in the announcements channel (https://discord.gg/pdd3BXpJ).', ''), NULLIF('comforttone@ucsd.edu', ''), NULLIF('@comforttone.at.ucsd', ''), NULLIF('', '')),
  ('Combat Robotics Club', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('We build combat robots in the 1lb, 3lb, and 12lb weight classes. Combat robotics is a sport which was popularized by the television show battlebots where two robots have a three minute battle. The club will compete in various regional events hosted by organizations like NHRL or SCAR with the goal of being competitive while developing engineering skill sets in all fields of robotics, as well as soft skills in marketing, getting sponsorships, and building relationships with other robotics orgs/clubs.', ''), NULLIF('robots@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Company 157', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Company 157 is a undergraduate theatre organization at UC San Diego dedicated to increasing the opportunities and satisfaction of the undergraduate theatre community by providing positions/roles in playwriting, directing, stage management, design, acting, and production team members. Company 157 provides students opportunities through our dedication to producing new student works, putting on productions, educational workshops, and community events every year.', ''), NULLIF('company157@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chabad Graduate Student Association', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('Chabad Graduate Student Association fosters a vibrant Jewish community among graduate students by providing opportunities for connection, celebration, learning, and meaningful engagement with Jewish life throughout the year.', ''), NULLIF('Shcunin@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Competitive Programming Club at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purpose of the Competitive Programming Club at UC San Diego is to cultivate a thriving community of passionate problem solvers and algorithm enthusiasts. Our primary aim is to empower students with the knowledge, skills, and resources necessary to excel in competitive programming competitions at both national and international levels. For the top programmers in this club, the ultimate goal is to represent UCSD with pride and sportsmanship in the annual International Collegiate Programming Contest (ICPC). The journey begins with the Southern California Regional, continues through the North American Championship, and culminates with the aim of securing a medal at the World Finals. Along the way, we strive not only for victory but also to embody the spirit of camaraderie, teamwork, and integrity, proudly showcasing UCSD''''s excellence on the global stage. For general members of this club, our club provides an environment for students to challenge themselves, sharpen their algorithmic thinking, and develop problem-solving abilities that are not only valuable in programming contests but also essential in various aspects of computer science and software development. Additionally, competitive programming skills have been proven to significantly enhance performance in technical job interviews, making our club an invaluable asset in preparing for future career opportunities. Join us to embark on a thrilling journey of intellectual growth and competitive excellence.', ''), NULLIF('icpc@ucsd.edu', ''), NULLIF('https://www.instagram.com/icpcatucsandiego/', ''), NULLIF('https://https://icpcatucsd.github.io/', '')),
  ('Chaldean-Assyrian Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Chaldean-Assyrian Student Association is an organization that strives to unite all Chaldeans and Assyrians, as well as promote an understanding of the Chaldean/Assyrian culture, while also raising awareness about the concerning issues back in the motherland, Iraq. Every event or activity that CASA sponsors is in light of maintaining the culture, traditions, history, and the language of our people.', ''), NULLIF('casa.sdexec@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chalk It Up!', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Chalk it Up is a research seminar series aimed at providing a platform for graduate students to present their research in a low-stakes environment to make interdisciplinary research talks within the biological sciences more accessible to undergraduate students. Traditionally, research seminars are catered towards graduate students, postdocs and faculty, and are quite technical and nuanced, making them inaccessible to individuals without expertise in the domain of the presenter. Distinguished from current initiatives on campus, our seminar series adds the unique element of chalk talks, the nature of which requires talks to be more engaging, focused on core concepts, and digestible for a broader interdisciplinary audience.', ''), NULLIF('chalkitupatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Computer Science and Engineering Society', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Computer Science and Engineering Society provides opportunities to students beyond what they get in the classroom. The main motto of CSES is to create a passionate and diverse society of talented Computer Scientists and Engineers. We host company sponsored events to help you get internships and jobs, workshops to improve your technical skills, social events to build your network, and much more! We are open to all students with an interest in computing!', ''), NULLIF('cses@ucsd.edu', ''), NULLIF('cses_at_ucsd', ''), NULLIF('', '')),
  ('Challenger Research Journal at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Challenger Research Journal (CRJ) aims to further the access and representation of underrepresented students through the dissemination of research produced by scholars participating in the Undergraduate Research Hub programs at UC San Diego. The purpose of the CRJ is to organize, implement, and maintain a scholarly research journal that represents diverse perspectives across multiple fields of study.', ''), NULLIF('challenger@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Conlang Club at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Conlang Club exists in order to create a safe, social, and educational space for those interested in studying or creating constructed languages, or conlangs for short. Conlangs are languages constructed by a person or group, rather than a natural language, natlang for short, that develops through the course of human history. Conlangs can be spoken, written, signed, conveyed through music, or transmitted through other various modalities, as can natlangs. We aim to teach about various existing conlangs and how our members can construct their own conlangs on their own time. As the ultimate goal of our organization, we also strive to create a conlang as a collaborative effort with our club members, creating our own unique system of communication. As a Conlang Club tradition, our organization’s conlang shall be passed down through iterations of the club, undergoing evolution through the contributions of new members throughout the course of this organization’s existence.', ''), NULLIF('conlangatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chancellor''''s Scholars Alliance', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To promote service, academic development, leadership, and a sense of community among recipients of the UCSD Chancellor’s Scholarship through volunteer and community service opportunities, social events, and organized meetings.', ''), NULLIF('cscholarsall@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Construction Management Association of America at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Construction Management Association of America at UCSD is a chapter of the professional organization (Construction Management Association of America) that seeks to educate students about construction management and provide them with networking opportunities with industry professionals.', ''), NULLIF('cmaaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Conversation at UC San Diego', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('Conversation is an educational organization focused on embracing dialogue and inclusive environment about varying social and political issues. As an organization dedicated to acknowledge nuances, variation, and multifacetedness of every issue, we strive to find middle ground and compromise in every problem and topic we approach as well as acknowledge the importance of unique perspectives and ability to embrace them. Conversation believes that our differences are meant for learning and that we can respect and acknowledge one another even when we disagree with each other. From local and global political questions to societal and personal dilemmas, conversation is not an organization focused on one specific topic or set of topics, but rather a space to learn how to find agreements in important current issues, while embracing different points of view.', ''), NULLIF('conversationatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Cornerstone Community Consultants at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To provide local businesses consulting services at no cost. Consulting services include but are not limited to the following: financial, marketing, web design, strategy, and competitive analysis.', ''), NULLIF('cornerstoneatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Che Cafe', NULLIF('Cooperative', ''), NULLIF('Social', ''), NULLIF('The Che Cafe is a community space for both the greater San Diego community and the University of California, San Diego. We identify this space as "Do It Yourself" venue, vegan cafe, resource center for radical grassroots activists. Furthermore, we open this space to people who would like to add to the space while at the same time dismantle hierarchies. The Che Cafe Collective organizes numerous political and social events and is available as a vegan catering option for your events.', ''), NULLIF('info@checafe.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chem-E-Car Project', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Chem-E-Car Project, centered within the NanoEngineering department, aims to provide chemical engineering students with the opportunity to participate in a team-oriented hands-on design and construction of a small chemical-powered model car. In addition, it helps increase awareness of the chemical engineering discipline among the general public, industry leaders, educators, and other students.', ''), NULLIF('chemecar@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Costco Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of this student organization is to provide new and existing Costco enthusiasts a safe space to express shared interest in wholesale products!', ''), NULLIF('costcoclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Cheese Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of this organization is to help students connect with other students over their shared love for cheese. Cheese is an almost universally loved food that will attract people of all majors, standings, and years and provide a casual environment for people to interact. We will host many cheese-related events, such as "Brie-ze Thru Finals" study sessions and cheese movie night, in order to provide the perfect backdrop for students to mingle and make new friends.', ''), NULLIF('cheeseclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Crafted for a Cure at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Crafted for a Cure at UC San Diego is an organization dedicated to fostering student creativity while promoting breast cancer awareness and research. Student-led art workshops will be facilitated to support creative development, with products sold to fundraise for the cause. Opportunities for involvement in external awareness events will also be promoted to encourage engagement.', ''), NULLIF('cfacatucsandiego@gmail.com', ''), NULLIF('@CFACatUCSanDiego', ''), NULLIF('', '')),
  ('Chemistry Peer Advisory League (ChemPAL) at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Chemistry Peer Advisory League (ChemPAL) provides mentoring to undergraduate students studying Chemistry and opportunities for graduate students to gain mentorship experience. The group focuses on supporting first generation undergraduate students and other minority students who are majoring in chemistry, though is not exclusive to those groups. Matched graduate mentors with undergraduate mentees meet throughout the academic year. Group-wide events may also be hosted per annual interest, such as resume-review, literature-reading, and research introduction workshops, or social events.', ''), NULLIF('chempal@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Cross-Med Outreach at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of this organization will be to offer help to underrepresented areas of the U.S. and Mexico; it will also empower underrepresented students who are pursuing a profession in healthcare.', ''), NULLIF('mponcegarcia@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chemistry Student Selected Seminar Committee at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The purpose of this organization is to promote academic and professional connections through student-selected seminars in the fields of organic, inorganic, and materials chemistry. This group is focused on providing a space dedicated to introducing chemistry students to novel and exciting organic, inorganic, and materials research happening outside of UCSD. Through this organization, members have the opportunity to solicit nominations from various research labs within the Chemistry & Biochemistry department, prepare and plan an entire day for the student-selected seminar, and communicate with researchers from outside institutions.', ''), NULLIF('sssc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Cru at UC San Diego', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('Win, Build, and Send: turning lost students into Christ-centered laborers.', ''), NULLIF('zeblanco@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chess Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To promote an intellectually challenging and fun environment through the sport of chess with weekly friendly contests and occasional tournaments at UCSD.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chi Delta Theta', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('Chi Delta Theta emphasizes the importance of empowerment within the Asian American community while promoting the significance of embracing one’s identity. We accept individuals of all sexualities, races, religious backgrounds and genders. Furthermore, our purpose is to promote friendship, communication, cultural awareness and social activity among university students. We all stand as one to strive to further our goals both academically and socially.', ''), NULLIF('sdchidelts.president@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chi Omega', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('Chi Omega is a Panhellenic sorority forever committed to its founding purposes of friendship, personal integrity, service to others, academic excellence and intellectual pursuits, community and campus involvement, and personal and career development.', ''), NULLIF('ucsdxopresident@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chicanx/Latinx for Community Medicine', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Chicanos/Latinos for Community Medicine is a pre-health undergraduate organization that is committed to providing support, guidance, and education in our pursuit for higher education in medicine. Our beliefs are deeply rooted in providing better healthcare for our underserved communities through service, empowerment, and improving access to culturally competent health care.', ''), NULLIF('ccmatucsd@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Da Real Punjabiz', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('In the 24 years since DRP was formed, the team has performed at numerous competitions including Boston Bhangra, Bruin Bhangra, Dhol Di Awaz, VIBC, So-Cal Bhangra, and Best of the Best. Placing at many competitions, DRP has raised awareness of Punjabi culture not only in Southern California, but all over the United States. Through hard work, dedication, and determination, DRP hopes to continue to spread its love and respect for bhangra for years to come.', ''), NULLIF('darealpunjabiz@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Dance and Rhythm Game Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Dance and Rhythm Game Club seeks to provide a recreational, social, and competitive community for players of dance and rhythm games within UC San Diego and the greater San Diego area, specifically DDR, Pump it Up, and Dancerush Stardom. By providing an environment of social interaction, friendly competition, and in-game support, our goal is to give all of our members a positive gaming experience and the competitive drive to succeed in any gaming or non-gaming endeavor.', ''), NULLIF('tehoubi@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chinese American Student Association', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('It shall be the purpose of the Chinese American Student Association to promote Chinese and Chinese American culture and way of life by providing a comfortable environment and social network for members as well as all others interested in Chinese and/or Chinese American culture. The Chinese American Student Association is first and foremost a cultural organization, and although social events may result from the endeavor to achieve this purpose, they are not the priority. The Chinese American Student Association is a non-profit cultural and social-oriented organization striving to promote the Chinese and Chinese American culture as well as serving the above-mentioned purpose around UCSD campus and its surrounding environment.', ''), NULLIF('casaorg.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('CS foreach', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('CS foreach is a community outreach student organization that aims to alleviate issues of equity and access in regard to Computer Science education among the underserved communities of San Diego. In pursuit of this purpose, CS foreach takes an active role in supporting and initiating efforts to improve Computer Science education and cultivate mentorship between college students and K-12 students.', ''), NULLIF('csforeach@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('D.I.Y. Club @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('D.I.Y. Club is a social student organization dedicated to fostering an inclusive, welcoming environment for students with a shared interest in making crafts accessible and easily reproduced by the student populace.', ''), NULLIF('diyclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Darkstar', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Darkstar is a gathering of all those interested in Science Fiction and Fantasy. We are also a SF/F library of 6000+ books on campus, open to all students', ''), NULLIF('darkstar@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Data Science Student Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of our organization is to be a hub for all students interested in Data Science, regardless of their skill level or major. We want to provide resources and events where students can learn new data science tools and further their careers.', ''), NULLIF('ds3@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chinese Drama Club', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('To create a space for Chinese international students who are interested in drama acting and directing. We want to give students who are interested in drama a chance to show off their talents.', ''), NULLIF('sduan@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Deejays and Vinylphiles Club', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('The Deejays and Vinylphiles Club (DVC) at UC San Diego is a dynamic and educational student community that nurtures a passion for music and DJ culture. Our goal is to provide an enriching, inclusive, and fun platform for students to explore the art and history of DJing. We cover a range of music styles, genres, and techniques. Through our club, members can develop their own unique brand, learn about the business and technical aspects of DJing, and connect with like-minded peers. In addition to DJing, DVC offers hands-on workshops and experiences within the realm of event production, audio-visual practices such as visual jockeying and lighting, and more. Ultimately, DVC combines a passion for music with industry-level insights, offering students from all backgrounds the opportunity to flourish and express themselves through our shared love of music. No past experience required!', ''), NULLIF('dvcatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chinese Engineering Society', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The main purpose of Chinese Engineering Society (CES) at UC San Diego is to promote academic excellence and entrepreneurship among researchers and students in Chinese ethnicity. We aim to help maintain the diverse, inspirational environment in UCSD by providing opportunities in career network, professional development and academic communications, and furthermore encouraging the society members to contribute to the greater community through innovative ideas and projects.', ''), NULLIF('ces@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Deen Entrepreneur Network', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Where bold ideas meet fearless execution, we are a Muslim-founded startup club driven by imagination, innovation, and impact. At the intersection of faith, entrepreneurship, and creativity, we empower students from all backgrounds to build the next big thing. We’re not just a team, we’re a launchpad for the future, turning visionary thinking into real-world ventures. Join us as we reimagine what’s possible, together.', ''), NULLIF('deen.en.network@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chinese Dance Association', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('To enrich the student community of UCSD with the awareness of Chinese culture through the art of dance. Our purpose is to create an atmosphere of artistic and creative expression for everyone. CDA practices Chinese dance with emphasis on ballet techniques, but continues to keep the essence of Chinese culture in the pieces. In order to spread multi-cultural acknowledgment, CDA uses dance to celebrate the individual creativity and artistic collaboration.', ''), NULLIF('cdaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Daughters of Triton', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('To bring together and create a female-identifying a cappella group within the UCSD community. To provide students who are interested in a cappella music an outlet through performances and/or a group to belong to.', ''), NULLIF('the.dots@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chinese Students and Scholars Association', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The Chinese Students and Scholars Association (CSSA) is a non-profit organization at UC San Diego. Those UC San Diego students, postdocs, visiting scholars, and their family members coming from China are automatically eligible for membership. As one of the largest student organizations on the UC San Diego campus, CSSA serves as an important vehicle in enhancing mutual help and affinity among individuals of the local Chinese community.', ''), NULLIF('cssaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Chinese Global Community', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Chinese Global Community (CGC) is a student organization founded and operated by Chinese international students around the world. We strive to serve the students here at UCSD with the purpose of learning the Chinese culture, embracing the diverse background of the student community, and enhancing students'''' college life experience. With our cultural, lifestyle, and academic services, CGC hopes to bring an authentic Chinese experience to everyone through activities such as festivals, exhibitions, and programs.', ''), NULLIF('cgc.offical01@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Delta Delta Delta', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('THE PURPOSE OF DELTA DELTA DELTA shall be to establish a perpetual bond of friendship among its members, to develop a stronger and more womanly character, to broaden the moral and intellectual life, and to assist its members in every possible way. IT SHALL ALSO BE THE PURPOSE OF DELTA DELTA DELTA to promote and develop mutually beneficial relationships between the Fraternity and the colleges and universities where the Fraternity has established chapters, to develop qualities of unselfish leadership among its members, and to encourage them to assume, with integrity and devotion to moral and democratic principles, the highest responsibilities of college women.', ''), NULLIF('ddd.president.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Christians at UC San Diego', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To provide Christian fellowship at UC San Diego', ''), NULLIF('christiansatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('CIFG', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('At CIFG, we are committed to building an international community that welcomes chemistry graduate students from all social, cultural, and religious backgrounds. One major goal of CIFG is to help international graduate students to overcome language and cultural barriers by creating a supportive and welcoming environment. CIFG strives to create a sense of community to make every current, incoming, and prospective international student in the department feel recognized and supported. We aim to facilitate inter-cultural communication and encourage members to recognize the value of their own culture through community activities and social gatherings. Finally, we advocate for international students in the department and help them thrive academically and professionally through specific orientation activities, individualized mentorship, and career-building events.', ''), NULLIF('cifg@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Delta Gamma', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('The ladies of Delta Gamma pride themselves on their commitment to fostering high ideals of friendship, promoting educational and cultural interests, creating a true sense of social responsibility, and developing the finest qualities of character.', ''), NULLIF('dgpresidentatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Engineering Innovators & Entrepreneurs Club @UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Our non-profit is driven by a passion to transform the campus culture, shifting its focus beyond traditional career preparation to ignite a spirit of innovation, entrepreneurship, and bold venture creation. We’re here to cultivate a vibrant, nurturing community where students feel empowered to think creatively, tackle real-world challenges, and bring their ideas to life. By blending technical expertise with business savvy, they learn to build ventures that make an impact. We believe in more than just skill-building—our members become part of a dynamic network, leaving with not only practical abilities but also the courage, vision, and connections to pioneer what’s next. Together, we’re shaping leaders who don’t just adapt to the future but dare to invent it.', ''), NULLIF('eiec@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Dementia Art Therapy Alliance', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our mission is to harness the therapeutic potential of art to enhance the lives of individuals affected by dementia and other neurodegenerative diseases. We are dedicated to fostering creativity, connection, and emotional well-being through engaging artistic experiences that promote a sense of joy and mitigate the various symptoms of these conditions. By providing a safe and inclusive space, we aim to empower both participants and their caregivers, promoting self-expression and shared understanding. With a strong focus on collaboration, we strive to create a meaningful and lasting impact on the lives of those living with dementia and other neurodegenerative diseases.', ''), NULLIF('dataclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Engineering World Health', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Engineering World Health focuses on improving the state of global healthcare by spreading awareness, and developing members'''' interdisciplinary engineering skills required to engineer low-resource medical devices. Year-long, innovative projects addressing specific medical needs of underserved communities will be developed for the Engineering World Health design competition. We accept students from all majors and walks of life who share our passion for improving global healthcare.', ''), NULLIF('ewh@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('End Overdose at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our purpose is to Educate and Train individuals on how and when to intervene during a suspected overdose, make resources that prevent overdose related events accessible to everyone, equip individuals with preventative and responsive overdose tools, and to De-Stigmatize the conversation surrounding mental health, addiction, and overdoses.', ''), NULLIF('endoverdoseatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Delta Epsilon Mu', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Members of Delta Epsilon Mu are committed to serving the community by advocating health education and care, and through active participation in service activities, fundraising, and outreach programs. Members are given the opportunity to directly participate in health-oriented workshops and discussions, thereby attaining access to pertinent academic and career information through association with professors, advisors, career professionals, Alumni Members and fellow Active Members.', ''), NULLIF('dem.alphalambda@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Circle K. International', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Circle K International is comprised of university students who are responsible citizens and leaders with a lifelong commitment to community service worldwide. Through the three tenets of Service, Leadership, and Fellowship, Circle K strives to make positive impacts in our local community and the world. Circle K provides opportunities and resources for all students to become involved on topics and goals that they are passionate about.', ''), NULLIF('presidentckiatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Dermatological at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('As a branch for UC San Diego we aim to bring awareness to prevalent skin conditions, including sun damage and melanoma, within the San Diego community. We are committed to narrowing the health literacy gap surrounding these issues. Along with bridging the health literacy gap for these conditions. Another goal of the organization is to fundraise and support research for skin conditions. By joining our initiative, you will actively contribute to community outreach, fundraising efforts for dermatological research, and gain valuable insights into the field of dermatology.', ''), NULLIF('dermatologicalatucsd@gmail.com', ''), NULLIF('dermatologicalatucsd', ''), NULLIF('', '')),
  ('Climate Justice Coalition at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Climate Justice Coalition at UC San Diego aims to establish a broad network of pro-environmental organizations and individuals across San Diego in an effort to empower local climate action efforts, bring attention to existing initiatives, and facilitate collaboration between UC San Diego and broader San Diego stakeholders. The organization will foster consistent information sharing and provide opportunities for connection and partnership across constituents. CJC will further utilize this coalition to serve San Diego community members by educating and encouraging action on critical environmental and social justice movements.', ''), NULLIF('cjcatucsd@gmail.com', ''), NULLIF('@cjcatucsd', ''), NULLIF('', '')),
  ('Engineers for a Sustainable World', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('ESW at UC San Diego’s Vision: We envision a worldwide era of sustainability in which all communities cooperate to achieve lasting environmental, social, and economic prosperity. ESW at UC San Diego’s Mission: Our mission is to bring communities together to develop, implement, and share sustainable technologies and practices worldwide.', ''), NULLIF('esw@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Engineers for social good @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('This organization is dedicated towards providing a space for engineering graduate students to improve the social welfare, including developing union leaders, providing support and resources for worker-led movements, and promoting civic engagement for workers more broadly.', ''), NULLIF('engineers4socialgoodatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Design Co', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Design Co is a pre-professional student organization at UC San Diego that bridges the gap between designers and industry. Our mission is to cultivate a space that fosters opportunity and growth as an inclusive community of designers. By combining workshops, events, and other career growth opportunities, we’re tackling the challenges of breaking into industry head-on and building a strong design community while we''''re at it.', ''), NULLIF('designatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Design For America', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Design For America is a national organization that provides students with the resources, framework and experience to innovate meaningful solutions to the social challenges that affect us and our communities.', ''), NULLIF('dfa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Engineers Without Borders at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Engineers Without Borders at UC San Diego is a humanitarian organization dedicated to unite young adults from all paths of study and work towards projects that help people locally and globally. EWB-UCSD helps students develop skills including working in diverse groups, undertaking leadership roles and critical thinking. The goal of this organization is to create sustainable projects to help communities in need. Students gain the experience of applying technical knowledge to develop real solutions, working on innovative research, community development, and international outreach projects from Tijuana to Kenya.', ''), NULLIF('ewb@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Design/Build/Fly', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Design-Build-Fly (DBF) Competition requires student teams to design, fabricate, and demonstrate the flight capabilities of an electric-powered, radio-controlled aircraft that can best meet a given mission profile. The goal is a balanced design possessing good demonstrated flight handling qualities and practical manufacturing requirements while providing high vehicle performance. The contest provides a real-world aircraft design experience for engineering students by giving them the opportunity to validate their analytical studies. The competition is hosted by the American Institute of Aeronautics and Astronautics (AIAA) engineering society.', ''), NULLIF('dbf@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Club de Español at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Club de Español at UC San Diego is a nonprofit, student-run organization that aims to foster a welcoming community of Spanish-speaking students. The club will provide students with opportunities to enhance their Spanish-speaking skills and learn about Spanish-speaking cultures, while fostering friendships, participating in fun events, and organizing field trips. The club will emphasize the importance of Spanish in our sociopolitical context and connect with the local Spanish-speaking community.', ''), NULLIF('clubdeespanolatucsandiego@gmail.com', ''), NULLIF('@clubdeespanolatucsd', ''), NULLIF('', '')),
  ('Envisionaries @ UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('EnVisionaries hosts a maker studio space for makers and aspiring creators across campus to brainstorm and implement their ideas. We aim to educate students in Engineering, Visual Arts, design, and manufacturing processes, providing an environment to connect theory with practice. We host workshops to educate students on the usage of the maker studio machinery and community events to bring together creators!', ''), NULLIF('envisionaries@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Destino at UC San Diego', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('A leading Latino and Hispanic ministry. Our goal is to help make disciples of Jesus who will multiply their faith to help fulfill God’s great commission. Our ministry is about empowering leaders, building others up in their faith, understanding their cultural identity, and helping others reach their God-given Destino.', ''), NULLIF('destino.at.ucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Division 12', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('To unite dancers from teams all over campus through collaborating on a project team called Division 12.', ''), NULLIF('division12atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Eta Kappa Nu (HKN)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Eta Kappa Nu (IEEE-HKN) is the official engineering student honor society of IEEE and is dedicated to encouraging and recognizing excellence in IEEE fields of interest. HKN uniquely honors ECE, CSE, MAE, BENG, MATH-CS and DSC students who have achieved substantial success academically, possess leadership qualities and have noteworthy character. Members consist of students, alumni, faculty, and professionals who have demonstrated exceptional academic and professional accomplishments. At UCSD (Kappa Psi chapter), HKN hosts a diverse range of workshops and events to promote technical, professional, and academic development. Through these initiatives, we aim to inspire continuous growth and provide invaluable resources to help our members thrive in their respective fields.', ''), NULLIF('hkn.kappa.psi@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Every Child Plays', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our purpose is to create a safe, welcoming, and collaborative space for neurodiverse children to develop their social communication skills and make friends through participation in the team sports of basketball and soccer!', ''), NULLIF('everyplayerplays@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Doctors Without Borders Chapter @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our mission is to provide UCSD students with the opportunity to take part in the global movement in providing care to everyone who needs it - regardless of gender, race, religion, or political affiliation by supporting Médecins Sans Frontières/Doctors Without Borders, a non-governmental organisation who sends emergency medical teams into regions of the world where others don''''t dare to go. We seek devoted individuals who can help spread awareness about MSF''''s work and are keen on learning about their inherent practice of medical humanitarianism.', ''), NULLIF('msfchapter@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Exercise is Medicine at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('To raise awareness about exercise/activity as a means for contributing/ maintaining good health and preventing disease, while also promoting the interests and professional development of the multidisciplinary field of sports medicine; such as orthopedics, family medicine, and rehabilitation.', ''), NULLIF('eimatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Enhancing Cultural Healthcare Outreach (ECHO) at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Enhancing Cultural Healthcare Outreach (ECHO) at UC San Diego aims to unite the UC San Diego community by helping bridge communication gaps in medical environments. By providing multilingual resources, interpreter services, and competent support to help ensure fair access to medical information and care for patients from various backgrounds, ECHO is dedicated to supporting individuals who have limited access to healthcare in the San Diego area. The organization''''s primary goals are to raise awareness, participate in charitable efforts, and provide support for individuals who may not have consistent access to healthcare. These goals will be met through educational events, volunteer opportunities, fundraising activities, and community programs. Members of Enhancing Cultural Healthcare Outreach (ECHO) at UC San Diego will have the opportunity to build leadership experience, engage in meaningful volunteer work, and contribute to making medical care more accessible to a broad range of individuals. Additionally, members may participate in charitable campaigns and community engagement activities, allowing them to make a tangible difference while gaining practical exposure to healthcare outreach. Through these efforts, members will also be able to collaborate with medical professionals, improve communication in healthcare settings, and build cross-cultural understanding.', ''), NULLIF('echoatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Drag Club @ UC San Diego', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('With such a rich Drag Scene and culture around San Diego, it''''s about time we bring the energy to campus! Our main focus is: 1) to connect with up and coming Drag Royalty; 2) build a steady community with emphasis on student support and accessibility in the drag scene; 3) put on show stopping performances.', ''), NULLIF('DragAtUCSD@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('General Store Co-op, The', NULLIF('Cooperative', ''), NULLIF('Social', ''), NULLIF('The General Store Co-op is a non-profit, non-hierarchical, student-run collective designed to provide students with low cost goods including but not limited to food, school supplies, music records, comic books, video games, and more.', ''), NULLIF('gstorecoop@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Family, Career and Community Leaders of America (FCCLA) @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Family, Career and Community Leaders of America (FCCLA) @ UC San Diego is dedicated to empowering students by providing opportunities for personal development and preparation for adult life. Our organization seeks to strengthen the role of the family as a fundamental unit of society while fostering a greater understanding between youth and adults. Through cooperative action, we promote democracy within the home and community, encourage participation in global cooperation, and prepare members for the multiple roles they will assume in today''''s society. Additionally, FCCLA @ UC San Diego is committed to promoting Family and Consumer Sciences and related occupations, providing members with opportunities to make informed decisions, assume leadership responsibilities, and contribute positively to the community.', ''), NULLIF('fccla@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Duly Noted', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('To provide a supportive environment in which singers can enjoy and participate in musical activities, specifically vocally.', ''), NULLIF('dulynotedatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Geography Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To create a fun, friendly space where students can socialize, explore, and learn about the world around us. Through geography game nights and field trips, members will have the chance to engage in the diverse landscapes, cultures, urban spaces, and hidden history that make up San Diego, the U.S., and beyond.', ''), NULLIF('geographyclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('GeoGuessr Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Our purpose is to better the knowledge of students at UC San Diego by exploring advanced geographical concepts through the game of GeoGuessr. This will be done in a fun and welcoming environment where students can enjoy social interaction and bond over geography.', ''), NULLIF('TritonGeoGuessr@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Figma at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('As designers at UC San Diego, we''''re inspired by the idea that young people are the next generation of designers and innovators. Together with Figma, we’re building a future where every student has access to top-tier design resources and a supportive community that inspires them to create, collaborate, and innovate.', ''), NULLIF('figmaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Eastern European Society @ UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The goal of the Eastern European Society (EES) at UC San Diego is to bring together its Eastern European students and allow for them to form a sense of community among each other through informational sessions, socials, and cultural events! This club will help the Eastern European students build a sense of belonging on campus by meeting culturally similar students, allowing them to feel at home at school. The EES seeks to promote the unity of Eastern European students through various methods, which includes but is not limited to educational general body meetings, social activities, and informational social media posts. Members of the EES will benefit from socializing with students of the same or similar backgrounds, learn more about their own and surrounding cultures, and build lifelong friendships.', ''), NULLIF('eesociety.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('ECE Collaboration Board', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The goal of this organization is to host events catered to UCSD’s ECE students as well as to create an event called ECE Day in Spring 2026 designed to highlight all aspects of the ECE department to students through workshops, socials, and presentations. This organization will seek to promote different projects and ECE organizations during these events. Other collaborative events may be planned in the future.', ''), NULLIF('eceday@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('German Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('This is a club for people who want to practice speaking German or are interested in learning the German language. Students can participate in cultural events, social gatherings, language classes, and study abroad programs together.', ''), NULLIF('germanclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Figure Skating @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Figure Skating at UCSD is open to anyone who loves the ice - whether you''''ve been competing your whole life or you''''ve never put on a pair of skates before, this team has a place for you! Our team features two components: a competitive team and a social team. Competing, while fun, is not a requirement. In addition to skating activities, our club hosts many off ice socials, such as potlucks, craft nights, and our big-little program. And with many of our members being long time skaters and some even being professional coaches, it''''s a great opportunity for people who have never skated before but would love to give it a try!', ''), NULLIF('skateatucsd@gmail.com', ''), NULLIF('@skateatucsd', ''), NULLIF('', '')),
  ('Girls Who Run', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('An inclusive women''''s running group at UCSD! Our community is dedicated to embracing all running levels while empowering women and fostering unity among UCSD students through our shared passion for running. Join us as we support each other, build confidence, and create lasting connections on and off the track. Together, we''''ll celebrate our achievements and inspire each other to reach our goals.', ''), NULLIF('arvillarreal@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Five Millennia Orchestra', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('The purpose of our organization is to transmit Chinese traditional culture, to convene student artists, and to provide them with an opportunity to communicate, improve skills, collaborate and perform.', ''), NULLIF('FiveMillenniaOrchestra@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('First Generation Student Alliance', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The First-Generation Student Alliance (FGSA) aims to foster a supportive first-generation community at UC San Diego. The primary goal of FGSA is to provide a welcoming and inclusive space where first-generation identifying students can connect, share experiences, and find resources to navigate their academic, professional, and personal journey successfully. FGSA seeks to empower students to embrace their first-generation identity by offering a network of support that addresses their unique challenges and needs. The organization will focus on building the first-generation identity at UC San Diego by creating alliances within the campus community.', ''), NULLIF('fgsa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('ECE Undergraduate Student Council', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The ECE Undergraduate Student Council (ECE USC) is the voice of Electrical and Computer Engineering (ECE) undergraduate students at UC San Diego. Through community, events, and leadership, the council strives to provide students with opportunities and enact change within the department and campus at large, building a stronger community for current and future engineers. ECE USC is committed to carrying out ECE’s mission statement of educating tomorrow’s technology leaders.', ''), NULLIF('eceusc@ucsd.edu', ''), NULLIF('eceusc_at_ucsd', ''), NULLIF('', '')),
  ('Global Dental Brigades (GDB)/@ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Global Dental Brigades (GDB) @ UC San Diego aims to improve dental health in underserved communities by providing essential dental care and education. GDB offers education on oral hygiene practices, such as proper brushing and flossing techniques, which is a key component, as well as focusing on building or improving dental clinics to ensure sustainable access to care. Through these efforts, Global Dental Brigades strives to enhance the overall well-being of the communities they serve.', ''), NULLIF('gdb.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Eclipse Analytics @ UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Eclipse Analytics is a student-led sports club committed to educating members on the art and science of sports analytics. By combining qualitative methods, such as analyzing game strategies and performance, with quantitative approaches like developing machine learning models, we empower students to gain comprehensive insights into athletic performance, team dynamics, and strategic decision-making.', ''), NULLIF('eclipse@eclipseanalytics.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Ecology, Behavior and Evolution Club at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Ecology, Behavior, & Evolution Club at UC San Diego seeks to provide students interested in ecology, behavior, & evolution areas with a sense of community and opportunities to build their professional capacities. Community events include hikes, lab/natural history museum tours, conservation & restoration events, camping trips, and bonfires. Professional opportunities include career panels, mixers with grad students in the EBE Department, workshops, etc. EBE Club of course emphasizes students from the Ecology, Behavior, and Evolution & Environmental Systems/EBE majors, but welcomes all students who take an interest in these amazing fields to join us!', ''), NULLIF('ebeclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Global Medical Brigades @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Global Medical Brigades (GMB) is a secular, international network of University clubs that travel to developing countries to perform health care in communities without access to medicine otherwise. GMB delivers a holistic model for sustainable health through rigorous needs assessments, sponsoring referrals to those with needs beyond our capacity, keeping accurate electronic patient records, and working to improve the water and overall public health infrastructures of the villages we serve.', ''), NULLIF('gmbatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Floating Doctors at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Floating Doctors at UCSD is a student-run organization dedicated to improving healthcare access for underserved communities in Panama, while providing students with meaningful global health, clinical, and leadership experiences. Our mission is to support the work of the international nonprofit Floating Doctors by fundraising, raising awareness, and sending UCSD student volunteers on medical service trips. Through this club, members will gain opportunities to: -Contribute to sustainable healthcare initiatives in resource-limited settings. -Participate in fundraising and community outreach efforts to support patient care abroad. -Learn about cultural humility, global health equity, and ethical volunteerism. Develop leadership, teamwork, and organizational skills through planning, service, and collaboration with other chapters. Ultimately, our purpose is to empower UCSD students to engage in hands-on service, expand their global health education, and make a tangible impact on vulnerable populations, while fostering a strong sense of community, compassion, and responsibility among future healthcare leaders.', ''), NULLIF('floatingdoctorsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Global Medical Missions Alliance', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('Part 1. Leave a positive and profound impact for Christ by guiding and equipping students with training and networking opportunities so they may serve as effective healers and ministers of Christ’s love. Part 2. Foster a unique community and fellowship among peers and mentors committed to medical mission and healing ministry. Part 3. Become the next generation of healthcare professionals “poured out as a drink offering” for the Gospel. Part 4. To provide various Medical Mission opportunities around the globe with the main focus, to further God’s kingdom.', ''), NULLIF('gmmaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Flying Sams at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Flying Sams is a medical service club at the University of California, San Diego in association with the non-profit service organization, The Flying Samaritans Inc. We are dedicated to providing free medical services to the underprivileged people of Mexico through a clinic staffed entirely of volunteer physicians, nurses, medical and pre-medical students.', ''), NULLIF('fsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Education Studies Student Association (EDSSA)', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Education Studies Student Association (EDSSA) at UC San Diego strives to create a community for UCSD students with interest in the field of education through informal academic support, social events, and professional networking and mentorship. It aims to provide students with opportunities to form social and professional connections with other EDS-associated students, and provides pathways to partnering with other organizations that offer volunteer or activism opportunities related to education.', ''), NULLIF('edssa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Following the Light Student Ministry', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('Following the Light Student Ministry is a Christ-centered community where students explore and share the Word of God in depth. We desire to help every student, whether seeking faith or growing as a believer, build a genuine and personal relationship with God. Rooted in Scripture, we encourage open discussion, honest questions, and spiritual growth together. Our vision is to see students transformed by the light of Christ and equipped to reflect His love and truth on campus and beyond.', ''), NULLIF('jieyelin@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Graduate Bioinformatics Council', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The objective of the Graduate Bioinformatics Council (GBIC) shall be to represent and advance the career, community, and outreach interests and objectives of the students of the Bioinformatics and Systems Biology (BISB) and Biomedical Informatics (BMI) PhD programs, and to participate in volunteer educational events at local, national, and international levels.', ''), NULLIF('gbic@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('EERI Student Chapter', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Our mission is to promote earthquake safety awareness among students, working alongside the San Diego Professional Chapter, providing networking tools with practicing professionals and nationally, and inspire students to engage with the necessary topic of earthquake engineering.', ''), NULLIF('eeri@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Food Cooperative at UC San Diego', NULLIF('Cooperative', ''), NULLIF('Social', ''), NULLIF('The Food Cooperative at UC San Diego is a student-run collective store committed to serving hot vegan food and alleviating basic needs insecurity on campus. Open Monday through Friday at the Old Student Center, the Food Co-op serves cheap meals and hosts a community shelf with free resources for students.', ''), NULLIF('food.cooperative@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Graduate Christian Fellowship', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('We are a group of UC San Diego graduate students, post-docs, and others who gather together to fellowship, worship, and learn what it means to be followers of Jesus in an academic setting. We provide a spiritual relief from the challenges and rigors of academia. With God’s blessing, we maintain a thoughtful and welcoming community with the intent to provide spiritual support and sustenance.', ''), NULLIF('gcfatucsd@gmail.com', ''), NULLIF('@gcf.atucsd', ''), NULLIF('', '')),
  ('EleFilm', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('The main goal of this filmmaking organization is to provide an inclusive platform for individuals to participate in the art of filmmaking. Our focus is on collaboration and learning through production of short films, without any barriers to entry. We welcome anyone with a passion for film and ideas to join us for filming and group learning. Through sharing our deep passion for film, we can express our thoughts and create more immersive opportunities. In addition, we will organize and participate in film festivals that can convey influential ideas and promote social change. Ultimately, our aspiration is for every member of the organization to discover their own personal definition of film.', ''), NULLIF('elefilm.sd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Egyptian Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Egyptian Student Association will serve as an open and safe space for students and faculty on campus to learn more and embrace the deep and rich Egyptian culture. It will serve as a key means of connecting Egyptians on-campus, in addition to helping to bring more awareness and inform others of the beauty of Egyptian culture.', ''), NULLIF('esaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Food for the Future', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of Food for the Future is to host monthly food fundraisers that not only raise money but also introduce students to different medical organizations and nonprofits, supporting their work and creating awareness. We also introduce students to different jobs in medical organizations.', ''), NULLIF('aupamhamran@yahoo.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Graduate Student Volleyball Party (GSVP)', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Allow graduate students to connect and take a break from research/classes by playing beach and indoor volleyball twice a week.', ''), NULLIF('gsvp-g@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Graduate Women in Physics', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('This group exists to discuss the challenges members encounter as women and other gender minorities in physics. We also plan large scale social/professional development events that promote gender minority voices in Physics and foster connections between gender minorities in Physics and related STEM disciplines. We meet periodically to discuss everything from how to find an advisor to life after grad school to just chatting over coffee.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Emergency Medical Services at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Emergency Medical Services at UC San Diego is organized exclusively to educate students and staff through CPR certification and training, provide information and resources for individuals, and to positively impact the health and safety of the UCSD community.', ''), NULLIF('emsatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Graphite', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Graphite is an undergraduate chemistry-focused journal at the University of California San Diego. The organization was established in 2021 to provide a platform for aspiring chemists to showcase their research and communication skills in an accessible and digestible format. Graphite is both an online and print journal split into four sections: news, research, features, and opinion. The journal aims to offer fresh insights into a variety of chemistry-related topics inside and outside of UC San Diego while providing a forum for aspiring writers under the guidance of trained student leaders. Graphite''''s in-house graphic design team collaborates with article editors to create effective visual representations that emphasize key scientific concepts in the article. At the end of each academic year, selected articles and artwork are featured in the annual print publication, which gets distributed to the faculty and students in the Department of Chemistry and Biochemistry.', ''), NULLIF('graphite@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Frequency', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Frequency is the only tenor-bass a cappella group at UC San Diego. Founded in 2008 and completely student-run, Frequency is committed to promoting a cappella music, providing entertainment through public and private performances, fostering long-term relationships with the a cappella community on and off campus, and providing its members with leadership opportunities.', ''), NULLIF('frequency@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Friends of Dialysis @UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Friends of Dialysis (FOD) aims to create a welcoming and comforting environment for dialysis patients and the community through meaningful outreach and support. The club seeks to host events at dialysis centers and facilities, recognizing that patients with kidney disease often face not only physical exhaustion but also mental and emotional strain. By involving undergraduate students and volunteers, FOD provides opportunities to give patients encouragement and companionship during their treatment journeys. In addition, the organization collaborates with healthcare facilities and partner organizations to advance its mission of fostering belonging and care. Beyond direct patient support, FOD also works to raise awareness about kidney disease, dialysis, and the importance of preventative healthcare. Members gain opportunities to both learn about kidney health and actively contribute to awareness efforts. Another key initiative includes assembling supportive kits for patients in dialysis centers, offering comfort and practical aid as part of the club’s commitment to compassion and community support.', ''), NULLIF('friendsofdialysisatucsd@gmail.com', ''), NULLIF('friends.of.dialysis.at.ucsd', ''), NULLIF('', '')),
  ('Grays & Hues Zine', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('Grays & Hues Zine seeks to introduce emerging writers and artists to the self-publishing scene. We intermarry literature, writing, photography, visual design, and mixed media with the arts and crafts through our DIY bookbinding process. Our content provides marginalized voices an opportunity to create self-representation and cultivate dissent against mainstream culture. As a zine catered to the college experience, we foster a space for young creatives to navigate adulthood and identity and critique hustle culture. However, each issue will follow different aesthetics, engaging artists to approach the facets of our themes in new ways.', ''), NULLIF('grays.n.hues@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Fusheng Chinese Drama Troupe', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('We are a Chinese Drama Club that has over 100 active club members, produce at least 1 theater festival each quarter. Providing a workspace for students who are interested in Drama acting or stage designing in Chinese.', ''), NULLIF('qiy015@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Green New Deal at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('To advocate for climate action. To organize students and the campus community at large around activism targeted mainly at demanding that UC San Diego: 1) Teach students about the climate crisis and climate justice. 2) Specify carbon neutral goals and meet them by 2025. 3) Build a UC-wide Green New Deal', ''), NULLIF('greennewdealatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Grey Matter Project, The @ UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Grey Matter Project chapter at UC San Diego aims to inspire and mentor high school students by fostering curiosity and education in the field of neuroscience. Through interactive learning, lectures, and community engagement, we seek to close the neuroscience education gap and empower students to explore the brain and nervous system while building confidence and interest in future careers in medicine and science.', ''), NULLIF('greymatterproject@yale.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Gender Minorities in Bioengineering', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Gender Minorities in Bioengineering at UC San Diego is a non-profit, student-run organization committed to advancing the academic and professional careers of women and other marginalized genders in bioengineering at the undergraduate, graduate, and post-doctoral levels. Our mission is to promote diversity within the scientific community by facilitating events that strengthen the involvement of women and other marginalized genders in STEM. We generate opportunities to best serve the interests of our members and the broader community so that we can shape a more diverse future.', ''), NULLIF('gmbe@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Groundwork Books Collective', NULLIF('Cooperative', ''), NULLIF('Social', ''), NULLIF('A political collective and non-profit bookstore that provide progressive literature and camaraderie for students and activists who hope for changes and a better world.', ''), NULLIF('groundworkbookscollective@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hands of Hope', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The goal of Hands of Hope is to provide aid to the community, including the homeless, disabled individuals, hospitals, and more. Our club is dedicated to spreading hope and love during challenging times and bringing joy into people''''s lives.', ''), NULLIF('handsforhope@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hawaii Club @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of the Hawaii Club will be to provide a place for students both from Hawaii and outside of Hawaii to connect and socialize with each other. The club will also be focused on spreading knowledge and awareness on different aspects of Hawaiian culture through engaging in various hands-on activities. For example, lei making, making spam musubi, dancing hula, and of course, an end of the year lu''''au. The goal of the club is to have a community on campus that shares the aloha spirit with all of our members and throughout UCSD.', ''), NULLIF('hawaiiclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('HDSI Student Council', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The HDSI Student Council serves as the governing body advocating for the undergraduate and graduate students pursuing academic degrees at HDSI. This includes but is not limited to representing HDSI students at internal and external events, evaluating funding initiatives for students and student organizations affiliated with HDSI, and liaising with student organizations. The HDSI Student Council will be the presiding collective voice for HDSI student populations to address the needs and concerns of its student body to HDSI and campus faculty, staff, and leadership.', ''), NULLIF('hdsistudentcouncil@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Healing Hands at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Healing Hands at UC San Diego aims to improve the access to healthcare in the unhoused and underserved communities and to provide students opportunities with hands-on medical related events around San Diego; to inspire and help teach the medically underserved how to advocate for mental health and medical services. The ultimate goal is to create an environment of learning and awareness in our members in order to build a bridge of understanding and assistance towards the unhoused and at-risk population.', ''), NULLIF('healingh@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Health and Anti-Recidivism Project (HAARP)', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Operating within an intersectional restorative justice framework, Health and Anti-Recidivism Project (HAARP) is a non-profit organization striving to combat rising recidivism rates by humanizing and promoting physical/mental wellness among those impacted by incarceration (the prison system). Through mentorship programs for impacted children, education + reproductive health advocacy for the incarcerated, and more, HAARP aims to empower by fostering health literacy, education, and community.', ''), NULLIF('haarpatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Health and Medical Professions Preparation Program (HMP3)', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The Health and Medical Professions Preparation Program (HMP3) at UC San Diego provides undergraduates with enriching experiences that will enhance their preparation for admission into professional school in the health professions. Through collaborations with the UCSD School of Medicine, faculty, HealthBeat, community health care providers and others, HMP3 provides members with stimulating experiences designed to expand the mind and increase qualifications for entry into the health professions.', ''), NULLIF('hmp3atucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Health Link', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Our mission is to empower students with the tools, experiences, and connections to drive healthcare innovation and improve patient care around the world. As a student-run MedTech incubator at UC San Diego, HealthLink unites students from engineering, medicine, business, and design to tackle real-world challenges at the intersection of healthcare and technology. Through ideation programs, career fairs, panels, networking events, and collaborations with our network of partners, we create pathways for students to grow, launch into accelerators, and build impactful careers in healthcare innovation.', ''), NULLIF('healthlink@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Health Disparities Initiative', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Established in commemoration of Thurgood Marshall College''''s 50th anniversary, the Health Disparities Initiative (HDI) at UC San Diego empowers students, staff, faculty, alumni and community partners to enact tangible change in their communities through public health education and service. HDI seeks to address and attend to health disparities within the San Diego area and beyond through meaningful collaborations, acts of service, and the publication and distribution of our quarterly zine, ultimately working toward long-lasting change in our communities. Through HDI, members interested in the intersection between public health and social justice have the opportunity to make a real difference by working on projects of their own design and/or contributing to the projects of others in the community to address health disparities.', ''), NULLIF('hdi@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Health, Law, and Business Society @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('This organization was established to bridge the gap between curiosity and the intersection of health, law, and business. These fields are deeply interconnected in ways that are often overlooked, and many students interested in one may also be drawn to the others. Whether the focus is healthcare policy, entrepreneurship in biotech, or legal frameworks in public health, exploring the overlap among these disciplines offers significant value. Many students are interested in multiple career paths or remain undecided about their future direction. Finding opportunities that encourage interdisciplinary exploration without requiring a firm commitment to a single field can be challenging. This organization provides a supportive space for students to engage with diverse interests, explore real-world applications, and connect with peers and professionals working across these sectors. Through events, panels, workshops, and networking opportunities, the organization aims to expose students to a broad range of perspectives and career possibilities within health, law, and business. Prior experience in any specific area is not required, and we know many search for an opportunity to gain more experience. We encourage members to come in with a genuine interest in learning and understanding the connections among these fields. By fostering meaningful engagement and providing resources, this organization supports students in exploring their options, building professional networks, and gaining insight into interdisciplinary career pathways.', ''), NULLIF('hlbsatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Healthcare Professions Mentorship Programs', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Pursuing a career in healthcare begins with a pre-health education experience and is furthered by mentorship and advice throughout this experience. Our organization seeks to aid all paths to health care through programs put on by our Peer Mentorship UCSD is known as for its strong emphasis in the sciences, and many students aim to pursue careers in the health sector. But there is more to health than getting an MD, PharmD, or DDS. There are dozens of other careers, our SEARCH committee is here to let you know about! Additionally, the Peer Mentor Program is designed to help pre-health undergraduates navigate life at UCSD as a pre-health student both academically and socially. By fostering meaningful, long-lasting relationships between different levels of the student body, the goal of the program is to ultimately increase the number of UCSD pre-health majors admitted into their desired health professional school.', ''), NULLIF('hmp3hpmp@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Healthy Skin Initiative (HSI)', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Healthy Skin Initiative (HSI) strive to educate the student community about the importance of skin health and empower them to take ownership of their own skin through guest speaker workshops and infographics. Through these events, we hope to bring light to and cultivate an awareness of the intersections between health and social issues surrounding skin.', ''), NULLIF('hsiatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hearts For The Homeless San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Hearts for the Homeless (H4H) San Diego is an organization committed to informing one of the most vulnerable populations in our nation about their cardiovascular health and overall well being by providing free blood pressure screenings, informative heart health education events, and clinical outreach opportunities for students who wish to contribute to our effort.', ''), NULLIF('h4hatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Helix AI', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of Helix AI is to function as a high-intensity, founder-led pre-incubator at UC San Diego. Our primary mission is to bridge the critical gap between technical AI innovation and viable market strategy. We are structured to unite and empower two essential student profiles: "Builders" (AI-related students, engineers, researchers) and "Strategists" (Rady business students, marketers, and designers). Our organization achieves this purpose through three integrated pillars. First, the Helix Venture Studio is our core incubation arm. It provides project teams with tangible resources—including GPU compute, strategic advising from experienced AI founders, and a structured framework—aimed at developing ventures competitive for top-tier incubators like YC, Hsix, and The Basement. Second, Helix Media Labs is our content and education division. It produces high-quality public content on AI entrepreneurship, product analysis, and advanced knowledge management, serving to educate our members while acting as a practical training ground for marketing and content talent. Third, the Helix Atlas Project is our long-term, organization-led technical initiative to build a comprehensive, multi-lingual database of existing AI products. This provides a real-world engineering challenge and generates critical market intelligence for our venture teams. Collectively, these pillars create a robust ecosystem designed to manufacture launch-ready AI ventures and valuable entrepreneurship experiences for club members.', ''), NULLIF('xpi@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hedge Fund Club', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of our student organization is to provide a dynamic platform for aspiring finance professionals to develop their expertise in equity research and portfolio management. Our club aims to empower students with the knowledge, skills, and practical experience needed to excel in the world of finance and contribute positively to the investment industry. Here''''s a breakdown of our primary objectives and purposes: Learning and Skill Development: We strive to cultivate a strong foundation in equity research and portfolio management by offering educational resources, workshops, and access to industry experts. Our members will gain a deep understanding of financial markets, investment strategies, and analytical tools. Hands-On Experience: We provide students with real-world, hands-on experience in conducting equity research and implementing portfolio management strategies. Through simulated investment activities, members will have the opportunity to apply their knowledge in a practical setting. Professional Development: We are dedicated to preparing our members for successful careers in finance. We offer networking opportunities, resume-building workshops, and access to internships or job placements within the financial industry. Collaborative Environment: We foster a collaborative and inclusive community where members can exchange ideas, collaborate on research projects, and learn from each other. Teamwork is a fundamental aspect of our organization, mirroring the collaborative nature of the finance industry. Ethical Investment Practices: We emphasize the importance of ethical and responsible investing. Our organization promotes sustainable investment strategies and encourages members to consider environmental, social, and governance (ESG) factors in their analyses. Industry Insights: We invite guest speakers from the finance industry, including professionals from hedge funds, asset management firms, and investment banks, to share their insights and experiences with our members. This exposure enhances our members'''' understanding of industry trends and best practices. Competitions and Challenges: We organize and participate in equity research and portfolio management competitions, giving members the opportunity to apply their skills in a competitive environment and gain recognition for their achievements. Community Outreach: We believe in giving back to the community. Our organization may engage in philanthropic activities or financial literacy initiatives to share our knowledge and expertise with the broader community. In summary, our pre-professional student organization for equity research and portfolio management is dedicated to empowering students to become proficient finance professionals. Through education, practical experience, and professional development, we aim to equip our members with the tools they need to succeed in the investment industry while upholding ethical standards and fostering a collaborative learning environment.', ''), NULLIF('dykan@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Himalayan Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Himalayan Student Association focuses on creating a welcoming community for Himalayan individuals as well as those interested in Himalayan culture. Our purpose is to promote cultural awareness of the Himalayan region and connect UCSD students to celebrate an array of identities, cultures, and languages through fun events, educational discussions, and community service.', ''), NULLIF('hsa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hermanas Unidas de UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Hermanas Unidas is a non-profit organization that provides undergraduate, graduate, and professional leadership opportunities and resources to Latinx students by participating in academic excellence, community service, and collegiate networking events to foster Hermandad.', ''), NULLIF('lmsantillan@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hmong Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The main purpose of Hmong Student Association is to create a strong community with the people around us. Hmong Student Association is a community that strives to educate all learners about the culture of the Hmong people. We would teach the history and traditions of the Hmong people. Although this organization is primarily cultural to the Hmong, we do encourage students from a different background to explore our organization and enjoy our engaging socials, events, performances, and celebrations.', ''), NULLIF('tevang@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hope Epsilon Lambda Pi', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The goal of Hope Epsilon Lambda Pi is to educate people about hospice programs and help the hospice community through volunteer work. This organization seeks to encourage individuals to become more active in helping hospice programs and enhancing the experience for hospice patients as they go through a vulnerable moment in their lives. Organization members will be able to accumulate community service hours by being a part of this organization and participating in volunteer work such as fundraising, creating care packages, and writing letters among other things. We will be supporting several hospice programs to increase awareness about the hospice community and directly help them, including Anchor Health which principal members have been previously involved with.', ''), NULLIF('hopeepsilonlambdapi@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hong Kong Student Union', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The goal of the organization is to create a platform to fuse the traditional Hong Kong culture with the new-fangled Western ideals. Our vision is to promote the welfare of the Cantonese-speaking student body. We hope to promote cultural awareness of Hong Kong and raise cultural diversity at UC San Diego. We also provide a social environment for those who want to stay in touch with the Hong Kong culture as well as those who want to find the sense of belonging in the States.', ''), NULLIF('hksu.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hopkins Sax Jam', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Hopkins Sax Jam is an all-saxophone performance ensemble. We strive to promote the art of saxophone through public performance at UCSD and in the San Diego community and to support other saxophonists in further improving their musicianship and technique by sharing saxophone knowledge and skills with each other. Members of this organization benefit by continuing to improve their saxophone playing and developing strong relationships with fellow saxophonists.', ''), NULLIF('hopsax@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Hope Presbyterian Church', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('For college members of Hope Presbyterian Church to meet together on campus', ''), NULLIF('hopepresbyteriansd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Houselessness Service Club at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of this organization is to raise funds for our local houseless community and share community resources such as food, clothes, and hygiene products with those in need. Additionally we aim to build connections with our local houseless community, organizations that support them, and the students at UCSD to make this a community relational process.', ''), NULLIF('hsoatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Homeless Health and Empowerment Across Learning (Homeless HEAL)', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of Homeless HEAL is for UC San Diego students to identify and research the unique health challenges surrounding homelessness in San Diego, design an educational curriculum addressing those topics, and teach this information in presentations with partnering organizations that provide services for individuals experiencing homelessness and housing insecurity. Homeless HEAL aims to improve health outcomes in San Diego by empowering this community through health-based education and more informed health decision-making . This organization provides service and leadership opportunities to all members, known as student educators.', ''), NULLIF('homelessheal@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Iaido at UC San Diego', NULLIF('Martial Arts/Combatives/Weaponry', ''), NULLIF('Sports', ''), NULLIF('Iaido at UC San Diego seeks to promote awareness and preservation of the Muso Jikiden Eishin-Ryu branch of Japanese swordsmanship.', ''), NULLIF('iaido.sandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Human Development Student Association', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Human Development Student Association, or HDSA, is an undergraduate organization that focuses on expanding awareness about the Human Developmental Sciences Major/Minor on campus as well as provide students in the Human Developmental Sciences resources to aid them in learning, and gaining research and career advice. Additionally, HDSA aims to create a community in which students in the Human Developmental Sciences major/minor will be able to build meaningful connections with staff, faculty, and peers.', ''), NULLIF('hdsaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('IEEE EMBS @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Engineering in Medicine and Biology Society (EMBS) at UCSD is dedicated to promoting the application of engineering sciences and technology to medicine and biology by fostering interdisciplinary education, professional development, collaborative research, and outreach activities. The organization is committed to improving access to and inclusion in engineering research and applications to students, scientists, and the public at large.', ''), NULLIF('ieeeembs@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Human Powered Submarine', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Human Powered Submarine (HPS) designs and builds a fully-flooded human-powered submarine to compete against other universities. Our mission is to preserve and innovate existing approaches to marine engineering, specifically those relevant to the propulsion, guidance, and manufacturing of submarine design. We offer our members hands-on engineering skills that are not easily acquired in the classroom environment, as well as opportunities to develop engineering intuition, team communication skills, and critical thinking.', ''), NULLIF('submarine@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Ikigai Dance and Company', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('We at Ikigai Dance and Company, strive to provide a safe space for all dancers, just starting out or continuing, to create movement and art. We will learn numerous dance styles like jazz, contemporary, jazz funk, hip-hop, etc. through combinations and everyone will have an opportunity to choreograph a piece(s) for our end of year showcase during spring quarter.', ''), NULLIF('ikigaidanceandco@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Industry Pharmacists Organization (IPhO)', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('IPhO is the organization whose pharmacist members are universally recognized within the pharmaceutical industry as being the most professionally equipped to contribute to the development, commercialization, promotion, and optimal use of medicines. IPhO National Student Members are recognized as the best prepared among all student pharmacists to pursue pharmaceutical industry-focused career opportunities. National Student Members have an excellent working knowledge of common industry pharmacist roles and key pharmaceutical industry driving forces, as well as an understanding of the skills and experiences necessary to become a successful industry pharmacist.', ''), NULLIF('iphoatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Interfraternity Council', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('The purpose of this body shall be to govern the member fraternities, to promote intellectual, philanthropic, fraternal and social values of the fraternities at the University of California, San Diego, and to maintain cooperation between these fraternities, their respective international headquarters, alumni, and the surrounding community.', ''), NULLIF('ifcpresidentucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Intergenerational Connections', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Intergenerational Connections is a non-profit student organization consisting of volunteers who believe in engaging seniors through various creative activities to promote healthy aging. Students will work together with seniors and community members.', ''), NULLIF('intergenerationalconnectionssd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kommon Society', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Kommon Society is a student organization for Korean and Korean-American undergraduate students with social science majors. Kommon Society aims to establish an academic environment among Korean and Korean-American students with Social Science majors, facilitate a mutually beneficial network among students with the same majors and career goals provide opportunities for various academic and professional experiences to prepare each individual''''s future, and promote interest in contemporary global issues throughout the campus.', ''), NULLIF('kommonsociety@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Insight Pre-Optometry', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('To provide UC San Diego students interested in the field of optometry with the information, support, and opportunities necessary to learn about the profession, the schools of optometry, and the application process.', ''), NULLIF('insight.ves@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Intermission Orchestra', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('The Intermission Orchestra at UC San Diego is a student-run, hybrid performance/social organization dedicated to playing music from anime, films, video games, and other forms of pop culture media. We hold weekly rehearsals for our quarterly concerts for UC San Diego students to enjoy their favorite pieces. We have various teams assisting our productions, including music arrangers, an art team, and a tech team, who sometimes hold workshops to train anyone interested. We hold a variety of formal and informal social events, from dinners to game nights. If you''''re interested, please contact us through email or our social media pages below!', ''), NULLIF('intermissionatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Korean American Scientists and Engineers Association - Young Generation', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('KSEA-YG stands for Korean American Scientists and Engineers Association - Young Generation. Our parent organization was first established in 1971 to promote international cooperation between scientists and engineers in Korea and the US by providing career development and community service opportunities in the areas of science, technology, and entrepreneurship. More information about our parent organization can be found on the web: www.ksea.org. As a student chapter of KSEA, our organization foster communication among and provide assistance to Korean-American students in STEM field.', ''), NULLIF('snamgung@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Institute of Electrical and Electronics Engineers (IEEE)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('IEEE at UC San Diego is one of the largest IEEE Student Branch in the United States. We are part of the world’s largest technical professional organization dedicated to advancing technology for the benefit of humanity, IEEE. We at the UC San Diego Student Branch do our best to provide students the skills they will need to be better professionals. We host technical and professional workshops, social events, and K-12 outreach events. In addition to these, we host a variety of large, annual events such as H.A.R.D HACK –our 24 hour hardware hackathon–, Reverse Career Fair, Robofest, and more! We offer multiple projects students can participate in to improve their technical skills and stand out to employers. Our projects are split into two categories: quarterly and annual. Quarterly projects are beginner oriented and no experience is necessary to join them. Throughout the quarter there are project oriented technical workshops and mentors to help students bring their ideas to life. At the end of each quarter, teams have the opportunity to present their project for prizes. Our annual projects require more experience to join and compete against varying institutions. We currently have 2 projects fitting within this category, Robocup Soccer, an autonomous soccer playing robot, and Supercomputing, competing in various competitions utilizing hardware located within the San Diego Supercomputer Center.', ''), NULLIF('ieee@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Korean American Student Association (KASA)', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('KASA stands for Korean American Student Association. Here at UC San Diego, KASA prides itself on celebrating Korean culture through social interaction.', ''), NULLIF('kasastaffatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('International Health Collective', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The International Health Collective (IHC) strives to alleviate disparities in the San Diego–Tijuana region and abroad using an approach that is culturally sensitive, holistic, and sustainable. Based at the University of California, San Diego (UCSD) IHC is a youth-driven, 501(c)(3) organization run entirely by students and recent alumni. This structure gives IHC the unique ability to constantly innovate and improve its approach in an effort to create lasting change. In addition, IHC also promotes education and research both within the organization and in the communities it serves. IHC works closely with its communities and continually evaluates its efficacy in addressing their needs. IHC identifies with the World Health Organization’s definition of health, which goes beyond medicine and healthcare: "Health is a state of complete physical, mental, and social well-being, not merely the absence of disease or infirmity." IHC uses an interdisciplinary approach in which people of all backgrounds tackle large issues regarding health in a collaborative and comprehensive way. Students, teachers, medical professionals, engineers, community leaders, artists, and many others work together to create solutions and learn from one another. Our mission is to improve the health, and by extension the lives, of both those we serve and those who provide service.', ''), NULLIF('admin@internationalhealthcollective.org', ''), NULLIF('@internationalhealthcollective', ''), NULLIF('', '')),
  ('Korean Graduate Student Association (KGSA)', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Korean Graduate Student Association is the organization of the Korean graduate students, research staff, post-docs, professors, visiting scholars, and visiting professors at the University of California, San Diego (UCSD). The KGSA aims to promote unity and harmony among Korean people at UCSD and to support them in various ways. The main activities of the organization include assisting new incoming students with settlement, holding seasonal/ holiday/ sports events, and providing members with various kinds of useful information on the job market and life around campus. We welcome any kind of supports or contributions from individuals, organizations, and companies that could further consolidate the Korean community at UCSD and contribute to sound relationship between our members and society in general.', ''), NULLIF('kgsa.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Inter-College Residents Association (ICRA)', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of ICRA is to serve the on-campus residents of all residential areas at the University of California, San Diego, hereinafter referred to as UCSD. This body will plan educational, social, community service, and diversity programs to unite these residents as well as make recommendations for the enhancement of residential living. In addition, ICRA will serve to unite the residence committees of all residential living areas. ICRA will promote leadership opportunities and encourage college and residential area representation. It is the purpose of ICRA to help students grow as leaders and to unite the residents of all of UCSD’s residential areas. ICRA is a non-profit organization.', ''), NULLIF('icra@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('International Student Society', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The International Student Society is dedicated to creating a welcoming and inclusive environment for international students. Our mission is to help students build meaningful connections through social events, cultural events such as potlucks, and opportunities to share languages and experiences. By fostering this sense of community, we aim to reduce feelings of alienation and provide a support system for students adjusting to life at UCSD. Our club is a space where diverse cultures are celebrated, and students can connect, share, and grow together.', ''), NULLIF('intlsc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('International Society for Pharmaceutical Engineers (ISPE)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Our purpose is to bring professional development to students in the pharmaceutical, biotechnological, and related industries. Thus our members will be offered resume/interview building workshops, networking events with industry professionals, industry tours, discussion panels, and much more.', ''), NULLIF('ispe@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Korean Student Cultural Association (Ko.SCA)', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Korean Student Cultural Association at University of California, San Diego is a nonprofit student association organized to construct and maintain a comforting environment for Korean International Students- providing a smooth transition into UCSD. We strive to help students adapt to their newly found environment far from home with the following: (1) recreational social events such as freshman and transfer student rallies that brings unity and welcomes new people into our community, and (2) academic workshops and information sessions on scheduling and studying abroad summer programs. Our independent student run organization will host many events throughout the year creating a shelter for stressed out students and bringing about a sense of unity by maintaining a close knit community in which students can rely on for information, stress relief, and provide a comfortable home like environment. Our organization will also strive to interact and collaborate with other likewise Korean societies and organizations across California, expanding our network and creating many more invaluable connections for the student body.', ''), NULLIF('kosca.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Korean-English Language Exchange(KELE)', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('This organization was established with the purpose of facilitating language exchange between Korean and English. It aims to provide Korean students with opportunities to improve their English skills and meet diverse international students, socialize while offering students chance to enhance their Korean skills and experience Korean culture at UC San Diego.', ''), NULLIF('hac077@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('International Studies Student Association (ISSA) at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The organization gathers like-minded individuals who share diverse interests in international studies and international relations. We aim to not only be a resource hub, but also build community and meaningful connections among our peers. ISSA intends to provide a platform of rich experiences and opportunities in international studies, including: -Networking, social, and pre-professional events, including collaboration with UCSD''''s undergraduate and graduate departments -ISP Peer Mentorship program supported by the ISP Advising Office -Research opportunities with UCSD faculty and graduate students -Resources for studying, working, and interning abroad -Public events, conferences, and workshops for research, social awareness, international development -Service projects and fundraising for international causes -Student and alumni panels', ''), NULLIF('issaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lion Dance at UC San Diego', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Lion Dance at UC San Diego is established for the purpose of providing cultural enrichment to UCSD and the San Diego area by practicing, performing, and teaching the ancient art of Chinese Lion Dancing. On campus, no other traditional Chinese performing arts group exists that practices the Lion Dance. Lion Dance at UC San Diego is a unique group at UCSD. Lion Dance at UC San Diego intends to perform for any UCSD affiliated groups and events as well as non-UCSD affiliated organizations interested in our presentation. Lion Dance at UC San Diego understands and is committed to fulfilling its responsibilities of abiding by the University''''s policies.', ''), NULLIF('liondanceatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Living Stones College Ministry', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To minister to students at UC San Diego with the healing gospel of Jesus.', ''), NULLIF('livingstonescollege@lsccsd.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('KOTX', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('KOTX is a K-Pop community at UC San Diego that is both a social org & an all-inclusive dance team. Founded in 2015, KOTX’s mission is to provide a welcoming environment for all K-pop fans and to spread Korean culture through the art of K-pop. Always having fun and going crazy, let’s get KOTX!', ''), NULLIF('kotx@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Inter Varsity Christian Fellowship', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To establish and advance a witnessing community of students and faculty who follow Jesus as Lord and Savior: growing in love for God, God''''s word, God''''s people of every ethnicity and culture and God''''s purpose.', ''), NULLIF('ivatucsdoperations@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('International Women''''s Health Organization (IWHO)', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The International Women''''s Health Organization (IWHO) is a non-profit organization that strives to create a more equitable, comfortable, and inclusive space for young women all over the world. We provide basic education regarding puberty, menstrual health, and physical wellness to these young women, as well as to our community. We also fundraise to finance the materials for kits that include hygiene and menstrual products that are delivered on a monthly basis. Join our mission to make an impact on women''''s reproductive education and wellness!', ''), NULLIF('iwho@ucsd.edu', ''), NULLIF('iwho_at_ucsandiego', ''), NULLIF('', '')),
  ('Living Water Student Fellowship (LWSF)', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('LWSF is a faith-based, Christian student organization affiliated with the Living Water Bible Church at San Diego. Our primary purpose is to provide an opportunity for Chinese (Mandarin)-speaking students at UC San Diego a chance to experience Christianity and grow in faith together with our fellow members and mentors from our organization and church through our weekly Saturday fellowship, Sunday services, and special events.', ''), NULLIF('sdchristianfellowshiplwbc@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('IUSM (International Undergraduate Student Ministry)', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('We are a fellowship that strives to build a Christ centered community on campus, primarily with International undergraduate students, but everyone is welcome. We meet weekly for Bible studies & prayer and worship on campus on Sundays. Our vision is to share the gospel and students to spiritually thrive during college.', ''), NULLIF('iusm.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Loops of Love', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Loops of Love is about teaching people how to crochet and making items (beanies, toys, clothing, etc) for communities in need such as: homeless shelters, retirement homes, hospitals, and foster homes.', ''), NULLIF('loopsoflove@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('KUT Dance Team', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('By introducing new genres of dance while appreciating the culture the dance was founded upon, KUT ( Kpop Undefined Training ) Dance Team provides a safe and welcoming community for dancers to improve both as dancers and as individuals through three different divisions.', ''), NULLIF('kutdanceteam@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Jail Outreach Program', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Jail Outreach Program at UC San Diego aims to provide STEM classes in local incarceration facilities as a way to prevent recidivism in our San Diego community. Previously, we have received grants to create scholarship programs for previously incarcerated people. Additionally, our program increases science literacy in the community.', ''), NULLIF('sdscienceclass@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('La Familia de UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The mission of La Familia de UC San Diego is to foster a supportive and inclusive community for Latinx students. Through promoting open-mindedness and challenging harmful stereotypes, the organization aims to empower its members to reach their full academic potential. La Familia values vulnerability and encourages self-expression as essential elements of personal and professional growth.', ''), NULLIF('lafamilia@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Japanese Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Japanese Student Association at UC San Diego is for students whose home country is Japan and or for those who are interested and wish to experience Japanese culture.', ''), NULLIF('jsa.at.ucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Jewish at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The purpose of the club is to be a Jewish club for UCSD students. Members will have access to collaborative resources to enhance their Jewish experience.', ''), NULLIF('Jewishatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lotus Bridge @ UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Our club celebrates and shares Chinese culture on campus through food, crafts, language, and traditions. We aim to create a welcoming space where everyone can learn, connect, and enjoy cultural experiences together.', ''), NULLIF('lotusbridgeatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lambda Chi Alpha', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('Lambda Chi Alpha is a greek social fraternity as accepted by IFC.', ''), NULLIF('lambdachialpha.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lotus Project, The', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('We are mental health advocates working towards destigmatizing the conversation about mental health through educating local middle and high school students in the San Diego area.', ''), NULLIF('lotusproject@ucsd.edu', ''), NULLIF('@lotusprojectatucsd', ''), NULLIF('', '')),
  ('Lambda Theta Alpha Latin Sorority, Inc.', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('The purpose of Lambda Theta Alpha shall be to provide a sisterhood based on unity, love and respect in an effort to foster the development of strong leaders who will then provide and practice political, social and cultural activities. It shall also be the purpose of Lambda Theta Alpha to promote unity through charitable and educational programs, maintain a higher standard of learning and serve as a voice for all students.', ''), NULLIF('lta.etagamma@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Love and Time at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purpose of this student organization is to support the mission of Love and Time, a nonprofit dedicated to empowering mothers and children through mental health resources and community support. Our student organization will raise awareness on campus about maternal and child mental health through informational events on Library Walk, guest speakers, workshops, and group activities. By engaging UCSD students in service, education, and outreach, we aim to foster compassion, advocacy, and meaningful opportunities for students to make a difference in the lives of vulnerable families.', ''), NULLIF('loveandtime.mail@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kristos Campus Missions', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('KCM exists to care for collegians by discipling them to value the glory of God through local and global missions, ultimately to benefit and build up the local church of Jesus Christ.', ''), NULLIF('jak031@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Jugger at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Jugger at UC San Diego exists to bring the sport of jugger to the UC San Diego community, primarily through playing the sport and teaching new players. The ultimate objectives are for participants to exercise, meet new people, and above all enjoy themselves.', ''), NULLIF('juggeratucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lambda Theta Nu Sorority, Inc.', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('The purpose of Lambda Theta Nu Sorority, Inc. shall be to open doors of opportunity to the Latinas of our community. Our primary focuses are academic excellence and meeting the needs of Latina women in higher education. Lambda Theta Nu Sorority, Inc. also promotes the advancement of Latinas through various campus activities and community services and provides an environment for personal growth within a unit of sisterhood. Lambda Theta Nu Sorority, Inc.’s priorities, however, will be placed upon academic excellence and community service.', ''), NULLIF('xi1986president@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lumnus Consulting Junior Enterprise', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Lumnus Consulting is a Junior Enterprise that was established at UC San Diego in 2016. Lumnus is run entirely by students and provides business and marketing consulting services for startups and small businesses.', ''), NULLIF('contact@lumnusconsulting.net', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kaibigang Pilipino (KP) at UC San Diego', NULLIF('Student Affirmative Actions Committee (SAAC)', ''), NULLIF('Cultural', ''), NULLIF('Kaibigang Pilipino fosters a supportive and inclusive community where anyone can deepen their understanding of Filipino heritage, celebrate their identity, and access resources necessary to develop the skills to thrive both within and beyond the university setting.', ''), NULLIF('kaibigangpilipino.chair@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kairos College Fellowship', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('Building a community of believers on the college campuses of San Diego to make disciples of all nations.', ''), NULLIF('kairoschurchsd.college@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('M.E.M.O. at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('M.E.M.O provides medical and educational services locally in San Diego, Orange County, and Los Angeles, as well as abroad in Vietnam. We send volunteers annually to Vietnam to provide scholarships and school supplies to students in rural communities, set up free health clinics, donate monetary aid and supplies to orphanages, and sponsor heart surgeries for children with congenital heart disease. Locally in San Diego, Orange County, and Los Angeles we send volunteers to help other local non-profit organizations, set up community health fairs, and organize awareness nights on campus.', ''), NULLIF('memoatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('MAE Undergraduate Student Advisory Committee', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('To represent the undergraduate body in meetings with the administration of the Mechanical and Aerospace Engineering (MAE) department and organize events for the MAE student body.', ''), NULLIF('wbantugan@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Laotian American Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('It shall be the purpose of the Laotian American Student Association to promote Laotian and Laotian American culture and way of life by providing a comfortable environment and social network for members as well as all others interested in Laotian and/or Laotian American culture. The Laotian American Student Association is first and foremost a cultural organization, and although social and volunteer events may result from the endeavor to achieve this purpose, they are not the priority. The Laotian American Student Association is a non-profit cultural and social oriented organization striving to promote the Laotian and Laotian American culture as well as serving the above-mentioned purpose around UCSD campus and its surrounding environment. The Laotian American Student Association will work in collaboration with the Lao Community Cultural Center of San Diego to volunteer at their yearly cultural festivals and volunteer events.', ''), NULLIF('lasaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lambda Theta Phi Latin Fraternity Incorporated', NULLIF('Multicultural Greek Council (MGC) - Fraternity', ''), NULLIF('Fraternity', ''), NULLIF('Lambda Theta Phi Latin Fraternity Incorporated was born to promote the spirit of brotherhood, to protect the rights of Latino students in their quest for an education, to promote the rich Latino culture, and to maximize leadership potentials to provide guidance to our community.', ''), NULLIF('casector1.induction@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kappa Alpha Pi', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of this Fraternity shall be to foster knowledge of the law for undergraduate students; to provide service to the greater community and campus; to promote a strong sense of fraternalism among members; to uphold the ideals and integrity of Kappa Alpha Pi Pre-Law Co-ed Fraternity; so that each member may advance [their] intellect while contributing actively to the well-being of others.', ''), NULLIF('kapiatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kappa Alpha Theta', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('The first greek letter fraternity for women, Kappa Alpha Theta strives to create an inclusive social and educational environment. Our mission is to offer women lifelong opportunities for intellectual and personal growth and create the widest influence for good.', ''), NULLIF('thetazetarhopresident@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Latinx Advancing in Math and Physics (LAMP) at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The goal of LAMP is to provide an academic, social, and community space for Latinx math and physics students at UC San Diego. In an effort to promote retention within this marginalized population of STEM students we want to provide services in the Latinx community to combat high dropout rates, like office hours and tutoring. As well as finding the value in strong support systems, we created LAMP to help bridge students together in more ways than just academically. Through socials and general body meetings we want to help facilitate and grow these relationships. We are not just for the community, we are a community.', ''), NULLIF('lampatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Majiang at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Majiang at UC San Diego is a student organization aimed at helping students in their academic and social endeavors. Our goal is to encourage cultural interactions between different ethnic groups. Majiang at UC San Diego has no political agenda of any kind.', ''), NULLIF('roc003@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Malaysian Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The purpose of the Malaysian student organization will be to promote Malaysian culture, traditions, and values, as well as to support and empower Malaysian students at UC San Diego. Our mission will be to create a welcoming community that fosters cultural exchange and celebrates diversity.', ''), NULLIF('ncheah@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kappa Kappa Gamma', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('To build and provide bonds of friendship, mutual support, respect for intellectual development, and an understanding and allegiance to positive ethical principles.', ''), NULLIF('kkgpresidentatucsd@gmail.com', ''), NULLIF('kkgatucsd', ''), NULLIF('', '')),
  ('Law Social, The @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Our goal is to create an environment for Pre-Law students to network and learn more about the field they are going into.', ''), NULLIF('thelawsocial@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Le French Club at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Le French Club at UC San Diego aims to celebrate Francophone culture by fostering a community where students can immerse themselves in its rich traditions and language. Through building friendships, offering mentorship opportunities, hosting engaging events, and providing opportunities to improve French speaking skills, the club provides a welcoming space for cultural exchange, personal growth, and fun.', ''), NULLIF('lefrenchclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mariachi La Joya del Sur', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('To create an environment where people can enjoy and perform the traditional folk music of Mexico regardless of ethnicity or music level. We want to spread the beauty that is Mariachi Music throughout our campus and for those who are unaware of the importance it holds culturally and traditionally.', ''), NULLIF('mariachiljds@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kappa Psi Pharmaceutical Fraternity at UC San Diego SSPPS', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Kappa Psi Pharmaceutical Fraternity is a professional organization dedicated to fostering excellence in the field of pharmacy. Established in 1879, Kappa Psi provides a supportive network for pharmacy students and practitioners, promoting academic achievement, professional development, and community service. Through its commitment to brotherhood, leadership, and service, Kappa Psi aims to advance the pharmacy profession and create a positive impact on healthcare. Members collaborate to enhance their knowledge, skills, and ethical standards, contributing to the overall well-being of individuals and communities through the practice of pharmacy.', ''), NULLIF('deltaphi@kappapsi.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kappa Zeta Phi @ UC San Diego', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('Kappa Zeta Phi is a non-profit Asian-interest student organization established with the purpose of enriching the lives of its members through providing lasting friendship and sisterhood. In addition, the sorority aims to promote projects of cultural and intellectual value, as well as participate in charitable events.', ''), NULLIF('sdkappasprez@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Leading Women of Tomorrow at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purpose of this organization is to empower, encourage, and assist students in participating in careers in civil service. Our efforts are aimed at bridging the gender gap among public representatives.', ''), NULLIF('lwotatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Matcha Makers Association at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The goal of this organization is to foster a welcoming community of students who appreciate and enjoy Matcha–not only as a beverage, but as a ritual of self-care and wellness. This organization prioritizes bringing people together, encouraging interaction, and building lasting relationships. While we highlight the benefits of Matcha and wellness, our main focus is on creating opportunities for students to bond, share experiences, and cultivate a sense of belonging.', ''), NULLIF('matchamakerssd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lebanese Student Association at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The purpose of this student organization is: - To promote the interests of the Lebanese and non-Lebanese students at UC San Diego. - To acquaint the UCSD community with Lebanon and the Lebanese people, and to promote their culture. - To help Lebanese students integrate better into the diverse UCSD community by creating an atmosphere of friendship & support. - To form a closely knit community on campus.', ''), NULLIF('lsaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Math Motivators', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Math Motivators mission aligns with that of The Actuarial Foundation, aiming to harness the power of math education to transform futures through the expertise and resources of the actuarial community. The Foundation envisions a future where individuals gain confidence and opportunities through math proficiency. To support this vision, the program focuses on providing students with access to the resources and support they need to succeed, regardless of their circumstances or background.', ''), NULLIF('info@actfnd.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kendo Club at UC San Diego', NULLIF('Martial Arts/Combatives/Weaponry', ''), NULLIF('Sports', ''), NULLIF('The Kendo Club at UC San Diego seeks to promote awareness and appreciation of the Japanese martial art of kendo through community outreach, school involvement, and intercollegiate competition.', ''), NULLIF('kendoclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mathematics Graduate Student Council (MGSC)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The purpose of the Mathematics Graduate Student Council is to advocate for the economic, educational, professional, teaching, and diversity related interests of the math graduate student body. The Council is the liaison between the math graduate students and Mathematics Department administration and faculty. In addition, the Council pursues initiatives that improve math graduate student wellness, help graduate students build leadership and professional skills, and impact the greater UC San Diego community.', ''), NULLIF('math-mgsc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Keyboard Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Keyboard Club @ UC San Diego is an inclusive community for anyone interested in mechanical keyboards. Our goal is to be a social club where members can make friends based on a shared interest. We focus on our events—a place where you can try keyboards, meet others, and learn more about the hobby.', ''), NULLIF('keyboardclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('LiftHer at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('LiftHer is a growing organization that aims to promote female fitness, health, and wellness and empower women. LiftHer was created to provide women of all backgrounds and fitness levels with community, resources and confidence. Although we are female-oriented, we welcome members of all gender identities so long as they support and embody our mission.', ''), NULLIF('liftheratucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kidz Next Door', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Our purpose is to create a safe and supportive space for dancers of all backgrounds. We practice dance styles that range from jazz to hip hop, and other street styles as a way to celebrate all forms of dance. We hope to make our team, a space that can help to improve new dancers and help students along on their dance journeys.', ''), NULLIF('kidznextdoordance@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Kindness Collective', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Kindness Collective aims to inspire and cultivate a culture of kindness, positivity, and compassion through meaningful acts of service, community outreach, and personal connections. By focusing on the power of small, intentional actions and impactful service projects, we strive to create a ripple effect of positive change on campus and in the surrounding community.', ''), NULLIF('kindness.at.ucsd@gmail.com', ''), NULLIF('@kindness.at.ucsd', ''), NULLIF('', '')),
  ('Matsuri', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Spread Japanese Culture through the power of food, games, and performances. A team of over 20+ staff members, 100+ volunteers, and the oldest and largest food festival in all of UCSD.', ''), NULLIF('info@sdmatsuri.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Maximalist Magazine', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('To publish an experimental magazine that focuses on the intersection of the arts and humanities while exploring other interdisciplinary subjects. Maximalist Magazine seeks to uplift and celebrate the value of the individual by sourcing work from a diverse body of voices representing UCSD.', ''), NULLIF('maximalistmagazine@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Lighthouse College Life', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To provide a church-sponsored Bible teaching Christian organization for students on-campus.', ''), NULLIF('info@lighthousebc.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Line Dancing Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Our college line dancing club is a vibrant community dedicated to fostering friendship, fitness, and fun through country line dancing. We aim to create an inclusive space where students from all backgrounds and skill levels can unwind, learn new skills, and build lasting relationships. Through dance demos, workshops, and weekly dancing social events close to campus, our club provides opportunities for members to develop their dancing abilities in a friendly group setting.', ''), NULLIF('linedancing@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('MDS Graduate and Professional Society', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('This organization shall advocate for all professionals and students enrolled in the Master of Data Science program. Given this program’s online curriculum, the organization will focus on supporting students abroad by creating opportunities to connect online, regional meet ups, community events, and professional support. The Master of Data Science program is a part-time graduate program, thus this organization will support working professionals as well as full-time students with resources and events that are aligned with their personal or career goals. Part of this hybrid initiative will involve maintaining a strong relationship with alumni to further foster a network that supports current students beyond graduation.', ''), NULLIF('mdsgpsociety@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Linguistics Undergraduate Association (LINGUA)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Our purpose is to unify linguistics majors, minors and interested students through scholarly discussion, social activities and faculty interaction. We aim to foster a warm, inviting environment in which to explore academic and occupational opportunities within UCSD Linguistics department and beyond.', ''), NULLIF('lingua@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mechanical and Aerospace Engineering Graduate Student Council', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Mechanical and Aerospace Engineering (MAE) Graduate Student Council (GSC) is for building a community within the department, facilitating professional development opportunities for our graduate students, and promoting service within the greater community. We are run by MAE graduate students from all disciplines within the department. We aim to bridge the gap between faculty, staff, and students by organizing events throughout the year.', ''), NULLIF('maegsc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Medical Aid Initiative @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Medical Aid Initiative at UC San Diego aims to help identify and reallocate excess, unused medical supplies from UC San Diego Health facilities to groups that provide free health services to underserved communities. We are partnered with various local organizations that serve communities in need in the San Diego region as well as globally. We are dedicated to both improving local and global access to healthcare and promoting sustainability by reducing medical waste. Members will have the unique opportunity to gain hands-on and real-world public health experience, help facilitate the medical supply reallocation process, learn about sustainability in hospital systems, and join a community of students passionate about addressing health disparities.', ''), NULLIF('mai.atucsd@gmail.com', ''), NULLIF('@maiatucsd', ''), NULLIF('', '')),
  ('LIFE Fellowship', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The goal of this organization is to pray, worship and sing songs of praise to the triune God of the Bible (God the Father, Jesus Christ, and the Holy Spirit), and to study the Bible which we hold to be the inerrant, infallible and divinely inspired revelation of God. We desire to provide a safe environment for anyone of any belief to dialogue about the Christian faith. Members of the organization will find a genuine, loving community whereby they are unconditionally loved and accepted for who they are. In addition, members will learn more about the Christianity and Christian theology.', ''), NULLIF('aswing@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('KOJOBS at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Kojobs strives to act as an intermediary between students and companies, providing social networking events for students and professionals to assist students to become better prepared for their post-graduation lives. Such events include recruitment/job fairs, professional seminars, resume workshops, mock interviews, and intermural events.', ''), NULLIF('koj0b.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Medics in Armenia', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Medics in Armenia at UC San Diego is a student organization meant to educate and train students that are interested and/or pursuing a future in medicine by traveling to Armenia to shadow medical professionals and volunteer at impoverished communities across Armenia. This organization hopes to guide students in establishing significant connections with those in the medical field.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('MedSearch at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('MedSearch at UC San Diego is dedicated to fostering the next generation of healthcare leaders by providing comprehensive guidance to its members in their exploration of medical and educational opportunities through free programs, mentorship, and access to extracurricular resources. Concurrently, our organization is committed to impactful community service by actively organizing the donation of essential care items, such as first aid kits and homemade cards, to local hospitals, homeless shelters, and refugee centers. Members will gain valuable leadership, service, and medical insight through monthly meetings, hands-on donation drives, and engagement with the broader healthcare community, ultimately contributing to both campus well-being and the greater San Diego community.', ''), NULLIF('medsearch.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Medical School for Kids Outreach at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('A. Medical School for Kids Outreach Chapter is a student-led community service organization that aims to introduce children to the world of healthcare and medicine. Through interactive events such as Mini White Coat Ceremonies, Teddy Bear Clinics, and Health & Hygiene Fairs, the chapter aims to educate and inspire the next generation about medical sciences in a fun and engaging manner. The organization will provide hands-on experiences that promote medical knowledge and healthy lifestyles among children in the San Diego community. B. This chapter operates in partnership with Dr. Brandon Pham and Dr. Betty Nguyen, authors of the Medical School for Kids series. We shall incorporate their book series “Medical School for Kids” to enhance the educational content and outreach of our activities.', ''), NULLIF('mdforkidsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('MEDLIFE at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('MEDLIFE is a secular, volunteer-run global health organization whose mission is to help families achieve greater freedom from the constraints of poverty, empowering them to live healthier lives. Our patients did not choose to be poor, but they do choose to strive for a better life. MEDLIFE stands beside them in this pursuit. We seek to achieve this goal through partnering with motivated individuals to improve their access to MEDs: Medicine, Education and a safe home. MEDLIFE believes access to quality healthcare, education and community development are basic human rights. To this end, we commit all our resources to bring Medicine, Education and Development to Low Income Families Everywhere. That being said, we provide service opportunities for UCSD students both locally and abroad. Alongside our outreach projects, we actively learn about the local communities we work with in order to ensure we are providing the right, sustainable, and important care.', ''), NULLIF('medlifeatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Men''''s Club Basketball at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The Men''''s Club Basketball Team at UC San Diego is dedicated to fostering a vibrant and competitive atmosphere where students may engage in organized basketball as a part of a cohesive team. Our goal is to provide students with an opportunity to join a tight-knit community that is passionate about basketball and seeks to compete against other schools at a high level. With our core values of communication, teamwork, respect and inclusiveness at the forefront, we anticipate that students become improved leaders and individuals while simultaneously cultivating positive and lasting memories.', ''), NULLIF('MCBB@UCSD.edu', ''), NULLIF('@mcbbatucsd', ''), NULLIF('', '')),
  ('Mic Drop Karaoke Club at UC San Diego', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('College can often bring stress and unnecessary turmoil from schoolwork, so Mic Drop Karaoke Club at UC San Diego exists to offer students a fun and relaxing outlet. I understand that not everyone has the time to commit to a full musical theater production, but if you still want to practice your singing skills without the demands of a full show, this is the perfect opportunity. My club is a space to unwind through song, whether you’re a casual singer or an experienced performer. There’s no pressure or demand, just show up, sing when you want, and enjoy the moment. I welcome everyone to join and take a break from the hectic side of student life.', ''), NULLIF('micdropkaraokeclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Middle Eastern & North African Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The mission of M.E.N.A.S.A. is to increase M.E.N.A. student involvement by creating a community and place of belonging regardless of ethnic, political, or religious identities. M.E.N.A.S.A. will also advocate for issues happening overseas and educate other UC San Diego students about these conflicts. We are ecstatic about sharing the different M.E.N.A. cultures with the organization and the rest of the UC San Diego Campus while welcoming all M.E.N.A. students and its regions allies.', ''), NULLIF('mena.at.ucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mini Golf Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of Mini Golf Club is to promote enthusiasm for the game of Mini Golf, provide a welcoming and positive environment for those with a passion for the game of mini golf, and to assist members in developing their skills. The Mini Golf Club will foster a sense of sportsmanship, kindness, and bring people together in our love for mini golf. Additionally members will practice their strategy and tactics on the course, develop their short game, and come together to celebrate the sport we love.', ''), NULLIF('minigolfatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mindfulness Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of this club is to promote student engagement in mindfulness practices by providing them with a safe container on campus alongside a supportive community. As a result of our efforts, my hope is that students leave our offerings feeling refreshed, inspired, and whole.', ''), NULLIF('mindfulnessclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Muslim Student Association', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The Muslim Student Association at UC San Diego strives to facilitate character building, humanitarian work, and social justice through educational and social avenues founded on Islamic standards of personal conduct and community. The organization aims to maintain an inclusive environment, to unite with allies, and to retain members in order to nurture a diverse generation of Muslims who are cognizant and pragmatic members of society.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Muslim Tech Collaborative at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Muslim Tech Collaborative (MTC) at UC San Diego is dedicated to creating a professional and spiritual community for Muslims in tech. We aim to showcase Islamic excellence by leveraging our talents to create positive, tangible impacts on the world.', ''), NULLIF('mtcatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Minority Business Association', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Minority Business Association promotes the academic and professional development of students from ethnic minority groups interested in pursuing a business career. It will serve its members with opportunities for networking events, social events, guest speakers, community service, and academic unity hours. The goal of this organization will be for members to receive guidance to help them improve their skills and knowledge within the business world. Members will be provided with the knowledge to gain opportunities in the field of business to further ensure their success in their professional careers. The organization seeks to provide a safe and secure environment for minority students to develop professionally, communicate about essential issues, and promote a network to provide professional growth as we encourage minority students to successfully pursue a business career.', ''), NULLIF('minoritybusinessassoc@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Minority Law Association', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Minority Law Association (MLA) at UC San Diego is dedicated to supporting the academic and professional development of undergraduate students from underrepresented and marginalized communities who are interested in pursuing careers in law. Through mentorship, networking events, and guest speakers from the legal field, MLA equips members with knowledge, experience, and confidence to navigate legal education and professions. MLA also fosters an inclusive and empowering space for students to discuss issues affecting their communities, build meaningful connections, and advocate for greater equity and representation within the legal system.', ''), NULLIF('mlaatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mustard Seed Project, The', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Mustard Seed Project’s mission - guided by a “hand up, not hand out” philosophy - is to create a student model that connects unsheltered and low-income individuals to services and programs through outreach, research, and education.', ''), NULLIF('msp.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mycology Club @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Mycology club encourages exploration into the world of mushrooms and other fungi through the growing of gourmet (edible) mushrooms, foraging and identifying different fungal species, and overall, learning about fungi in a social, group environment.', ''), NULLIF('mycologyclubsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mitochondria Club at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of this organization is to fundraise and spread the word of Mitochondria disease in order to help UCSD researchers find a cure and treatment. Students will have the ability to participate in a multitude of events and learn from the researchers in order to provide aid for kids dealing with the illness and gain money and support for its cause. Additionally, students will have a close connection with UCSD Researchers, opening many exciting opportunities in the field of research and medicine.', ''), NULLIF('mitochondriaclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('NAMI On Campus @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('NAMI On Campus @ UC San Diego is a student-led chapter of NAMI On Campus that focuses on mental health awareness, education, peer support, and advocacy on campus. Founded in 1979, NAMI (National Alliance on Mental Illness) is the nation’s largest grassroots mental health organization. It provides education, advocacy, and support to people and families affected by mental illness, with many programs partly supported by federal grants. Our chapter hosts regular general meetings with guest speakers and skill-building sessions, organizes stigma-reduction and wellness events, connects students to NAMI services and crisis resources, and builds leadership pathways through volunteer opportunities with our local affiliate and community partners. Members take part in meaningful service in partnership with NAMI San Diego & Imperial Counties through outreach events and the Friends in the Lobby program, and each year we organize a NAMIWalks team that brings students together around stigma reduction and community support. By learning, serving, and leading, members gain practical experience, community, and professional development, while the broader campus benefits from increased mental-health literacy, stronger connections to care, and a more compassionate culture.', ''), NULLIF('NAMIOnCampus@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mixed Student Union', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Mixed Student Union at UCSD will have the purpose to increase and highlight cultural exchange amongst members and campus at large, as well as create a welcoming and inclusive community for people of multicultural identities.', ''), NULLIF('mixedstudentunion.atucsd@gmail.com', ''), NULLIF('@mixed_at_ucsd', ''), NULLIF('', '')),
  ('NanoEngineering and Technology Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('NETS is a non-profit student-led organization that collaborates with NanoEngineering students, faculty members, non-major students, and external industry stakeholders. Our organization''''s goal is to create an environment for professional growth, provide networking opportunities, and support academic development. Additionally, we aim to foster a community that facilitates communication and cooperation in the fields of nanotechnology, nanoengineering, and science.', ''), NULLIF('netsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('MMCB Club', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('To provide students in the Molecular and Cellular Biology and Microbiology major programs with academic resources, community, and connections.', ''), NULLIF('mmcb.outreach@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('National Arab American Medical Association (NAAMA) NextGen', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The objective of NAAMA is to create a supportive and culturally enriching community for Arab American students pursuing careers in healthcare. We strive to engage in community outreach and health education to promote cultural awareness of Arab American heritage within medicine. Additionally, we seek to provide networking opportunities, mentorships, and resources for our members. Our desire is for Arab American students at UC San Diego to have a space to connect with fellow peers to find a supportive atmosphere, advocating for Arab American representation. NAAMA aims to cultivate inclusivity and cultural competence, working towards a more equitable healthcare environment. NAAMA NextGen is committed to empowering Arab-American students with the resources and opportunities to play a key role in healthcare advocacy and community service.', ''), NULLIF('naamanextgenatucsd@gmail.com', ''), NULLIF('@naamaatucsd', ''), NULLIF('', '')),
  ('National Collegiate Wrestling Association Team at UC San Diego', NULLIF('Martial Arts/Combatives/Weaponry', ''), NULLIF('Sports', ''), NULLIF('The National Collegiate Wrestling Association Team at UC San Diego will serve to promote the sport of wrestling at the collegiate level at UC San Diego. It will serve as a place to practice, learn, and compete through the sport of wrestling and work as a space welcoming of everyone who wishes to join it with good intentions. Students who join the club will be welcomed and met where they are at, whether that is on day one of their wrestling journey or after many years of experience.', ''), NULLIF('clubwrestling@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mock Trial @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of Mock Trial at UC San Diego is to prepare for Mock Trial competitions under the governing body of The American Mock Trial Association, and also to encourage interest in law advocacy. Mock Trial at UC San Diego is a non-profit student organization.', ''), NULLIF('mocktrial.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Model United Nations at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Model United Nations members simulate the United Nations by role-playing diplomats and forming delegations to attend conferences. At these conferences, students debate global issues, conduct speeches, draft resolutions, form political alliances, and resolve critical international problems. In doing so, Model United Nations students are exposed to international relations and its application in today''''s society, which expands their understanding of the world and becoming global citizens.', ''), NULLIF('modelun@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Out in Science, Technology, Engineering, and Mathematics (oSTEM)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Out in Science, Technology, Engineering, and Mathematics (oSTEM) is a nationally recognized organization that is geared towards the personal and professional development of queer or LGBTQIA+ students who are interested in Science, Technology, Engineering, and Mathematics through social, educational, professional, philanthropic, and outreach programming. It is also focused on helping students throughout UCSD and San Diego connect to a broader community of queer folks (students and professionals) whose academic interests lie in similar fields.', ''), NULLIF('ostem@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mood Psychology @UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Mood Psychology aims to provide information about professional mental health services for overseas Chinese students. And it is committed to building a convenient psychological counseling channel so that overseas students who need psychological counseling can reduce the obstacles, and help to find a suitable counselor for them, while let them feel a better sense of belonging. Mood Psychology has established on-campus clubs in significant colleges and universities to link the excellent psychology resources of domestic and foreign schools with psychology enthusiasts, potential practitioners, and practitioners to develop a community and achieve psychology at home and abroad. In addition, we are sharing resources and building a platform for academic exchanges and discussions in psychology.', ''), NULLIF('moodpsy.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('National Marrow Donor Program (NMDP) at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purposes of this organization are to: A. Be the official chapter partnering with the NMDP representative to educate and engage the university or college community in this unique opportunity to save lives. B. Partner with the NMDP representative to plan and achieve the yearly goals of the chapter: • Raise awareness of the NMDP mission to save lives through cellular therapy. • Recruit committed members to the NMDP Registry of potential marrow donors. • Raise funds for NMDP patients and families through NMDP Foundation’s official fundraising platform. • Keep accurate records of these awareness, recruitment and fundraising efforts and report volunteer hours each month. • Ensure chapter’s sustainability by voting in officers each spring for the following year.', ''), NULLIF('ndmp.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Out The Archive', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('Out the Archive (OTA) is a creative community that uplifts others to embrace expression and bring their ideas to life. Our mission is to provide a collaborative space for inspired creatives in music, mixed media, clothing design, and website development—making the process of creative exploration more accessible through interdisciplinary exchange. From connective workshops to artistic showcases, OTA aims to convey that creativity is for everyone—empowering students to follow their inner spark and discover what they''''re capable of.', ''), NULLIF('outthearchive@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('National Residence Hall Honorary', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of the National Residence Hall Honorary is to serve and recognize individuals, groups, and programs on campus that contribute to the success of residential life at UC San Diego on a campus-level, national, and international basis.', ''), NULLIF('nrhh@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pacific Islander Student Association (PISA at UC San Diego)', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('PISA was established to connect the Pasifika student body at UC San Diego to create a sense of community as we are one of the smallest minorities in attendance at the university. PISA''''s mission is to provide a sense of community for students who identify as Pacific Islander or wish to be a part of and learn about the Pacific Islander community. PISA seeks to promote and perpetuate its mission through education, diversity, justice, community, and respect for Pacific Islander cultures', ''), NULLIF('crapolla@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Morning Sign Out at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Morning Sign Out (MSO) at UC San Diego is an online publication dedicated to making science and medicine understandable to the public, providing readers with clear information that leaves them more knowledgeable than before.', ''), NULLIF('morningsignout.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pakistani Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The purpose of this cultural student association is to create a community of those interested in learning and celebrating Pakistani culture, to further the knowledge of interested persons of the history of Pakistan, in the process learn about issues pertinent to the Pakistani community back home and American Pakistanis, and to serve all UCSD and other University Students, faculty and staff in achieving the above-stated goals. The Pakistani Student Association will also serve as a resource for International Pakistani students, and American Pakistani students in order to provide a home and cultural environment. PSA will establish connections between students from all cultural backgrounds, facilitating multiculturalism and cultural exchange at UCSD.', ''), NULLIF('psaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('National Pan-Hellenic Council', NULLIF('National Pan-Hellenic Council Organizations (NPHC)', ''), NULLIF('Greek Life', ''), NULLIF('The National Pan-Hellenic Council is a collaborative council composed of the Divine9 historically African American fraternities and sororities. This council serves as a support support system for allNPHC greek life on campus.', ''), NULLIF('nphcpresidentatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Movimiento Estudiantil Chicanx por Activismo (MEChA)', NULLIF('Student Affirmative Actions Committee (SAAC)', ''), NULLIF('Cultural', ''), NULLIF('The primary goal of Movimiento Estudiantil Chicanx por Activismo de UC San Diego, hereinafter referred to as M.E.Ch.A de UC San Diego is to create a greater community that fosters a greater consciousness which reflects the issues we face politically, culturally, and socially as well as celebrating those aspects of our identities and society. Through this community, the goal is to offer support, opportunities, resources and trust among students who often feel marginalized in traditional and oppressive higher education circles.', ''), NULLIF('mecha69atucsd@gmail.com', ''), NULLIF('@mecha.at.ucsd', ''), NULLIF('', '')),
  ('National Society of Black Engineers at UC San Diego (NSBE)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To increase the number of culturally responsible black engineers who excel academically, succeed professionally, and positively impact the community.', ''), NULLIF('nsbe@ucsd.edu', ''), NULLIF('@nsbeatucsd', ''), NULLIF('', '')),
  ('Moot Court at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('This organization’s purpose is to prepare for and participate in undergraduate moot court competitions.', ''), NULLIF('mootcourt@ucsd.edu', ''), NULLIF('@mootcourtatucsd', ''), NULLIF('', '')),
  ('Native American and Indigenous Student Alliance (NAISA)', NULLIF('Student Affirmative Actions Committee (SAAC)', ''), NULLIF('Cultural', ''), NULLIF('(Previously known as the Native American Student Alliance) The purpose of this organization is to facilitate the maintenance and education of Native American culture and beliefs, while maintaining a community for Native students (and Allies) on campus and contributing to local Native communities. Native American Student Alliance is a not-for-profit organization.', ''), NULLIF('afunmaker@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Muir Musical', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Muir Musical exists as a student-run production company. It is dedicated to increasing the opportunities and satisfaction of the undergraduate theatre community by providing positions/roles in directing, stage management, design, acting, and production team members. Muir Musical provides students opportunities through our dedication to putting on productions, educational workshops, and community events every year.', ''), NULLIF('muir.musical@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pandora Forum at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Pandora Forum is a space for Classical Studies majors, minors, and any student interested in ancient Mediterranean studies at UC San Diego. The organization seeks to provide resources and advice regarding the Classical Studies program at UC San Diego; to discuss previous and current literature, essays, and scholarly works in ancient Mediterranean studies; to serve as a collaborative study and investigative space; and to serve as a center for students within the Classical Studies program.', ''), NULLIF('pandoraforum@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Navigators', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To advance the Gospel of Jesus and His Kingdom into the nations through spiritual generations of laborers living and discipling among the lost.', ''), NULLIF('tritonnavs@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Panhellenic Association', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('To oversee the 11 Panhellenic and 1 Affiliate Chapters within the Panhellenic Council. These chapters are: Alpha Chi Omega, Alpha Epsilon Phi, Alpha Omicron Pi, Alpha Phi, Chi Omega, Delta Delta Delta, Delta Gamma, Kappa Alpha Theta, Kappa Kappa Gamma, Phi Sigma Rho (Affiliate), Pi Beta Phi, and Sigma Kappa.', ''), NULLIF('cpapresident@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Mujeres Activas en Letras y Cambio Social (MALCs) @ UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Mujeres Activas en Letras y Cambio Social @ UC San Diego. Supporting Latinas, Chicanas, Native American/Indigena activist and scholars!', ''), NULLIF('malcsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Multicultural Greek Council', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('The objective of MGC shall be to create and maintain high standards in fraternities and sororities by addressing, coordinating, and developing strategic action plans that unify organizations, promote higher education, provide community service, and enhance leadership skills.', ''), NULLIF('mgcpresident@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Neurodegenerative Disease Awareness Association (NDAA)', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of this organization is to educate members on neurodegenerative diseases, current treatments, and ongoing cutting-edge research, as well as inspire members to support these causes through fundraising for institutions, raising awareness at both the high school and college levels, and volunteering.', ''), NULLIF('ndaa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Paranormal Society', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Our purpose, to learn, investigate, and research about various places that are or may be experiencing unusual activity to verify if whether or not it is paranormal using logical reasoning.', ''), NULLIF('paranormalsociety@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Multi-Identity Art Collective', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The Multi Identity Art Collective was founded with the intention of creating an inclusive and warm artist space here at UCSD. The Collective is inclusive of all personal identities and skill levels. Members will learn technical art skills and art critique. They also produce at least one project per quarter. The collective guarantees a welcoming atmosphere for all who wish to create art, and stands against discrimination on basis of race, gender, or sexuality.', ''), NULLIF('miac@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Paper Airplanes at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Paper Airplanes at UC San Diego serves as the campus affiliate of the international nonprofit Paper Airplanes, connecting UCSD students with opportunities to tutor conflict-displaced individuals around the world. Our organization recruits and supports UCSD volunteers while Paper Airplanes provides all training, curriculum, and student matching. By acting as the link between UCSD tutors and Paper Airplanes, we uniquely expand access to education for refugees and conflict-affected students.', ''), NULLIF('paperairplanesatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Neurosciences Graduate Program', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Neurosciences Graduate Program (NGP) Student Council is a student-led group that represents the interests and concerns of graduate students within the Neuroscience Graduate Program. This council will strive to improve the overall quality of the NGP by promoting a sense of community within the NGP student body; by facilitating communication between students and faculty; and by providing social, academic, and professional programming for NGP students.', ''), NULLIF('neurograd@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Muse Dance Company', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('To provide a safe space for students to express themselves through jazz and contemporary dance and work collaboratively with others. Additionally, to give students the opportunity to perform with their peers and showcase their choreography.', ''), NULLIF('dancecompanymuse@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Partners In Health Engage at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('We believe that healthcare is a human right. At Partners In Health, this core belief drives everything we do—from hospital bedsides to the streets. Through Partners In Health Engage at UC San Diego, we plan to organize our campus community toward building a global movement for the right to health. We advocate for global and domestic policies that further the right to health and mobilize students in the fight for health equity. With each campaign, petition, and event, we generate new resources, foster public discourse, and advocate for policies that advance the right to health worldwide. Together, we demand the right to health be protected for all people, everywhere. The fight for health equity cannot wait.', ''), NULLIF('pihengageatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('New Life Student Ministry', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To educate and grow the students at UCSD in knowledge, love, and faith in Jesus Christ. Christian doctrines are taught from a Reformed and Presbyterian perspective, and anyone from any background is welcome.', ''), NULLIF('newlifesmatucsd@newlifelajolla.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Music and Memory at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Music & Memory at UC San Diego aims to bring personalized music into the lives of people with a wide range of cognitive and physical challenges through digital music technology and live performances, helping improve quality of life. Further, we would like to help advocate for our parent Music & Memory non-profit organization’s goal of making this form of personalized therapeutic music a standard of care throughout the healthcare system.', ''), NULLIF('musicandmemory@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('New Worms Poetry Club', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('We, NEW WORMS, aim to provide a space and a community for the fomentation of artistic performance in its widest possible signification. Concretely, this will take the form of a recurring time and a physical place for artistic performance (again, in the broadest sense). We, NEW WORMS, will not take a distinctive stance on the form or content of these performances. Thus, we also commit ourselves to providing a rare type of collective space on campus; i) free from categorial restriction on art; ii) emphasizing live performances to an audience of (mostly) compatriot performers, poets, and souls; iii) and determined by the collective that attends, and tends, to it. If you are feeling disconnected, possibly detached, from your artistic soul; seek us out. If you are feeling the pangs of a spiritual hunger; seek us out. If you have something to show, something that needs to be seen; seek us out. We hope that this is enough to bewilder most of you, shake something loose in some of you, and reawaken those slumbering mysteries few. Here you’ll find a safe space for yourself and, by extension, your art. While we believe in performance as a primary force to poetry (and art as a whole), attendees are by no means obligated to perform at any meeting. That being said, come! perform!', ''), NULLIF('newwormspoetry@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Peaks and Professors at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of Peaks and Professors at UC San Diego is to foster meaningful connections between students and faculty by organizing outdoor excursions that combine exploration, learning, and conversations. Through hikes, nature-based activities, and shared experiences, the club aims to create an environment where students can engage in open discussions, build relationships, and explore diverse perspectives. Peaks and Professors is committed to promoting a sense of community, encouraging intellectual curiosity, and celebrating the natural beauty surrounding UCSD.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Persian Community at Hillel', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Persian Community at Hillel at UC San Diego (PCH at UC San Diego) aims to provide a strong and tight-knit community for Persian Jewish students at UC San Diego. Through events and community building, students will gain informal cultural support from their Persian Jewish peers and advisor. The Persian Community at Hillel at UC San Diego will also educate students on aspects of Persian Jewish culture during events.', ''), NULLIF('pchatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Nigerian Student Association at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('To create unity among individuals who share a common Nigerian identity. We wish to understand, engage, and celebrate Nigerian culture through creating community for these students to associate with each other. To stand in solidarity with causes and movements concerned with self-determination and the welfare of Nigerian people, and the country.', ''), NULLIF('nsaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Nikkei Student Union', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('To allow Japanese American, Japanese and any other interested student to interact in a socially conductive environment. To promote awareness of Japanese American and Japanese culture, history and issues on the UCSD campus. To provide a link between the Japanese American community on the UCSD campus and the Japanese American community in the areas surrounding UCSD.', ''), NULLIF('NSUatUCSD@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Phi Alpha Delta', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Phi Alpha Delta is the world’s preeminent law fraternity because of our dedication to service: service to the student, the school, the profession, and the community. It is through devotion to the ideals of compassion, courage, diversity, innovation, integrity, professionalism, and service that we better both our profession and our community. The purpose of this Fraternity shall be to form a strong bond uniting students and teachers of the law with members of the Bench and Bar in a fraternal fellowship designed to advance the ideals of liberty and equal justice under law; to stimulate excellence in scholarship; to inspire the virtues of compassion and courage; to foster integrity and professional competence; to promote the welfare of its members; and to encourage their moral, intellectual, and cultural advancement; so that each member may enjoy a lifetime of honorable professional and public service.', ''), NULLIF('padatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Musings', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('Musings is a publication for creative work related to the ancient Mediterranean. Musings strives to promote diversity in perspectives, topics, and formats. Just as the nine Muses of Greek mythology inspired innovation in their devotees, we hope for Musings to serve as an inspiration for students and scholars-in-the-making. This is especially important as the academic field of Classical Studies faces its past and expands to better represent antiquity and the changing demographics of modern scholars.', ''), NULLIF('musingsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Phi Beta Lambda (FBLA)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('We inspire and prepare students to become community-minded business leaders in a global society through relevant career preparation and leadership experiences.', ''), NULLIF('pblatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Muslim Graduate Student Association', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The MGSA at UCSD seeks to advance and retain the Muslim presence in the graduate academic sphere while maintaining a climate conducive to harmonizing Islamically advised lifestyles with the lives of Muslim graduate students in the university and workforce. By serving as a center of social, educational, and tangible resources, the MGSA at UCSD intends to strengthen members to embrace Islamic values as a source of guidance in their goals to contribute to the well-being of the public and attain spiritual fulfillment as individuals.', ''), NULLIF('yamanjandali@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Nu Alpha Kappa, Inc.', NULLIF('Multicultural Greek Council (MGC) - Fraternity', ''), NULLIF('Fraternity', ''), NULLIF('We, NU ALPHA KAPPA, seek to unite and involve all students in a more harmonious and brotherly atmosphere through academic, social, and cultural means. There is a need to interface the various backgrounds that constitute the student body of our fraternal university chapter, in order to improve relations amongst all students and the community.', ''), NULLIF('lambda.president@nakinc.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Nueva Herencia de UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Our mission is to unite Latinx individuals who assist and promote an inclusive community to fight against cultural stereotypes, embrace diverse cultures, and support students overcoming adversities in higher education. Built on the foundation of community, we strive for all members to become “La Nueva Persona” through promoting academic excellence, community service, and social networking.', ''), NULLIF('nuevaherencia@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Phi Delta Theta', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('Helping every individual to meet his true potential is the bedrock of the Phi Delta Theta Fraternity. By celebrating each person’s true self, and by learning from each other’s strengths while helping to improve each other’s weaknesses, every member of Phi Delta Theta develops into a greater version of himself than he could ever on his own. Rather than try to find young men to mold into some ideal, we celebrate the uniqueness of each individual and, through encouragement, values, example and brotherhood, empower every brother to exceed his personal expectations. As undergraduates, Phi Delts can take advantage of the Fraternity’s Pursuit of Greatness four-year membership development program, challenging them to grow personally and professionally by learning about valuable soft skills, taking on chapter officer positions, attending educational experiences such as the Kleberg Emerging Leaders Institute and the McKenzie President Leadership Conference, and earning badges and college credits that serve as a tangible demonstration of skills they have developed through their Phi Delta Theta experience. As alumni, Phi Delta Theta encourages its members to stay engaged and become their greatest version through volunteerism, mentorship, and networking with the vast Phi Delt network.', ''), NULLIF('pdtcakpresident@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Phi Gamma Delta', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('We, the founding fathers of the Chi Lambda Chapter of UCSD will endeavor to provide an opportunity for friendship, scholarship and service to our members now and in the future. We seek excellence. We believe that the Phi Gamma Delta Chapter we bring back to UCSD must take into account the unique circumstances of our university and our student body. In order to be successful we must adapt our program to be in harmony with other campus constituencies, such as our student athletes and student leaders.', ''), NULLIF('fijiatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Organization for Pre-Health Advising', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('OPHA strives to facilitate the journey of fellow students who are on a path to become healthcare providers in the future. Whether you seek a career as a medical doctor, PA, nurse, or even in the dental field, we will provide you with opportunities to expand your network in San Diego. Partnering up with organizations such as the American Red Cross and local medical and dental clinics, we will work to aid the needy and underserved through community service, while also benefitting participating students in strengthening their resumes and applications for professional schools!', ''), NULLIF('ophaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Musicians Club @ UC San Diego', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Our purpose is to provide a space for a diverse group of people passionate about music to connect and grow in a low-stress environment, as well as to offer opportunities to perform with others in front of an audience. We welcome those looking to play, perform, learn, launch their music career, or simply to join a community of people who love music. Our events include socials, live-performance opportunities, workshops with industry professionals, musical challenges, and more!', ''), NULLIF('musiciansclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Phi Lambda Rho Sorority, Inc.', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('The purpose of Phi Lambda Rho Sorority, Inc. is to promote academic excellence within its members, provide sisterhood, engage in community service, with emphasis in the Chicano (a) and Latino (a) community, and to instill the importance of retaining its roots for the sake of its identity by promoting the Chicano (a) and Latino (a) culture.', ''), NULLIF('flr.gamma.president@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Origami Folders at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To provide a venue for origami enthusiasts to fold and share their passion with others and to introduce beginners to the traditional Japanese art and its applications in math and engineering. Discord Link: https://discord.gg/KfTWB66Mp6', ''), NULLIF('origamifoldersatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Other People Magazine', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('UCSD''''s first campus-wide literary magazine. A space to embrace the creative spirit and explore the timeless experience of humankind through a fusion of language, art, image, and technology. We accept, edit, illustrate, and publish creative works by UCSD students.', ''), NULLIF('otherpeoplezine@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Phi Sigma Rho', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('Phi Sigma Rho is a national sorority for women and non-binary students in engineering, science, and engineering technology. The sisterhood is made up of women and non-binary students who are studying technical sciences, but also take part in campus activities and the social Sorority and Fraternity Life system. In addition to socials, the members of Phi Sigma Rho are involved in community service projects and philanthropies.', ''), NULLIF('xpsr.president@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Photonics Society at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The promotion of Optics and Photonics to the community shall be made through educational outreach to local High Schools and Middle School Students. Furthermore, our organization is required to maintain a faculty mentor from the Electrical and Engineering Department. Part of the directive of the Photonics Club at UC San Diego is to assist its members in attending conferences in order to learn about the latest advents in Optics and Photonics and network with students, researchers, professors and professionals in the industry so as to facilitate the growth in this community. An additional goal is to mentor its members in academia by providing support in an understanding of optics and photonics and by providing assistance in the presentation and publication of their research.', ''), NULLIF('spie@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Physician Assistant Student Society', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of the student society shall be to serve as the official organization for PA students of the Atkinson Physician Assistant Education program (PAE) and to provide leadership opportunities for professional development while in PA school.', ''), NULLIF('pastudentsociety@health.ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Phi Sigma Pi', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Phi Sigma Pi National Honor Fraternity is a co-educational honor fraternity with the purpose of fostering the ideals of scholarship, leadership and fellowship.', ''), NULLIF('psp@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pi Beta Phi', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('The mission of Pi Beta Phi is to promote friendship, develop women of intellect and integrity, cultivate leadership potential and enrich lives through community service.', ''), NULLIF('cakappapresident@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pi Kappa Alpha', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('Celebrate, educate, and develop a sense of community for students seeking cultural and Identity-based involvement opportunities. Support the university''''s academic mission by holding each member to high academic standards, providing resources for academic support, and recognizing educational achievements. Focus on the integration of values and ethics through membership development in leadership, equity, diversity, inclusion, and health education programs. Serve the community through direct service and promote awareness and financial support for beneficiaries through initiatives, programs, and philanthropies. Develop a support system for members through brotherhood and sisterhood programs.', ''), NULLIF('kappaphipikes@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pi Kappa Phi', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('Our mission is to create an uncommon and lifelong brotherhood that develops leaders and encourages service to others for the betterment of our communities. We envision a future where every Pi Kappa Phi embraces his role as a leader, puts service before self and improves the world around him.', ''), NULLIF('pikappatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pi Nu Gamma', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Pi Nu Gamma is an Asian-interest organization dedicated to promoting and celebrating Asian cultures, fostering a sense of community, and supporting the representation of Asian interests on campus. Our mission is to educate and raise awareness about the diverse cultural, ethnic, and social customs of Asian communities, while providing a supportive space for students to explore their heritage and identity. Through active participation in councils, committees, and programs with other cultural organizations, we aim to encourage dialogue, understanding, and positive relationships among all cultural groups at UCSD, ensuring a more inclusive and culturally enriched campus environment.', ''), NULLIF('pinugamma@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pink Ribbon Initiative', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Pink Ribbon Initiative at UC San Diego (PRI at UC San Diego) is a service student organization that aims to provide knowledge, aid, and awareness to one of the most common diseases in women worldwide, breast cancer. This organization will promote volunteerism, wellness, support on and off-campus on the issue and outward movement to spread awareness on a larger scale. PRI at UC San Diego will provide students with educational training, local professional panel speakers, wellness activities and socials, and a hand in providing grants to breast cancer patients in need.', ''), NULLIF('priatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('PKC Overflow', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To create a community of authentic believers and to witness our campus transformed by the revelation of Jesus Christ.', ''), NULLIF('yal116@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pilipino Undergraduate Society for Health', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('As members of the Pilipino Undergraduate Society for Health (PUSH), we believe in the academic empowerment of Pilipino American students. We are leaders of the Pilipino community who strive to be an active presence through service, who establish networking opportunities and collaborations, and who promote education and awareness of health issues in order to productively direct ourselves towards future goals in health professions.', ''), NULLIF('pushatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Plant Futures at University of California - San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The mission of this Organization shall be to educate and engage with students passionate about plant-centric food systems and provide a network through which they can apply this passion to better both their own lives and engage in meaningful professional development and career exploration.', ''), NULLIF('plantfutures@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Planned Parenthood Generation Action at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Planned Parenthood Generation Action at UC San Diego exists to educate the community about reproductive health and to translate increased awareness into reproductive justice activism on campus. PPGA believes in the fundamental right of every individual to make decisions about their reproductive health. PPGA advocates for policies that ensure equal access to comprehensive reproductive healthcare in settings that protect the essential privacy and rights of each individual. The organization also aims to provide accurate, accessible, and inclusive educational programs that enhance the community’s understanding of sexuality.', ''), NULLIF('ppgaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Platypus Affiliated Society at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Platypus is a project for the self-criticism, self-education, and, ultimately, the practical reconstitution of a Marxian Left.', ''), NULLIF('platypus1917sandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Poetry Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To provide a space where students can engage in, and share, creative writing. Carrying with it a focus on catering to the needs of more introverted students and general lovers of poetry as a written art form, not necessarily a spoken art form. For example, the club allows students the option, if they wish, to share their writing anonymously. Poetry clubs and literature clubs have historically had a very social focus in that they''''ve revolved around the public speaking aspect of creative written word. This facet of modern literature clubs is a reflection of the origins of the art form, in that they tend to focus on performative art. Here, that is not the case. We hold that poetry is a window into the soul, that it is extremely personal, and that it is very difficult for a largely untapped group of literature lovers, who, while they may have quite a few things they would benefit from expressing, struggle to share those expressions in any way that leaves them vulnerable or pressures them to engage in public speaking. We instead have a welcoming space that provides access to the tools, resources, and encouragement, to put pen to paper and make that inner voice heard In a way that focuses on the written aspect itself, as well as the raw emotion that fuels it. In addition, we want to prepare and encourage students to work toward the annual Muir poetry award, to hold writing workshops and help students learn to better express themselves, and ultimately to create a close knit community that encourages people who''''ve perhaps never even had the chance to write like this before, to do so. UCSD is largely a STEM focused university. It is because the standard academic life is expected to be so cold and calculated that we feel many students have had such little opportunity to express themselves in a creative way that''''s free from academic scrutiny. We hold that there needs to be a space that brings together those who wish to have a little more creative freedom in their life. A place separate from regular academic curriculum that gives them a place to feel, express, and share, in a way that''''s completely free of ridicule and any pressure whatsoever.', ''), NULLIF('poetryclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Poker Club', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Poker Club at UC San Diego is the hub for the poker community at UC San Diego to meet, learn, and play. We engage undergraduate and graduate students alike with varying poker backgrounds, from new players to those with professional tournament experience. We meet to play tournaments, hold workshops, and hear guest speakers. We are also committed to building relationships with trading and tech companies that rely on the quantitative and analytical skills poker demands for their business.', ''), NULLIF('pokerclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Political Voices for Change At UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purpose of this organization is to empower students from diverse backgrounds and career paths with a comprehensive understanding of politics. We aim to cultivate informed students who are interested in navigating and influencing the political landscape. Through dynamic education programs, workshops, and engaging events, we provide opportunities for meaningful dialogue, critical thinking, and active participation in civic life. By fostering a community of individuals, we encourage students to explore their voices and contribute to positive change in their communities and beyond.', ''), NULLIF('pvc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pollinator Club at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('To spread awareness about the importance of protecting native pollinators and their habitat at UC San Diego through active and collective change.', ''), NULLIF('pollinatorclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Polynesian Dance Club at UC San Diego', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Polynesian Dance Club was established for the purpose of promoting cultural awareness of the Polynesian Islands on campus through dance. Members are taught Hula Hawaiian, Ori Tahiti, and Siva Samoa from the ground up, so no experience is needed! Our dances will be showcased throughout the year: in person at crossover events; virtually on our social media pages, and in person at our Annual Ho''''ike (performance).', ''), NULLIF('pdc.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Poseidon''''s Closet', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The goal of Poseidon’s Closet is to provide a place for students who enjoy fashion, thrifting, and upcycling clothes to meet each other and make new friends. We will go off-campus to thrift stores, hold workshops with sewing machines to upcycle used clothing, and accept clothing donations. Members can make new friends and enjoy thrifting as a part of this club.', ''), NULLIF('poseidonscloset313@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Postgrad Puzzles & Proofs', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of Postgrad Puzzles and Proofs (PPP) is to provide an inclusive and engaging community for math graduate students who are interested in jigsaw puzzles. Through community-building events with refreshments and puzzles, we hope to contribute positively to the experience of being a math graduate student at UCSD.', ''), NULLIF('caseyperdue@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-Dental Society/Student Run-Free Dental Clinics @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To provide additional educational resources to Pre-Dental students through our general body meetings, special speaker series, and student run free clinics.', ''), NULLIF('apliang@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-Dental+Pre-Medicine Society @UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of our organization is to combine pre-dental and pre-medicine students. Together, we can hold events to fundraise for low-income elementary schools, homeless shelters, and third-world countries in need of supplies. The goal is to donate dental kits (emphasizing dental hygiene) and sports equipment (emphasizing health). We hope to educate members of our community about the importance of health by showing them presentations and videos. Apart from donations our club aims to provide helpful resources to incoming pre-dental and pre-medicine students by offering them clinical experience, shadowing medical professionals, upperclassmen advising, and a community of peers who share the same interests as them.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-health Persians at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Pre-health Persians at UC San Diego strives to provide a much needed support system for Persian students who are interested in pursuing health professions. Through this club, we want to strengthen our cultural and communal identity by providing a platform for Persians to come together to provide each other with insight as we begin the path of seeking a career in health care. Our organization serves to prepare students towards their prospective careers in the health fields through meaningful community service opportunities, shadowing, mentorship and access to test-preparation resources. We also aim to bring in guest speakers from different health professions to give students a better understanding of their possible future careers. Even though our goal is to create a community for persian pre-health students, we are committed to creating an environment that is welcoming to students of all identities and backgrounds.', ''), NULLIF('pratucsd@ucsd.edu', ''), NULLIF('@prehealthpersiansatucsandiego', ''), NULLIF('', '')),
  ('Pre-Medical APAMSA at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of our organization is to involve and educate pre-medical undergraduate students at UC San Diego on the health issues that pertain to the Asian community and enable them to serve the Asian Pacific communities throughout the greater San Diego region. As a pre-medical organization, we plan to educate our members on health issues that pertain to the Asian community, provide them with resources and insights into medical school, the medical school application process through a mentorship program.', ''), NULLIF('apamsaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-Meds Without Borders', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Pre-Meds Without Borders (PMWB) at UC San Diego is dedicated to advancing health initiatives through proactive engagement and high-impact volunteer work. By partnering with local non-profits and community organizations, we provide a platform that helps emerging healthcare leaders to make meaningful contributions within their respective communities. We aim to help our members get hands-on experience, connect with healthcare professionals, and promote health education in underserved communities.', ''), NULLIF('pmwb.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-Nursing Student Association at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Pre-Nursing Student Association (PRENSA) at UC San Diego is dedicated to establishing the presence of a pre-nursing community for students at UC San Diego aspiring to enter the nursing profession. By providing a foundation of educational resources, hands-on experiences, and professional development opportunities, organization members will be prepared for future advancements in nursing school and nursing professions. Through collaboration, mentorship, and advocacy efforts, members will enhance their understanding of the healthcare field, promote a commitment towards compassionate care, and support each other’s journey towards becoming empathetic healthcare professionals with obtained knowledge, insight, and information surrounding the field of nursing.', ''), NULLIF('prensa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-Pharmacy Society @ UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Pre-Pharmacy Society (PPS) is a student organization dedicated to supporting future pharmacists by offering workshops, volunteer opportunities, guest speakers, and networking events. Our mission is to prepare members for pharmacy school admission while also exposing them to the diverse career paths within the field of pharmacy. Beyond providing valuable resources and guidance, PPS fosters a welcoming community where students can learn, grow, and enjoy their journey toward a career in pharmacy.', ''), NULLIF('pps@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-Vet Student Association', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To inform and guide students who are interested in pursuing careers in veterinary medicine by introducing various resources such as volunteering opportunities and contacts with experienced professionals. In addition, the Pre-Veterinary Student Association at UCSD strives to create a positive community centered around helping one another reach their own individual goals within the field of veterinary medicine. A network of resources, support, and companionship will be fostered in order to motivate and encourage students to follow their chosen career paths. The club will help members refine their skills, improve their resumes, and expand their knowledge in preparation for applying to veterinary school.', ''), NULLIF('prevetatucsd@gmail.com', ''), NULLIF('@prevetatucsd', ''), NULLIF('', '')),
  ('Product Management Club @ UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('At Product Management Club, we believe in the transformative power of product management. We understand that products are more than just commodities; they are the building blocks of industries, solving real-world problems and shaping the future. We recognize products as the lifeline of businesses, connecting solutions to needs. Our commitment as a product club lies in providing a platform where individuals can connect, grow, and contribute to the evolution of product management practices. In our collaborative community, we strive to be curious, challenged, and innovative. Members will gain valuable insights into the dynamic field of product management, foster a deeper understanding of strategic decision-making, customer-centric approaches, and the pivotal role of technology in delivering successful products. Through our collective expertise, we aim to drive excellence in product development and inspire undergraduate students to lead with impact in their careers.', ''), NULLIF('pmcatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Producers and Remixers Organization at UC San Diego', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('We are here to educate and to help promote students within UCSD to make and publish their own music!', ''), NULLIF('producersandremixersorg@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Project Happiness', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Project Happiness empowers a dynamic and dedicated corps of UCSD student volunteers to bring programming, recreational (arts), educational (tutoring and mentoring) and social service (health & dental counseling) to families of children affected with medical challenges in the San Diego area. Volunteers will selflessly donate their time to create program materials and deliver programs. Our volunteers will help relieve the anxiety of these afflicted families through a context of fun and play and help foster a spirit of courage to confront challenges that lie ahead. Project Happiness volunteers will spread happiness by restoring a sense of normalcy to the pediatric healthcare environment.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Saudi Students Association @ UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('• To unite Saudi students and those interested in Saudi culture • To orient incoming Saudi students to the university environment and assist them in their effort to adjust to the new community • To facilitate social and intellectual interaction between members • To function as a formal body for the purpose of information exchange • To Share and represent the Saudi Culture on campus', ''), NULLIF('saudistudents@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Scent Lab', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Scent Lab is dedicated to exploring the art and science of fragrance. Our mission is to provide UCSD students with opportunities to learn about perfumery and the cultural significance of scent. Through workshops, discussions, and hands-on projects, we aim to foster both scientific curiosity and creative expression within the world of fragrance. We will host events such as fragrance sharing workshops, group review sessions, and a lending library of perfumery-related books and resources. By engaging students from diverse academic and cultural backgrounds, Scent Lab seeks to create an inclusive community where members can share knowledge, experiment with various scents, and develop transferable skills in creativity, collaboration, and critical thinking. Ultimately, the organization strives to enrich the UCSD campus community by introducing fragrance as a unique medium of cultural exchange, self-expression, and interdisciplinary exploration.', ''), NULLIF('scentlab77@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Scholars Society at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('To promote personal and academic development among UC San Diego merit scholarship recipients, to facilitate networking between UC San Diego scholars and alumni, and to provide service for the surrounding community. Connected to UC San Diego Academic Enrichment Programs.', ''), NULLIF('scholarssociety@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pre-PA Student Organization (PPASO)', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('PPASO''''s mission is to inform students about the physician assistant (PA) profession and to provide members with the resources that will best help them achieve their goals of entering PA school. PPASO seeks to accomplish this mission by educating students about the process of becoming a physician assistant, collaborating with invaluable resources such as physician assistants, medical professionals, alumni, and UC San Diego faculty, and fostering camaraderie within the organization through unique experiential opportunities.', ''), NULLIF('ppasoatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Science Olympiad @ UCSD', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('To volunteer for the Science Olympiad community in Southern California and San Diego. Discord: https://discord.gg/g3hmzSnzKX', ''), NULLIF('jasonchang@socalscioly.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Product Space at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('New products are the lifeblood of any company and cornerstone of any economy. Yet, the most prestigious higher education institutions lack meaningful communities dedicated to the intersection of business and technology. Product Space solves this problem. We teach students from all backgrounds how to create and analyze products and offer a space for students to apply their skills in product management, product marketing, and product design. Through these activities, our vision is to create a cross-campus product family invested in its members’ success as future product leaders.', ''), NULLIF('productspaceatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Redeemer’s Grace Church on Campus at UC San Diego', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('We are part of a local church called Redeemer''''s Grace Church of San Diego. We seek to proclaim the gospel of Jesus Christ and one of our ministries is to the college campus of UC San Diego.', ''), NULLIF('cays@rgcsd.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Scientific Experiments to Amaze and Motivate', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Science Experiments to Amaze and Motivate (SEAM) is dedicated to advancing STEM education by engaging elementary school students in interactive, hands-on scientific demonstrations. Our mission is to inspire intellectual curiosity and increase access to early science enrichment. Through outreach led by trained undergraduate volunteers, SEAM fosters mentorship, community partnership, and a sustained interest in science among young learners to lay the foundation for the next generation of scientists.', ''), NULLIF('seamatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Reformed University Fellowship International', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The purpose of Reformed University Fellowship International at UC San Diego is to glorify God by believing, living, and proclaiming the good news of Jesus Christ in word and deed among the international community at UC San Diego. We seek to accomplish this in three key ways: (1) welcome and show hospitality to students and scholars from all nations; (2) explore the gospel of Jesus Christ with interested students and scholars; and (3) equip those students and scholars who want to honor and enjoy God in every area of life.', ''), NULLIF('rufiatucsandiego@ruf.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Scripps Education Association', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Scripps Education Association at UC San Diego has assembled to represent the interests of the three majors at Scripps Institution of Oceanography: Marine Biology, Geosciences, and Oceanic and Atmospheric Science, in addition to the Environmental Systems program. This club will provide professional and educational support as well as an outlet for community service and recreational activities. Students involved will have access to community service opportunities, social events, professional assistance, and scholarship funds raised by club members.', ''), NULLIF('sea.sio.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Revelle''''s Garden', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The primary purpose of this club is the continued maintanance and development of the Revelle Garden, located near Revelle''''s formal lounge, along with promoting environmentalism, locally grown produce on campus, and fostering a collaborative community.', ''), NULLIF('revellegarden@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Scripps Student Symposium Committee', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Scripps Student Symposium Committee plans, organizes, promotes, and hosts the annual Scripps Student Symposium. The Committee seeks to promote student research and collaboration across disciplines within Scripps Institution of Oceanography as well as the broader UCSD community.', ''), NULLIF('sss@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Roblox + RBXDev at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Roblox + RBXDev is a club that utilizes and hosts events talking about Roblox and development on the platform! Whether it be fun game nights, exciting discussions about upcoming projects, or chill socials to meet new friends, we aim to bring together game developers, artists, music creators, and players, fostering a collaborative group of members. Let’s power our imagination together!', ''), NULLIF('rbxdev.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sciencible', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Research and Discovery of Science and Technology', ''), NULLIF('admin@sciencible.io', ''), NULLIF('', ''), NULLIF('', '')),
  ('SDx @ UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('SDx @ UC San Diego is a home for all the builders and creators of UCSD. We cultivate a community of founders through hosting events such as hack days (sponsored by companies like Anthropic, Perplexity, Groq, and more - 6 hours of building along with demoing what was built), demo days (where members showcase their projects), speaker events (featuring founders, and seasoned entrepreneurs), and dinners. We strengthen connections with Venture Capitalists and founders to give our members a strong network.', ''), NULLIF('hello@sdxatucsd.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Seal Society Club at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our purpose is to educate the public about the importance of seals and sea lions in La Jolla Shores, with the emphasis of protecting mothers and pups. We want to provide educational opportunities for students to become docents, where they learn and advocate for the protection of these animals. The Seal Society Club at UC San Diego understands that the Sierra Club San Diego Chapter and its volunteers do not assume legal liability for the actions of the organization or its members.', ''), NULLIF('sealsociety@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Robotic Graduate Student Organization (RoboGrads)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('RoboGrads is a graduate student organization affiliated with the Contextual Robotics Institute (CRI) at UC San Diego. As an organization, we connect graduate students through academic, professional, and social events to foster a stronger and more inclusive robotics community at UCSD. In doing so, we develop relationships amongst both graduate and undergraduate students that promote interdisciplinary research collaborations, provide opportunities for learning and sharing robotic knowledge, and address the needs of the robotics community.', ''), NULLIF('robochairs@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Serotones', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('The purpose of this association shall be a non-profit organization for pharmacy students at UC San Diego Skaggs School of Pharmacy and Pharmaceutical Sciences with an interest in music dedicated to providing relief to patients in hospitals and other health settings through music.', ''), NULLIF('jet010@health.ucsd.edu', ''), NULLIF('@serotonesatUCSD', ''), NULLIF('', '')),
  ('Rocket Propulsion Laboratory', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of Rocket Propulsion Laboratory at UC San Diego is to help students develop engineering capabilities and promote good engineering practices to prepare them for industry careers. In pursuit of this goal, Rocket Propulsion Laboratory at UC San Diego will focus on designing innovative propulsion systems and launch vehicles for aerospace applications. Members will learn how to conduct effective research and implement that research in practical applications. By developing these systems from the ground up, members will gain experience and skill in the areas of design, analysis, testing, fabrication, safety, and flight hardware operations. Please direct inquiries regarding applications to rocket@ucsd.edu and visit our website at rocketproplab.org for more information on current programs.', ''), NULLIF('rocket@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('ShaDjam', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('ShaDjam is a student-led organization at UCSD dedicated to celebrating and promoting Indian Classical music. Our mission is to create a welcoming space where students can learn, perform, and collaborate across vocal, instrumental, and percussive traditions. Whether you are an experienced performer or a curious beginner, we invite you to explore this timeless art as both a musical practice and a cultural expression. Through workshops, concerts, and lecture-demonstrations, ShaDjam fosters community, creativity, and a deeper appreciation for the discipline, diversity, and emotional richness of Indian Classical music.', ''), NULLIF('shadjamatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Rho Epsilon Iota @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Rho Epsilon Iota at UC San Diego (REI@UCSD) is a student organization dedicated to advancing real estate education, leadership, and networking opportunities for undergraduate and graduate students. Through workshops, mentorship programs, and collaborative projects, members gain exposure to residential, commercial, and investment real estate while developing professional and interpersonal skills. REI@UCSD aims to foster a supportive environment that promotes ethical conduct, community involvement, and a passion for real estate as both a field of study and a career pathway.', ''), NULLIF('reiatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Roger''''s Community Garden', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Functioning underneath the University of California - San Diego Urban Studies and Planning department, Roger''''s Community Garden is home to a variety of student-led projects designed to help reduce food waste and carbon emissions while simultaneously producing organic, locally-grown produce for the UCSD Food Co-op and the Triton Food Pantry. Some examples of our student research projects are converting campus food waste into organic fertilizer, maintaining aquaponic and hydroponic systems, and cultivating edible oyster and shiitake mushrooms from coffee grounds.', ''), NULLIF('rogerscommunitygarden@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Role Playing Games Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To encourage networking among the gaming community and introduce the UCSD community to role-playing games.', ''), NULLIF('rpg@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Shifa Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Shifa Society of Muslim Pre-Health Students is an organization dedicated to the pre-health professional development of members through the abridgment of deen (religion) with dunya (worldly life) to build a community of successful health professionals and sustainable Muslims.', ''), NULLIF('shifasocietyatucsd@gmail.com', ''), NULLIF('@shifasocietyatucsd', ''), NULLIF('', '')),
  ('Room 264 Chamber Music Club', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Room 264 is a space for anyone at UC San Diego who loves chamber music. We host weekly sessions on Saturday evenings where you can join a group, try out new pieces, or just hang out with other musicians. We also help connect members with gigs, concerts, and opportunities on and off campus. No auditions and no pressure!', ''), NULLIF('room264@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Shining Smiles Alliance @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('We are committed to promoting lifelong oral health and building confidence within our community. Our aim is to educate the community on healthy dental habits, alleviate dental anxiety for patients, and increase access to essential oral health resources for underserved populations. By fostering early awareness and making dental care more approachable, we strive to empower individuals and families to prioritize their well-being and embrace brighter, healthier smiles.', ''), NULLIF('shiningsmilesalliance@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sigma Alpha Mu Fraternity', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('To unite each undergraduate member toward a more meaningful life, to prepare members for responsible fraternity and community involvement. And to encourage true manhood, democracy, and humanity.', ''), NULLIF('prior.samatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Rooted at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of Rooted @ UC San Diego is to create a safe space where students can build community, slow down, and reconnect with each other, themselves, and the earth. In the middle of everything happening in the world, we believe that caring for something living (even something small like a houseplant) can ground us and remind us that growth is still possible. Plants don’t just grow. They teach us patience, presence, and intention. As we care for them, we’re also caring for ourselves and one another. Plant care can be self-care. At Rooted @ UC San Diego, we see plants not just as something to keep alive, but as something that helps US feel more alive, too. Our mission is to use houseplants and plant care to nurture ourselves, build connection, and stay grounded in times that feel especially heavy, whether due to politics, current events, burnout, or just life. Through plant swaps, educational events, repotting parties, community hangs, and much more, Rooted @ UC San Diego is here for students who need a breather. We grow here. Emotionally, socially, and collectively. Everyone is welcome.', ''), NULLIF('rootedatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sigma Gamma Rho Sorority Inc., Eta Delta Chapter', NULLIF('National Pan-Hellenic Council Organizations (NPHC)', ''), NULLIF('Greek Life', ''), NULLIF('It is the mission of Sigma Gamma Rho Sorority Inc. to enhance the quality of life for women and their families in the U.S. and globally through community service, civil, and social action. Our goal is to achieve greater progress in the areas of education health awareness and leadership development. Our members, affiliates, staff, and community partners work to create and support initiatives that align with our vision.', ''), NULLIF('etadelta1922@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Rooted in Wellness', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The goal of Rooted in Wellness is to empower students with the knowledge about healthy living through the pillars of sleep, exercise, food, social connection, mental health, and spiritual health. Through educational seminars, infographics, and events, we aim to raise awareness about the health impacts of the aforementioned pillars. We seek to create a meaningful community through volunteer opportunities where members can contribute to community efforts to educate and take meaningful action to improve the pillars of health. Members will benefit from engaging in social events, networking seminars, and a chance to earn volunteer hours while actively improving their lives through one of the pillars. Rooted in Wellness aims to bring together students from all walks of life who are looking for a community that can give students the tools to improve their lives through a holistic approach.', ''), NULLIF('rootedinwellnessatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Shift Towards Hope at UC San Diego.', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Shift Towards Hope is a student-led organization dedicated to empowering young children to build emotional resilience and mental well-being through compassionate, research-backed storytelling. By co-creating age-appropriate books and resources with mental health experts, we help children understand their emotions, spark meaningful conversations with caregivers, and develop lifelong coping skills. Through partnerships with schools, clinics, and global organizations, we work to ensure that every child—regardless of background—feels seen, supported, and emotionally equipped to thrive. Members of Shift Towards Hope gain hands-on experience in advocacy, outreach, and creative development. They collaborate with psychologists, educators, and community leaders to design impactful resources and lead initiatives that support children and families. Whether contributing to storytelling, organizing workshops, or building partnerships, members develop professional skills in communication, leadership, and emotional intelligence—while making a tangible difference in the lives of others. The organization offers a space for personal fulfillment, creative expression, and meaningful community engagement. On campus, Shift Towards Hope fosters a culture of emotional awareness and interdisciplinary collaboration. By normalizing mental health conversations and reducing stigma, we empower students to lead with empathy and purpose. Our initiatives bridge academic insight with real-world advocacy, positioning UCSD as a hub for innovation in child and family mental health. Through inclusive leadership and outreach, we strengthen ties between the university and surrounding communities, ensuring that emotional wellness becomes a shared priority across generations.', ''), NULLIF('outreach@shifttowardshope.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('ROOT[D at UC San Diego', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('ROOT[D is a project dance team with the aim to develop and showcase dancers within the UC San Diego/San Diego community. As the only South Asian dance team that encompasses a wide breadth of styles such as Kuthu and Hip-Hop, we focus on developing skills for the sake of growth, not competition. Through our dance styles and welcoming environment, we cultivate diversity and encourage our dancers to become comfortable with being uncomfortable.', ''), NULLIF('sd.rooted.dance.co@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sigma Kappa Sorority', NULLIF('College Panhellenic Association (CPA)', ''), NULLIF('Sorority', ''), NULLIF('The purpose of Sigma Kappa Sorority is to unite its members in a bond of sincere friendship for the development of character and the promotion of social, philanthropic, and intellectual culture.', ''), NULLIF('president.skzetamu@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Roots of Care for Refugees', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of Roots of Care for Refugees (RCR) is to encourage students from a diaspora of backgrounds to contribute to cultivating accessible healthcare for the refugee/asylum seeker community residing in San Diego. As the rebrand of the club, Welcome Home, RCR consists of three branches: 1- Social outreach, 2- Health Outreach, and 3- Research and education to collectively contribute and advocate for the rights of refugees to access equitable healthcare, along with advocating for the expansion of their rights.', ''), NULLIF('rootsofcareforrefugeesatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sigma Nu', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('To promote scholastics, a positive social environment, philanthropy, sports, and leadership for UCSD students.', ''), NULLIF('kapparhocommander@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sigma Omicron Pi', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('To promote Asian American Awareness through unity, friendship, leadership, and service. Our organization was originally created by ten Asian American women pursuing the interest of teaching. Though, our sorority, no longer centers around the interest of teaching, it still maintains its commitment to the Asian American community. All of our chapters have become extremely involved in their respective communities, volunteering our time at community agencies and raising money to donate to favorable charities.', ''), NULLIF('sdsopi.president@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Rubik''''s Cube Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To bring cubers and non-cubers together to learn more about solving the Rubik''''s cube, cuboids, or any other puzzles.', ''), NULLIF('cubingatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Salsa Society', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('At Salsa Society, we foster a fun and interactive learning environment where we share our love of dance. Weekly classes are held every Saturday. where we teach our members the fundamentals of salsa and bachata. We hope to provide a connection to each other as well exercise of body and mind through dance.', ''), NULLIF('salsasocietyatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sigma Phi Epsilon', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('To impress upon its members the true significance of fraternal relationships and to create and perpetuate friendship among all persons in the chapter. To develop and strength the character of its members; promote the principles of Virtue, Diligence, and Brotherly Love; and preserve the ideals upon which this fraternity was founded. To instill upon those principles which are the responsibilities of an individual as a member of society.', ''), NULLIF('calrhopresident@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sigma Pi Alpha National Sorority, Inc.', NULLIF('Multicultural Greek Council (MGC) - Sorority', ''), NULLIF('Sorority', ''), NULLIF('Sigma Pi Alpha is a Chicana/Latina based sorority that focuses on community service, campus involvement, and sisterhood and within these components we stress academics and cultural awareness. We hope to provide women with the means to access higher education and to provide women on campus with community service opportunities and academic, personal, and individual support. Although we are a Chicana/Latina based sorority, our sisterhood reaches out to all different ethnicities.', ''), NULLIF('iotachapter.president96@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sitaare', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Sitaare is UCSD’s premier award-winning South Asian fusion A Cappella team. Since our inception in 2006, we have taken pride in our diverse vocal talent, and strive to bring creativity, variety, and culture into our repertoire. We enjoy performing various genres of both South Asian and Western music, ranging from Indian Classical and Bollywood to R&B and Pop. We travel across the country and compete in the ICCA and South Asian A Cappella circuits. In addition to UCSD’s annual cultural events, we also perform at private events in San Diego, the Bay Area, and beyond. Sitaare is always looking to push the boundaries of Desi A Cappella and reach for the stars!', ''), NULLIF('sitaare.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Saltman Quarterly', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('The purpose of "Saltman Quarterly" (SQ) is to provide a medium for undergraduate students at UCSD to publish biological research as well as communicate new advances in the field of biology, encompassing topics ranging from medicine to ecology. SQ also provides authors and staff members with the skills needed to communicate science effectively to both biology and non-biology majors.', ''), NULLIF('saltman@biology.ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('San Diego Coptic Club', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The purpose of this club is to create a home away from home for students from the Coptic Orthodox community as well as a home for others who hope to find a home away from home. We hope to radiate God’s light within the community.', ''), NULLIF('Copticclubsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sikh Student Association', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To promote awareness of Sikhism and inform others of its principles while building a close knit community.', ''), NULLIF('ssa.atucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('SKY Campus Happiness at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('This organisation will act as a group for teaching and practicing yoga and meditation, offered in a group setting by certified instructors. The group will meet regularly, at least weekly for practice sessions. Inculcating these activities in daily routines has been shown to improve mental health, resilience, and social connection among groups of people. We aim to offer a SKY Campus happiness program every quarter which teaches stress management and overall wellness through Yogic stretches, meditation, and breathing techniques. The retreat further focuses on building a positive mindset of service and leadership among its participants. This is achieved by letting participants design and implement social outreach projects on campus.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('San Diego Indonesian Association (SDIA)', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('To promote Indonesian culture to University of California, San Diego community through social and other nonprofit events. To create camaraderie between the members To build a network with other Indonesian clubs. Provide a community for Indonesian students at University of California, San Diego, as well as people interested in the Indonesian community. Educate the student body about INDONESIAN culture, history, identity, and issues. Cultivate a culture of racial and gender inclusivity. Provide opportunities for leadership development, student engagement, networking, and service.', ''), NULLIF('permias.sandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('SIO in situ Zine', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('In situ is a student-led zine that captures the creative, critical, and curious spirit of the Scripps Institution of Oceanography (SIO) community. Through written word, visual art, photography, and multimedia formats, in situ provides a platform for UC San Diego''''s SIO community members to reflect, reimagine, and express their experiences and perspectives on science, the ocean, academia, and life at Scripps or San Diego—in situ and beyond.', ''), NULLIF('sio-insitu@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Rotaract Club at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of Rotaract is to follow Rotary International''''s motto of "Service Above Self." We are devoted to organizing and participating in both local and international service events. In addition, we strive to prepare our members for the future by offering professional development, leadership, and networking opportunities.', ''), NULLIF('rotaractatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sleepless Collective', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Sleepless Collective aims to connect with people through dance and create humble community leaders and innovative performances.', ''), NULLIF('sleeplesscollectivedance@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Social Justice for Sudan', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Social Justice for Sudan is dedicated to confronting injustice by spreading truth, raising awareness, and educating others about the humanitarian crisis unfolding in Sudan. We center the voices of innocent people affected by the violence, sharing their stories alongside verified information, resources, and clear ways to take action.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('San Diego Injury Prevention Program', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The San Diego Injury Prevention Program facilitates community well-being through volunteering events, research, education, and resource dissemination. Our current endeavors include longevity and mobility classes taught weekly at senior residential facilities, health fairs for underserved populations, injury prevention presentations, joint events with UCSD trauma and Scripps, and much more. Volunteering is flexible (held on weekends at various times), meaningful (you can develop bonds with many people such as seniors and learn their health stories), as well as designed to build your pre professional skills. We ask for no membership fee, have no prerequisites, have no minimum volunteering requirements, and provide relevant training to support your success. SDIPP is part of the California Injury Prevention Program, an expanding undergraduate organization with chapters at UCLA and UC Davis. Volunteers are encouraged to join one of our 6 committees to get more involved in our expansion across San Diego county and into other areas of California. We look forward to working with you!', ''), NULLIF('sdinjurypreventionprogram@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('SISTERS at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('In a cross-sectional study of 9th-grade students, girls reported significantly lower mathematics self-efficacy and state self-esteem compared with boys, although their academic achievement in mathematics did not differ significantly (Raufelder et al., Frontiers in Psychology, 2020).Results from the Girls’ Index national survey indicated that only 59% of adolescent girls reported feeling proficient in mathematics and science in 2022, a decline from 73% in 2017. In the same survey, 58% of girls reported believing they were not smart enough to pursue their desired careers, compared with 46% in 2017 (Ruling Our eXperiences [ROX], 2022). Our club seeks to close the confidence gap by helping younger girls develop belief in their own abilities while gaining early exposure to STEM concepts. By learning alongside girl friends in a supportive community, participants can share experiences, practice teamwork, and encourage one another. Through mentorship, engaging discussions, and approachable activities, we aim to normalize the idea that girls can thrive in science and mathematics. The focus is not only on understanding STEM topics but also on reshaping self perception, so that girls see themselves as confident, capable, and free to pursue opportunities in these fields.', ''), NULLIF('sisters.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Social Media Production Lab', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('Social Media Production Lab (SMPL) is a student-run club focused on learning and creating high-impact social media content. SMPL brings students together to develop practical content creation skills, including crafting strong hooks, optimizing posting timing, and understanding what captures attention online. The club operates through short, hands-on lessons during the week and frequent social events that double as content opportunities. By using real campus experiences as creative material and scaling events over time, SMPL aims to increase student engagement and help challenge the perception of UCSD as socially disconnected.', ''), NULLIF('reallysmpl@yahoo.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('SangamSD', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The largest South Asian organization at UC San Diego, SangamSD aspires to promote South Asian cultural awareness and education within the UC San Diego community and beyond. SangamSD''''s goals of uniting South Asians at UC San Diego as well as spreading diversity, tolerance, and the understanding of all South Asian cultures is reflected through its numerous social, cultural, and educational events.', ''), NULLIF('sangamsd@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('SandDiego Volleyball Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To bring together beach volleyball lovers of all levels to have fun and play some volleyball!', ''), NULLIF('sanddiegobeach@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society for Advancement of Chicanos/Hispanics and Native Americans in Science (SACNAS) Chapter at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('SACNAS is an inclusive organization dedicated to fostering the success of Chicanos/Hispanics and Native Americans, from college students to professionals, in attaining advanced degrees, careers, and positions of leadership in STEM.', ''), NULLIF('sacnasatucsd@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sapphic Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Sapphic Club shall foster a safe space for friendships, mentorships, and community among sapphics through facilitating social events. Since sapphics are part of a student minority on campus, the club aims to promote their sense of belonging.', ''), NULLIF('sapphicclubatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Asian Scientists and Engineers at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Chapter is committed to preparing members for success in the global business world, celebrating diversity, and contributing back to the community. The objectives and goals of the Chapter shall be to: 1. Support and develop programs that provide for the advancement of Asian heritage scientists and engineers. This goal shall be implemented by: -Career Workshops -Seminars and Symposia that focus on bettering the employability of members by bolstering the soft skills of members, working on their resumes, and teaching interview skills. 2. Develop and support programs that aid Asian heritage scientists and engineers who are actively seeking careers. -Interactions with potential employers -Tutoring/Curriculum assistance -Mentoring programs 3. Provide a forum for professional development and for the connection with entrepreneurial opportunities. 4. Inform the public of contributions and advancement made by Asian heritage scientists and engineers in newsletters and awards ceremonies.', ''), NULLIF('saseatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Civil and Structural Engineers', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Society of Civil and Structural Engineers (SCSE) is the UC San Diego student chapter of the American Society of Civil Engineers (ASCE) and the Structural Engineers Association of San Diego (SEAOSD). Our purpose is to supplement the engineering education of UCSD students, promote the personal and professional development of our members, and improve the community of which we are part of through outreach and community service.', ''), NULLIF('scse.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Cosmetic Chemists at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('We promote cosmetic science and technology in the UCSD community. As a pre-professional organization, we prepare undergraduates for the global cosmetics industry with research and development, finance, and marketing teams. We also host community engagement events which allows hands-on experience with cosmetic chemistry to the UCSD community.', ''), NULLIF('sccatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Hispanic Students in Law', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Uplifting the next generation of lawyers, justices, and policymakers through community building and empowerment. Through a variety of workshops, open discussion forums, professional development opportunities, volunteerism, and debate competitions, the Society of Hispanic Students in Law fosters the ideal environment for aspiring Hispanic legal scholars to gain the skills necessary to excel in America’s legal arena.', ''), NULLIF('sohilatucsd@gmail.com', ''), NULLIF('sohil_at_uc_sandiego', ''), NULLIF('', '')),
  ('Society of Hispanic Professional Engineers', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of SHPE at UC San Diego is to promote the advancement of Hispanics in math, science, engineering and other technical fields through our student chapter benefits; including but not limited to Professional Development, Academic Development, and Community Service. SHPE at UC San Diego is a non-profit student organization.', ''), NULLIF('shpe@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Immigrant and Refugee Health', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('SIRH strives to improve the healthcare of refugees and immigrants by addressing equity in healthcare. We want to educate our community and provide a space to better understand refugees and immigrants, and improve healthcare practices by doing so.', ''), NULLIF('sirhatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('STEM Educators & Researchers for Volleyball Events', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('STEM Educators & Researchers for Volleyball Events (SERVE) aims to foster camaraderie and engagement among scientists that work as educators or researchers across UC San Diego through volleyball-related social activities. Playing volleyball alongside each other will create a more inter-connected scientific community while also benefitting the health and wellness of employees and student researchers.', ''), NULLIF('SERVE.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Undergraduate Mathematics Students (SUMS)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('SUMS provides resources, workshops, talks, and social events for the mathematics community at UC San Diego with the goal of promoting mathematics and related fields.', ''), NULLIF('sums@ucsd.edu', ''), NULLIF('@sumsatucsd', ''), NULLIF('', '')),
  ('SAP-VN at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('SAP-VN at UC San Diego is a chapter of SAP-VN, a humanitarian nonprofit based out of Garden Grove. SAP-VN at UC San Diego hopes to connect UCSD students to our local community outreach to the vulnerable Vietnamese populations of San Diego.', ''), NULLIF('sapvnatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('STEMagination @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Stemagination is dedicated to inspiring curiosity and fostering a love for science among underserved youth in the San Diego area. Through hands-on weekly science projects and engaging STEM experiences, we aim to make science accessible, exciting, and relevant. By collaborating with UCSD faculty, career advisors, and student volunteers, we will create pathways for students to explore their academic and professional potential in STEM fields.', ''), NULLIF('stemaginationatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Women Engineers (SWE)', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Motivate women to achieve full potential in careers as engineers and leaders, expand the image of the engineering profession as a positive force in improving the quality of life, and demonstrate the value of diversity.', ''), NULLIF('swe@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sociology Community', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The goal of the Sociology Community is to provide a stable, foundational, home base where students interested in the subject can meet, share ideas, and access resources. We seek to promote interconnection between students and provide connections between students and the sociology department. Members within this organization will receive access to like-minded individuals who share an interest in Sociology. They will also receive opportunities to network amongst themselves and with other sociology faculty and alumni.', ''), NULLIF('jeguo@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Strides Running Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('We''''re a social, casual distance running club at UCSD for runners of all skill levels — from beginners who are just interested in giving it a try, to seasoned athletes training for big races! You''''ll almost always have someone to run with and you''''re guaranteed to make a few new friends. We also run in local races and host a variety of social events. Join our Discord — you don''''t want to miss out on the announcements!', ''), NULLIF('stridesatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Society of Physics Students at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The purpose of this organization shall be the advancement and diffusion of knowledge of physics, the encouragement of interest in physics throughout the academic and local communities, and the introduction of students to the professional community. We are devoted to fostering a welcoming and inclusive social and academic community for all UCSD undergraduates interested in physics. Our events include research presentations, educational talks, socials, lab tours, the physics graduation ceremony, and more!', ''), NULLIF('spsatucsandiego@gmail.com', ''), NULLIF('sps_atucsd', ''), NULLIF('', '')),
  ('StRIVE', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('We are a peer mentorship program that works with students from TRACE (Transition Resources for Adult Community Education) ages 18-22 who have mental and/or physical disabilities. We come together to teach them skills to further their independence and help them transition into adulthood!', ''), NULLIF('striveatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Soka Gakkai International Buddhist Club', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The Soka Gakkai International Buddhist Club (SGI-BC) serves as the place for the students who want to study Nichiren Buddhism and learn the philosophy of Buddhist philosopher, peacebuilder, educator, and writer, Daisaku Ikeda, who has received over 400 academic honors. The fundamental purpose of the SGI-BC is to help students unlock their hidden potential and achieve creative harmony with their environment through the philosophy and practice of Nichiren Buddhism in the SGI-USA. This is the ultimate expression of individual empowerment where each student can transform the inevitable challenges of daily life into sources of growth and fulfillment and become a positive influence in his or her school, workplace, family and community. By promoting and understanding of how Nichiren Buddhism can be applied to the challenges of modern living, our activities contribute to the development of peace, culture, and education within society, inspire respect for cultural diversity and human rights, and encourage the protection of nature and the environment.', ''), NULLIF('sgi.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Soon Movement Global', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('To help fulfill the Great Commission at UC San Diego by training students to live out a Christian life after College through discipleship groups, prayer meetings, worship sessions, and fellowship. Soon Movement Global is a non-profit, non-denominational Christian organization.', ''), NULLIF('sdsoonmovement@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Student Health Advocates', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Student Health Advocates (SHAs) are trained, volunteer peer health educators that educate other students about health issues and concerns through educational workshops, events, and campaigns. SHAs address topics such as alcohol, drugs, stress, healthy eating, physical activity, and sexual health.', ''), NULLIF('studenthealthadvocatesatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('SPARK', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('SPARK is a science outreach program created to increase awareness about STEM related topics and reduce educational disparities in middle school students from underserved communities. Through an interactive science theater program, we aim to foster interest in STEM-related subjects and bring students joy through hands-on science activities, fostering critical thinking skills about scientific processes. Moreover, we hope to provide students with the information and resources they need for success in STEM careers, empowering them to achieve their goals. Ultimately, our mission is to bring a unique educational experience to middle schoolers and promote equality within this dynamic and multifaceted field. Interested members can fill out the following form: https://docs.google.com/forms/d/e/1FAIpQLSdN6SFMy_simV9M9KS_nDTvDIPpE6hirl3gnEyCpeEK9KHrhQ/viewform?usp=dialog', ''), NULLIF('sparkatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Student HOMES Coalition at UC San Diego Chapter', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Student HOMES Coalition seeks to end student homelessness through legislative advocacy. Collaborating with student groups, non-profits, and legislators, we develop policies to advance student tenants’ rights, fund affordable housing, and promote the development of on and off-campus housing. We also work directly with local officials to implement innovative solutions to student housing issues in campus communities. Finally, we collaborate with professors to expand the availability of housing research and curriculum on our university campuses. Through these avenues of advocacy, activism, and education, we hope to make it so that every student has a safe and affordable place to call home during their time in college.', ''), NULLIF('soreeves@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Speech, Physical, Occupational Therapy (SPOT)', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('SPOT''''s purpose is to provide a safe space for individuals interested in speech, physical, and occupational therapy by networking, hosting speakers from the field, and providing information about the application process.', ''), NULLIF('spotclub.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sports Care, Ortho & Pre-health Exploration', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('Sports Care, Ortho & Pre-health Exploration or SCOPE at UC San Diego is dedicated to exploring the surgical and orthopedic dimensions of sports-related injuries through education, skill-building, and professional networking. Through these three pillars, we provide students with opportunities to gain insight into a surgical career, develop practical skills, and engage with medical professionals. Our mission is to foster a community of aspiring healthcare leaders while making the highly restricted world of surgery more accessible to undergraduate students.', ''), NULLIF('scopeatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Student Support Services Club (SSSC or SSS Club)', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('To encourage and foster social, recreational, and cultural growth and experiences in the spirit of diversity.', ''), NULLIF('triosssatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Student Involvement Leadership Consultants (SILCs)', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Student Involvement Leadership Consultants, or SILCs, are bright, motivated UC San Diego students committed to sharing our leadership and involvement experience to serve the UCSD community on whole. Our mission is to provide the University of California, San Diego student organizations with direct services to assist in their operations and to provide the campus-wide student population with consultation regarding student involvement and leadership opportunities.', ''), NULLIF('csifrontdesk@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sports Medicine Association at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('To advance the interests of students interested in a career in medicine or athletic training, to introduce topics of interest in sports medicine to build interest in the field among the UCSD community, and to create connections between faculty and undergraduates to foster potential research or advising in the future', ''), NULLIF('sportsmedatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Student Entrepreneurs Network', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The STUDENT ENTREPRENEURS NETWORK at UC San Diego (“The Network” or “SEN”) aims to cultivate an interdisciplinary community of students passionate about entrepreneurship and innovation. The Network shall be an inclusive and welcoming environment for any student to learn about entrepreneurship and innovation. This organization will serve as a resource to support students’ entrepreneurial interests, support existing entrepreneurial programs, serve as a talent platform, and generate new opportunities to advance students’ entrepreneurial interests. SEN seeks to empower its members to create a lasting impact by supporting an entrepreneurial mindset and the generation of new ventures for the benefit of the UC San Diego community and society.', ''), NULLIF('sen@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sprout Up @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('We teach children concepts in Environmental Science, Sustainability, and the unique ecosystems that surrounds them. During the earliest stages of their educational development, we encourage kids to think in new ways about the world around them through activities, experiments, and discussions, inspiring them to bring the message of environmental stewardship home to their families and friends. In this way, we cultivate the next generation of passionate caretakers of the Earth and promote sustainability from the youngest members of society up.', ''), NULLIF('directorsd@sproutup.org', ''), NULLIF('@sproutupatucsandiego', ''), NULLIF('', '')),
  ('Star Wars Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To provide a space for fans of the Star Wars franchise to gather, socialize, and bond over our shared love for the movies, TV shows, books, and other media that make up Star Wars. We host social events like watch parties, discussions, and more.', ''), NULLIF('starwarsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Students'''' Civil Liberties Union', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('To defend and advocate for the individual rights and liberties of students and to strengthen our systems of mutual cooperation.', ''), NULLIF('sclu.sd@proton.me', ''), NULLIF('', ''), NULLIF('', '')),
  ('Start Up Incubator Club', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To consolidate bright, innovative, and passionate minds from the UCSD student body to brainstorm start-up ideas and analyze successful business models. Our club is a safe haven for people passionate about entrepreneurship!', ''), NULLIF('startup.incubator.club@gmail.com', ''), NULLIF('startup.incubatorsd', ''), NULLIF('', '')),
  ('Student Veteran Organization', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Student Veteran Organization serves the Veteran and Military Affilated community. They are the Student arm for the Student Veteran Resource Center and work hand in hand on a joint mission of service to the community. The SVO is specifically positioned to serve our military personel and the broader community.', ''), NULLIF('tritonsvo@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Students for Altruism at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Students for Altruism (SFA) is an organization run by students which seeks to develop student potential through thoughtful and impact-driven actions aimed at societal and community well-being. The work of Students for Altruism is guided by the use of statistical evidence, transparency, reflection, and a strong work ethic geared towards empowering families, communities, and individuals in San Diego. Students for Altruism at UC San Diego also works towards socializing students so that they can become active, empowered citizens ready to transform their communities. This organization is open to students from all majors and levels!', ''), NULLIF('sfa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Students for Global Health', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Our purpose is to promote global health undergraduate student collaboration by striving to advance student’s knowledge, opportunities, and careers in the field. We uphold an interdisciplinary alliance with diverse majors, staff, faculty, and organizations around the globe. We also promote and educate members of our club and school on illness, health, and healing, through perspectives that transcend national borders and regional interests.', ''), NULLIF('yzurita@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Students for the Exploration and Development of Space', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('SEDS at UC San Diego is a multi-disciplinary group, motivated to advance the new space movement. Our goal is to make space exploration and rocketry accessible to all students. Guided by our passion and perspectives on the importance of space development, our organization pushes the boundaries on what is deemed possible. We have already made several waves in the aerospace field: we were the first student group to design and 3D-print a rocket engine (Tri-D) and the first undergraduate group to launch a rocket with a 3D-printed engine (Vulcan). SEDS at UC San Diego is focused on designing, building, testing, and executing projects to advance space technology.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Project in a Box', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Project in a Box (PiB) is a team of students passionate about creating. PiB’s goal is to foster a community of makers in order to empower students to invent and launch their careers. We pursue this vision by making projects accessible to students and promoting a hands-on approach to engineering education wherein students learn to place theory into practical, creative applications.', ''), NULLIF('pib@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Students Against Mass Incarceration', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('This student organization seeks to educate the campus about mass incarceration (the Prison Industrial Complex) as a form of institutionalized racism. To do so, the group will provide a space to cultivate a culture of undergraduate student activism against the injustice in the U.S. prison system and cooperate with faculty and graduate students to spread awareness primarily through screenings, speakers, panels, campaigns, and direct networking with key people working in this arena.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Students United for Research &Environmental Safety', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('SURE is dedicated to cultivating a proactive and inclusive culture of safety across research and teaching laboratories. Led primarily by graduate students with support from faculty, staff, and Environmental Health & Safety (EH&S), SURE engages the broader research community—including undergraduates, postdocs, staff and faculty—to: 1. Promote awareness, education, and dialogue around safe laboratory practices. 2. Host preparedness events and identify gaps in safety knowledge and resources. 3. Strengthen connections between academic labs, EH&S, and industry to align safety expectations. 4. Encourage sustainable research through waste reduction and responsible lab practices. Through leadership, collaboration, and advocacy, we aim to make every lab at UC San Diego a safer, more informed, and environmentally conscious place to research and discover.', ''), NULLIF('vlerda@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sun God Archery at UC San Diego', NULLIF('Martial Arts/Combatives/Weaponry', ''), NULLIF('Sports', ''), NULLIF('The purpose of SGA is to develop a community of athletes who learn and practice life and leadership skills through the sport of archery.', ''), NULLIF('info@sungodarchery.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Project RISHI', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Project RISHI at UC San Diego aims to promote sustainable development and growth of rural Indian communities. In partnership with local community members and social enterprises, we identify issues central to our target community and provide resources to implement solutions through extensive field research and on-campus initiatives. In our international efforts, we brainstorm new, innovative, creative ideas to tackle issues in our adopted village. What may be commonplace in America can not be handled the same way in a developing country. We are seeking devoted individuals who can think outside the box. Help us make a difference in the lives of underprivileged communities.', ''), NULLIF('rishi@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sun God Soccer', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To facilitate the organization and regulation of pickup soccer games on campus for students, staff, and anyone who wants to play a friendly game of soccer.', ''), NULLIF('SunGodSoccer@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Project Shifa', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('To empower Middle Eastern immigrants, marginalized communities, and refugees by bridging the gap in healthcare access and education.', ''), NULLIF('projectshifa.us@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Project Sunshine at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Project Sunshine is a nonprofit organization that provides free educational, recreational, and social programs to children and families living with medical challenges. We strive to bring smiles and deliver the healing power of play to children with medical needs through trained and dedicated volunteers.', ''), NULLIF('projectsunshineatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sunny Angels at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Sonny Angels are a world-wide phenomenon: cherub figurines that wear a variety of themed hats and accessories. The purpose of this student organization is to create and bring like-minded individuals together to celebrate and collect Sonny Angels.', ''), NULLIF('sunnyangels@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Project Venus', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('Our project''''s purpose is to empower any individual interested in the legal field by providing political experience as well as activism, while uplifting and promoting women''''s rights. We are dedicated to community service and inclusivity, welcoming members from all majors and backgrounds to engage in meaningful discussions and initiatives that drive positive change.', ''), NULLIF('projectvenussd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Sustainable Investment Group', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Sustainable Investment Group (SIG) at UC San Diego is a student-run organization focused on investments in companies that prioritize sustainability. By emphasizing responsible investing, SIG aims foster a commitment to ESG within the community and beyond. Additionally, the group prepares students for careers in the climate and financial sectors through guest speakers, networking opportunities, and hands-on experiences.', ''), NULLIF('sigatucsd@gmail.com', ''), NULLIF('@sigatucsd', ''), NULLIF('', '')),
  ('Psi Chi Omega', NULLIF('Multicultural Greek Council (MGC) - Fraternity', ''), NULLIF('Fraternity', ''), NULLIF('The purpose of UCSD Psi Chi Omega, an Asian-interest fraternity, is to promote excellence through integrity, perseverance, and eternal brotherhood, focusing on the Asian-American culture through activities that enhance scholarship, leadership, and service.', ''), NULLIF('sdpsichi.prez@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Symphonic Student Association', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('The Symphonic Student Association at UC San Diego (SSA) is a student-run organization committed to fostering a community for students and community members who share an interest in classical music. SSA also strives to make classical music more accessible in the community by presenting regular free concerts and workshops both on and off campus. SSA primarily rehearses its own chamber ensembles and presents yearly showcases at the Che Cafe. SSA selects music from various genres within classical music and aims to provide a great experience for both musicians and the audience regardless of prior exposure to classical music. SSA is also the primary social platform for the UCSD Chamber Orchestra and hosts social events open to the entire UCSD community. In addition, SSA regularly performs at various gigs, local senior homes, and children’s centers. We have ways for you to be involved with SSA whether or not you play an instrument or not! You can subscribe to our newsletter by entering your email on the homepage to stay tuned. We hope to see you around!', ''), NULLIF('symphoni@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Psi Chi/Psychology Club', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Psi Chi is the International Honors Society of Psychology whose mission is to provide students opportunities for leadership, scholarship, community service, and research. The UC San Diego chapter supports these opportunities by allowing students to form and join committees of interest as well as having a panel of officers who consistently present opportunities for professional growth. Being a registered member of the organization means a student has lifelong access psychology fellowships, scholarships, a career database, submission access to a peer-reviewed academic journal, and opportunities to present at the annual WPA and APA conferences. While Psi Chi has criteria for joining including a minimum GPA, amount of completed psychology courses, and a major or minor of psychology being a requirement, the UC San Diego chapter welcomes all students. Students who do not meet these minimum requirements (including new transfer students) are welcome to join the chapter by being Psychology Club members. At meetings both Psi Chi and Psychology Club members work together using Robert’s Rules of Order to vote on the direction of the chapter for the academic year. Students will be able to participate in experiences that can aid them in becoming stronger applicants for graduate school, attend workshops, view guest speakers, gain leadership skills, and help people in need within the San Diego community through service projects.', ''), NULLIF('psichi@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Syrian American Medical Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of the Syrian American Medical Society (SAMS) club at UC San Diego is to bring together students who are passionate about healthcare, humanitarian aid, and advocating for the well-being of people affected by the Syrian crisis. The club aims to raise awareness about the ongoing humanitarian needs in Syria and surrounding regions, provide opportunities for members to participate in fundraising and advocacy efforts, and support SAMS''''s mission to deliver medical relief to Syrian refugees and underserved communities. Additionally, the club fosters a community of students interested in global health, offering educational events, volunteer opportunities, and collaboration with other organizations to make a positive impact.', ''), NULLIF('samsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Surfrider Foundation @ UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Surfrider Foundation at Scripps is dedicated to the protection and enjoyment of our world’s ocean, waves, and beaches for all people, through a powerful activist network! Through Surfrider’s Student Club Network, we display our passion for these causes through active leadership in the community (both on-campus and off-campus) via environmental stewardship projects that encompass conservation, advocacy, and/or education.', ''), NULLIF('surfrideratucsd@clubs.surfrider.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Prospect - The Journal of International Affairs at UC San Diego', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('PROSPECT is an undergraduate journal of international/transnational affairs at the University of California, San Diego. Serving as a forum for intelligent discourse on international and transnational affairs, the journal showcases works by undergraduates who wish to broaden their understanding of contemporary and global issues while analyzing the world''''s most pressing challenges.', ''), NULLIF('prospectjournal@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Syrian Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('Our purpose is to unite students who are interested in the Syrian background for cultural support, inclusion, and to learn about Syria’s history as well as provide a safe space for students to express their cultural and personal identity. We want to celebrate, educate, and develop a sense of community relating to our culture.', ''), NULLIF('ssaatucsd22@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Taekwondo @ UC San Diego', NULLIF('Martial Arts/Combatives/Weaponry', ''), NULLIF('Sports', ''), NULLIF('The Taekwondo Club at UC San Diego is seeking to provide Olympic-style Taekwondo classes for students at UCSD. We will teach those who want to either practice recreationally or are looking to prepare to compete at local/national tournaments.', ''), NULLIF('ucsdtkd3@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Public Transit Enthusiasts at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To create a space where students can discuss and learn about the different public transit vehicles and public transit systems that run San Diego, the United States, and beyond. Spreading awareness of the countless places students can go just with their transit pass. Students will have the opportunity to join in events where we explore San Diego via public transit, as well as regular meetings where we share our knowledge and discuss anything in the world of public transit.', ''), NULLIF('pte@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Puente Project at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('To support and establish a community that Puente students and others feel connected through leadership, community service opportunities, and workshops. To provide support to celebrate and bring awareness to minority cultures first generation students. To establish an opportunity to raise funds for the club. To support current university students in tasks such as FAFSA, etc. To provide a relationship with high schools to give tours and panels at UC San Diego and to give mentorship opportunities.', ''), NULLIF('PuenteAtUCSD@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Public Health Graduate Organization @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('PH-GO is a health profession organization that seeks to engage UC San Diego graduate students with the common goal of learning, promoting, and addressing public health issues.', ''), NULLIF('publichealthgo@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('PULSE at UC San Diego', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The purpose of PULSE at UC San Diego is to create a community for students pursuing careers in healthcare. Our mission is inclusive of all aspiring physicians who seek connection, mentorship, and access to meaningful resources along the prehealthcare path. Our goal is to address the sense of isolation many students face while preparing for medical, dental, optometry, or pharmacy school. We will facilitate collaborative MCAT, DAT, and other standardized test study spaces, student-led groups, and access to learning tools shared by members of our community. Through events and panels, we also plan to invite physicians, grad students, and healthcare professionals to speak about their experiences, offering valuable insight into clinical exposure, research opportunities, and the application process as a whole. We believe that financial barriers should never stand in the way of a student''''s ability to pursue a career in healthcare. That is why we plan to actively raise funds to support scholarship programs and charitable initiatives aimed at increasing access to education. PULSE is committed to walking alongside students aspiring to the healthcare track, fostering a collaborative, informed, and inclusive community of future physicians, and helping eliminate the feeling of loneliness on this long journey. PULSE: Prehealth, Unity, Leadership, Support, Empowerment', ''), NULLIF('pulseatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('PULSE MedTech Undergraduate Journal @ UC San Diego', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('PULSE MedTech Undergraduate Journal @ UC San Diego seeks to keep the community engaged with the MedTech research being conducted on campus. We are committed to making this work accessible to a broad audience, including those without a STEM background. For our writers, the journal provides both a platform to share their perspectives in the field and a valuable professional opportunity: a publication they can highlight on resumes, CVs, and graduate school applications.', ''), NULLIF('PULSEMedTechAtUCSD@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Qamar Society at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Qamar Society at UC San Diego is committed to uplifting, educating, and building sisterhood among Muslim women and allies on campus. We aim to highlight women''''s historical, spiritual, intellectual, and societal contributions in Islam and to provide space for exploration, dialogue, healing, and growth.', ''), NULLIF('qamarsocietyatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Pushpanjali', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('To promote, explore, and showcase classical Indian styles like Bharatanatyam, Kuchipudi, Kathak, and many more in a way that can reach out to all cultures and people.', ''), NULLIF('pushpanjaliatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Queer and Trans* People of Color (QT*POC) at UC San Diego', NULLIF('Student Affirmative Actions Committee (SAAC)', ''), NULLIF('Cultural', ''), NULLIF('Queer and Trans* People of Color (QT*POC) at UC San Diego was established in 2000 by a group of Queer students of Color FED UP with racism in the queer community, and with homophobia and transphobia within cultural organizations. With this, at the core of QT*POC are our commitments to struggle and our commitments to activism. We recognize the intersections of our multiple, beautiful, and sometimes confusing identities, as well as the related intersections of social justice movements. We create a SPACE--a social, political, academic, and cultural environment--to enhance our members'''' entire self-being and holistic wellness.', ''), NULLIF('qtpocatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Quantum Computing at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Quantum Computing at UC San Diego (QCSD) is intended as a learning environment where students that are curious about quantum computing can meet to discuss ideas, find resources, and be connected to peers and faculty they can learn from through workshops designed to help the very curious beginner to learn the basics of quantum computing and competing in various quantum computing hackathons.', ''), NULLIF('qc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Queer@Scripps', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of this group is to connect queer-identifying students, staff, postdocs, researchers, faculty, and alumni at Scripps Institution of Oceanography (SIO) to share resources and be in community with each other. To do this, we host monthly informal meet-ups and events throughout the year.', ''), NULLIF('leadership-queer-sio@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Quiz Bowl Club at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To promote and participate in quiz bowl competitions throughout the United States.', ''), NULLIF('quizbowlatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Public Health Undergraduate Organization at UC San Diego', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The overarching goal of the Public Health Undergraduate Organization is to bring students, staff and faculty with an interest in public health, healthy lifestyles, or community health together. The Public Health Undergraduate Organization will serve as an umbrella organization wherein members will be able to specialize in a particular field of interest. The Public Health Undergraduate Organization will help members by providing information and opportunities for volunteerism and internships.', ''), NULLIF('phuoatucsd@gmail.com', ''), NULLIF('phuoatucsd', ''), NULLIF('', '')),
  ('Raas Ruckus Dance Team at UC San Diego', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('The competitive Garba and Raas team at UCSD is a non-profit, recreational club with a cultural twist. This group promotes Garba and Raas, two interrelated West-Indian dance forms that originated from the state of Gujarat. In this day and age, Garba & Raas have been transformed from the deeply traditional precursors to the more energetic, contemporary form that is practiced by this team. In addition to simply developing and performing modern Garba/Raas choreography on campus, this team intends to partake in national, collegiate Garba/Raas competitions, thereby representing the University of California, San Diego and promoting school pride. At the local level, this seems also seeks to promote cultural and social awareness of this dance form and the related cultural connotation by performing on campus, and at nearby universities, as well as by eliciting participation from the student body. An implicit goal of this organization is to build a community at UC San Diego for all students who dance for the team and wish to be involved.', ''), NULLIF('raas.ruckus@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Reach @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('What started as a way to build community amongst a growing social media industry in a college setting has quickly grown to be much more. Reach is the first and only social media club at UCSD. However, we''''re more than just social media. At Reach, we aim to create a community for content creators, digital marketers, influencers, actors, and anyone interested in entertainment and social media. During the quarters, we feature creator workshops, brand collaborations, influencer content days, UCSD student socials, industry professional and creative pioneer guest speakers, and more. In the past, REACH has had guests from Google, TikTok, WarnerMedia, Paramount, and Fullscreen. The landscape of entertainment, digital marketing, and social media is ever changing; with new platforms, trends, and algorithms being created everyday, we want to ensure club members are ahead of the curve. Industry workshops and creative content creation peer-to-peer classes will give insight on how to build a following, create viral content, and manage a brand''''s page. Learn hands on and connect in an intimate setting with those who have climbed the ladder. We understand that collaboration is key to a successful career, whether you''''re a content creator or someone just interested in media and entertainment. As a family, we strive to encourage members to share their projects with each other. Many club meetings involve brand collaborations, photoshoots, socials, club dinners, retreats, and other bonding events.', ''), NULLIF('reachatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Red Cross @UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The Red Cross @UC San Diego Club strives to make a positive impact by supporting the American Red Cross mission to assist the needy and distressed. We bring students together to serve these populations through projects like blood drives, fundraising, and global humanitarian initiatives. By volunteering and supporting the larger community, we aim to spread compassion, teamwork, and a spirit of service across the UC San Diego campus and beyond.', ''), NULLIF('redcrossatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Taiwanese American Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Taiwanese American Student Association (TASA) at the University of California, San Diego is an organization that provides a community for Taiwanese Americans and those interested in Taiwanese culture. The organization creates a culture of unity within San Diego and extends across universities. We promote cultural awareness by building a community of motivated, dedicated, and curious students through our social and cultural activities that take place throughout the year. The Taiwanese-American identity is one that is very diverse and at times, divisive. Despite this, individuals ranging from those who barely identify themselves as Taiwanese, to those who feel passionately about Taiwanese culture, are all still unified under a common background. Thus, those with the Taiwanese-American identity have the potential to develop into a tight-knit community as strong leaders with a unified voice in this nation and college community.', ''), NULLIF('tasa.atucsd1@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('TamashaSD', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('TamashaSD is a student run organization on the UC San Diego campus that aims to connect South Asian Americans back to their roots while fostering a positive cultural environment for the community. We host a Raas-Garba and a Bollywood-Fusion competition, which teams from across the country participate in.', ''), NULLIF('tamashasd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('TAMID at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('TAMID at UC San Diego is a pre-professional organization that provides students with real-life business experience. We conduct pro-bono consulting projects with Israeli start-ups, hold investment research competitions, and provide opportunities for networking and internships. Our chapter is part of a multinational organization that connects students all around the world to educate them through experiential learning and prepare them for careers in various fields.', ''), NULLIF('TAMIDatUCSD@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tau Beta Pi', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Tau Beta Pi is the premier engineering honor society in the United States and one of the top three honor societies in the nation. The Society focuses on serving its members and the public with enthusiasm and excellence. The Association also strives to promote excellence in the fields of engineering, thus helping to improve the perception of the profession.', ''), NULLIF('tbp@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Rack N’ Roll (The Pocket Billiards Club @ UC San Diego)', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The goal of Rack N’ Roll (The Pocket Billiards Club @ UC San Diego) is to build and support the pool and billiards community at UC San Diego. We aim to promote the learning and adoration of the niche field of cue sports with tools and resources to help members learn about the game. Organization members will get enriching experiences involving Pocket Billiards. Members will also gain the opportunity to learn how to better play Pocket Billiards games, and be exposed to the more professional edge of the sport.', ''), NULLIF('sghodke@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tau Sigma', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Tau Sigma is a national academic honors society designed to acknowledge the academic achievements and university involvements of transfer students. With an aim to serve current and future transfer students, our intention this year is to provide community among transfer students and support resources that propagate success.', ''), NULLIF('tausigma@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Real Food Challenge at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our movement seeks to redirect university spending on food and beverage on campus toward local, ethical, and sustainable sources, particularly uplifting BIPOC producers and growers. RFC uses an intersectional approach, prioritizing “real food,” or food that incorporates our 5 values: local and community-based economies, environmental sustainability, valued workforce, animal welfare, and community health & nutrition. Through our campus organization, we aim to increase collaboration between students, faculty and producers regarding food systems on campus in an effort to educate, build community, and enact change on our campuses.', ''), NULLIF('squad6@rfchallenge.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('TEDx@UCSanDiego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('TEDxUCSanDiego''''s mission is to bring together a diverse set of leaders, thinkers, and doers to share ideas that come from their varied disciplines. Through a local forum, we hope to inspire people to change their lives, their futures, and ultimately, their world. We aim to engage, motivate, and celebrate all generations of the UCSD family.', ''), NULLIF('tedx@ucsd.edu', ''), NULLIF('tedxucsandiego', ''), NULLIF('', '')),
  ('Triton Software Engineering', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Triton Software Engineering (TSE) is an interdisciplinary student-run organization at UC San Diego that designs and develops pro-bono software (e.g. web and mobile applications) for non-profits, while giving our students practical, real world experience.', ''), NULLIF('tse@ucsd.edu', ''), NULLIF('@tse.atucsd', ''), NULLIF('', '')),
  ('Teo-Chew Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The Teo-Chew Association is a nonprofit student-run organization committed to the rich history and culture of the Teo-Chew American community and serving college-age youth. The following goals compose the Teo-Chew Association’s mission statement and purpose: • To increase awareness about Teo-Chew culture and language • To unite the Teo-Chew community on campus and beyond • To advocate for the preservation of Teo-Chew and Chinese culture and history for the general welfare of the Teo-Chew community', ''), NULLIF('tca@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Thai Student Union', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('As a cultural organization, the Thai Student Union (hereinafter “TSU”) strives to strengthen the bond of the Thai community in San Diego while sharing the Thai culture with those outside of the Thai community.', ''), NULLIF('tsuatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Solar Car', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('To create a solar car and race at competitions against other universities.', ''), NULLIF('tritonsolarcar@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('The Reclamation Project at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Empowering historically marginalized and underserved communities and youth to battle systems of oppression, trauma, violence, and poverty by centering youth leadership and delivering programming including conferences, summits, forums, workshops, campaigns, and grassroots projects. Key strategies of empowering youth include political/civic education and organization, youth leadership and mentorship, coalition building, mutual aid, community wellness, narrative change and research, and youth movement building. Past and ongoing projects include “Supplies for Solidarity” providing underserved families with access to necessary school supplies, “Abolition & Me: Stonewall’s Legacy” highlighting issues of prison labor and abuse in the criminal justice system, and the “Stand Up & Speak Out” bringing together underserved youth in California to contribute to youth-serving ethnographic research and hear from an immersive panel of activists, scholars, and movement leaders. New projects include “activation events,” which are community-based pop-up style social events that activate community members to engage in social justice and connect with peers.', ''), NULLIF('trp.empowers@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Robotics', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Promote the practice and field of robotics in the community by providing the opportunity to enter robotics competitions, take part in workshops as well as join a supportive community. Currently, our main goal is to compete in the international RoboMaster Competition organized by DJI.', ''), NULLIF('tritonrobotics@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Spike', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of Triton Spike is to foster a community around the sport of roundnet (colloquially known as spikeball), and to engage and educate the student body on the rules and competitive scene of roundnet!', ''), NULLIF('tritonspikeatucsd@gmail.com', ''), NULLIF('tritonspike.at.ucsd', ''), NULLIF('', '')),
  ('Triton Smash', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Smash is a student organization with the purpose of bringing together players, spectators, and enthusiasts of Super Smash Bros Ultimate for the Nintendo Switch. The goal is to create a friendly community of students that share the same passion for the game while also promoting the competitive scene. The focus will be primarily on socializing with other players on campus and bringing the best gaming experience possible to students.', ''), NULLIF('o5garcia@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Themed Entertainment Association @ UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Officially affiliated with the international Themed Entertainment Association, TEA at UC San Diego is a club for aspiring theme park designers, engineers, and creators. Providing experience with industry-based, hands-on projects and events that can’t be found anywhere else at UCSD, members graduate prepared to work in the top businesses that create the magical and adventurous experiences we all remember, cherish, and love.', ''), NULLIF('tea@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Splatoon', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Splatoon is a student organization with the purpose of bringing together players, spectators, and enthusiasts of Nintendo’s Splatoon series (primarily Splatoon 2 and Splatoon 3). The goal is to create a friendly community of students that share the same passion for the game while also promoting the competitive shooter scene. The focus will be primarily on socializing with other players on campus and bringing the best gaming experience possible to students.', ''), NULLIF('tritonsplatoon@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Swing Dance', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('The purpose of the organization shall be to promote and celebrate the art of African American Vernacular dance originating from the 1920s and 1930s (colloquially referred to as “swing dance”). The organization aims to educate students about the dance itself, as well as the history and cultural significance of Lindy Hop and other swing dances while fostering an inclusive and welcoming space for all individuals.', ''), NULLIF('tritonswingmedia@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Theta Tau at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of Theta Tau is to build a strong fraternal bond and maintain high standards of professionalism among fellow members. We are a pre-professional engineering organization established for the development of the brothers of the fraternity. Theta Tau aims to provide its members the social and professional development necessary to succeed during and after their college years.', ''), NULLIF('thetatauatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Tails - Furries at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The furry fandom is a subculture interested in anthropomorphic animals. Its origins date back to at least the 1980s in science fiction and comic conventions. Due to the diversity within the fandom, as well as fictional portrayals of the fandom based heavily on stereotypes, a certain amount of stigma and controversy is unfortunately associated with the fandom. Triton Tails hopes to serve and portray the furry population on campus positively, as well as foster community collaboration between furries at UC San Diego with other interest-based or academic groups.', ''), NULLIF('tritontails@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Thomistic Institute at UC San Diego, The', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('Our goal as The Thomistic Institute at UC San Diego is to promote academic discussion of the Catholic church’s intellectual tradition, placing particular emphasis on the thought of the 13th-century philosopher and theologian, Thomas Aquinas.', ''), NULLIF('thomisticinstitute@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tijuana Youth Migrant Mentor Network (TYMMN)', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Our organization is dedicated to empowering the youth residing at Casa YMCA de Menores Migrantes by fostering a culture of compassion and support. Our primary objective is to provide comprehensive mentorship programs through our dedicated team of volunteers. In collaboration with the Center on Global Justice staff, we aim to proactively address emerging challenges faced by the residents of the shelter. At the core of our mission is the commitment to creating a safe and inclusive environment for immigrant, first-generation, and Latinx students on our campus. We achieve this through our weekly General Body Meetings, fostering meaningful bonds among our members, and organizing networking events that celebrate diversity and promote cultural understanding. Furthermore, we are deeply committed to nurturing leadership and professional development among our members. Our organization offers a myriad of opportunities for personal growth and skill development. Whether working directly with migrant youth or contributing to the overall success of our team, every member has the chance to make a meaningful impact. By joining our organization, members not only extend their support to migrant youth but also gain invaluable experience in community action and leadership. Together, we strive to uplift and empower the next generation, transcending borders and building a brighter future for all.', ''), NULLIF('tymmn@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Tidepooling', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Triton Tidepooling meets biweekly at local tide pools to explore and document their unique habitats and wildlife. Through Triton Tidepooling, students not only connect with nature, but also connect with each other through a shared appreciation for California''''s coastal beauty.', ''), NULLIF('tritontidepooling@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Trading Group', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('This professional student organization helps students build investing experience, financial knowledge, and trading skills using Artificial Intelligence (AI). Members gain practical opportunities to apply AI tools to real financial markets, making research faster, investment strategies more accurate, and decisions more data-driven. By connecting classroom learning with real-world applications, the organization prepares students for careers in finance through the integration of AI, while also equipping them to invest wisely and make smarter financial decisions to manage their money effectively, regardless of the professions they pursue.', ''), NULLIF('ttgatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tikkun Olam Makers AT UC San Diegio', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Tikkun Olam Makers - is a global movement of communities that creates and disseminates affordable solutions to neglected challenges of people living with disabilities, the elderly and the poor. At UC San Diego, we will focus on engineering solutions for those in need, and will participate in various community efforts throughout San Diego county.', ''), NULLIF('sdtikkunolammakers@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tokens', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('Tokens is a creative club dedicated to producing a unique interactive magazine that celebrates the charm of lived experiences. Through our magazine, we capture life’s rich moments by weaving together personal histories, reflections, and memories across all art forms, from photography and other traditional art forms to creative writing, editorial design, and fashion. Our magazine is a collaborative project where each member brings their unique perspective, creating something both heartfelt and timeless. We welcome anyone who wants to explore the art of storytelling and share the beauty in life’s little details!', ''), NULLIF('tokensatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Ball', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Triton Ball is committed to extending classroom knowledge into the field of sports analytics by providing students with hands-on opportunities to work with and analyze data from intercollegiate sports teams. We aim to bridge the gap between academic learning and practical application while offering workshops to help students acquire the technical skills essential for success in sports analytics. The organization will host guest speakers and industry professionals who will share their expertise and provide insights into the field of analytics and data science within the sports industry. Additionally, Triton Ball will offer networking events that allow students to connect with industry professionals and fellow students who share a passion for sports analytics, fostering collaboration and career development.', ''), NULLIF('tritonball@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Tutors', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Triton Tutors is an initiative dedicated to reducing educational disparities and empowering K-12 students in underserved communities across San Diego. We aim to provide free, flexible tutoring services through both virtual and in-person sessions, with a focus on developing long-term mentorships that foster academic mastery and critical thinking skills. By connecting UC San Diego volunteer tutors with local students, our goal is to create a supportive learning environment that prepares students for future academic and career success, thus contributing to a more equitable educational landscape in San Diego. Interested tutors can fill out the following form, and we will quickly reach out to you via the email you provide to discuss onboarding: https://docs.google.com/forms/d/e/1FAIpQLSfuiVu83qY3EcGEnkCNikGNMCoHGmCmHco_6RtGe4gHSWx0jQ/viewform?usp=sf_link', ''), NULLIF('tritontutors@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Unmanned Aerial Systems', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('We are a student-run team that designs, builds, tests, and flies our own UAV to compete each year in the Student UAS Competition hosted by the AUVSI Seafarer Chapter against over 70 teams from around the world. The team is multi-disciplinary consisting of four subteams. The airframe team designs, analyzes, and builds a reliable composite flight platform to house and transport a variety of avionics packages. The embedded team designs the payload and electronics. The software team programs the ability to complete mission tasks such as autonomously recognizing targets and dynamic path planning. The business team assists with raising funds, as well as forming and growing corporate, campus, and public relations.', ''), NULLIF('tuas@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Barbell', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Barbell is a powerlifting and weightlifting oriented community that aims to promote knowledge and competition in strength sports. Our goal is to create a friendly, welcoming environment in which everyone, regardless of personal goals or experience level, can pursue self-empowerment through lifting.', ''), NULLIF('tritonbarbell@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Trader Joe''''s Club @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of this student organization is to promote healthier alternatives to grocery shopping through grocery runs at Trader Joe''''s, fostering more awareness about food labels and nutritional needs. Additionally, this club will create a welcoming and friendly community for those who enjoy Trader Joe''''s products and host community events such as Trivia Nights, give-aways, and donations to the Food Co-op with raised funds.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Brain Injury Network', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of Triton Brain Injury Network is to provide support to brain injury survivors through recreational activities and are dedicated to creating a space for our students to engage with disability advocacy, education, and awareness.', ''), NULLIF('tbin@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton XR', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Triton XR is an organization that connects students with the VR industry through networking, workshops, and projects. Our mission is to foster a multidisciplinary community dedicated to exploring and creating Virtual, Augmented, and Mixed Reality experiences.', ''), NULLIF('admin@tritonxr.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Transfers in Science', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The goal of Transfers in Science (TiS) is to provide transfer students with academic, professional, and social support through different workshops, social activities, and volunteering. Transfer students face a different set of challenges so TiS is here to promote their achievements by providing the necessary resources for maximizing their success as well as offering a community of support, encouragement, and guidance. In addition, the goal is to help STEM transfers find their way through obtaining research and internship experiences, letters of recommendation, finding mentors, boosting resumes, grad/med school prep, and so much more!', ''), NULLIF('tis.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton-Ai', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Learning machine learning through competing in autonomous robotic vehicle races.', ''), NULLIF('triton-ai@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Trebles, The', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('The purpose of this ensemble is to find joy through singing together. We sing for ourselves and perform to share our love of music with others. We will explore a wide variety of musical styles and genres, including jazz, classical, and popular music.', ''), NULLIF('treblesatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Business Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Triton Business Society is a professional organization aiming to foster the study of business in universities; to encourage scholarship, social activity and the association of students for their mutual advancement by research and practice; to promote closer affiliation between the commercial world and students of commerce, and to further a higher standard of commercial ethics and culture and the civic and commercial welfare of the community.', ''), NULLIF('tritonbusinesssociety@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Consulting Group', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To create business leaders in the UCSD community by engaging students in the consulting sector, by providing them with real-life applications and professional development.', ''), NULLIF('board.tcg@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('TREND', NULLIF('Media', ''), NULLIF('Social', ''), NULLIF('TREND is a non-profit student organization that publishes a fashion magazine. It highlights the fashion of individuals and connects UCSD students to social events in the local San Diego community. The publication offers student opportunities to learn and gain experience in the media industry by being a stylist, photographer, designer, coordinator, and more.', ''), NULLIF('trend@uscd.edu', ''), NULLIF('trendatuscd', ''), NULLIF('', '')),
  ('Tritones at UC San Diego', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Founded in 1996, the Tritones are UC San Diego’s premiere vocal ensemble. United by a passion for singing and music, the Tritones seek to foster a nurturing environment for all undergraduates looking to pursue a cappella during their college career. They strive to promote a cappella music throughout the UC San Diego community and greater San Diego area through performance and volunteering.', ''), NULLIF('tritones@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tritonettes @ UC San Diego', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('To serve the African American and minority communities by introducing a Historically Black College-inspired dance form, founded by African American women. This initiative is designed to promote cultural pride, empower women through dance, and create a supportive, inclusive space for minority women at UC San Diego. By honoring heritage and fostering unity, we aim to build a stronger sense of community and belonging on campus.', ''), NULLIF('tritonettes24@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Democrats', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('The purpose of the College Democrats, a non-profit organization, is to educate students about the philosophy of the Democratic Party, promote campus discussion of issues of concern to students and the nation at large, foster involvement in political movements, and affect political change on a local, state, and national level', ''), NULLIF('tritondemocrats@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triangle', NULLIF('Interfraternity Council (IFC)', ''), NULLIF('Fraternity', ''), NULLIF('To promote the growth of brotherhood amongst our members, while promoting and upholding the Triangle Code of Ethics.', ''), NULLIF('triangleatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Trinket Box', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Trinket Box, or Trinkets, is a welcoming space for anyone who loves collecting - from tiny buttons and keychains to cards, blind boxes, and favorite characters. Whether you''''ve been collecting for years or just love seeing what others treasure, Trinkets is all about sharing the joy behind the things we love. More than just a club, Trinket Box is a cozy, judgement-free hangout where you can unwind, connect with fellow collectors, and explore the stories behind all kinds of unique finds. It''''s a space to appreciate the little things that make us smile and remind us why collecting is so special.', ''), NULLIF('trinketsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Divers Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Divers Club aims to build a welcoming and active community for scuba divers, freedivers, and snorkelers at UC San Diego. Our mission is to connect students who share a passion for the ocean, provide opportunities to meet dive partners, and create a platform for organizing group dives and ocean-related adventures. With the potential for bulk certification classes. We host social events such as bonfires and group lobster dives, as well as educational opportunities including citizen science workshops, safety checks, and gear maintenance sessions. By fostering both community and ocean stewardship, we strive to make diving more accessible, safe, and enriching for all members.', ''), NULLIF('tritondiversclub@gmail.com', ''), NULLIF('Tritondiversclub', ''), NULLIF('', '')),
  ('Tritons for HHT Awareness at UC San Diego', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Tritons for HHT Awareness at UC San Diego is a student organization committed to raising awareness of Hereditary Hemorrhagic Telangiectasia (HHT), a rare and underdiagnosed genetic vascular disorder. Our mission is to educate students, future healthcare providers, and the broader community about the clinical features, diagnostic challenges, and treatment considerations surrounding HHT. As the only student-led HHT organization in the UC system, we strive to bridge the gap between genetics, public health, and patient-centered care, highlighting how early awareness can change outcomes.', ''), NULLIF('tritons4hhtawareness.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tritons Adoptee Collective', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('This club serves as a safe space for the adoptee community as well as anyone interested in learning about the community. I want this club to help build connections and foster new friendships among the adoptee community through volunteering and raising money for those in foster care and other communities in need.', ''), NULLIF('tritonsadopteecollective@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Droids', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Triton Droids is a student-led organization focused on developing the first affordable, autonomous humanoid robot that can eventually help eliminate global poverty. Access to capital, technology, and cheap labor causes epic disparities in production efficiencies across regions of the world. This is the reason why a farmer in Australia earns 20 times more than a farmer in India or Africa with the same amount of land or why many American companies outsource production. By leveraging collaboration with UCSD faculty, UCSD’s unique engineering labs,industry partnerships, and the interdisciplinary innovative spirit of our student body, we aim to make cutting-edge humanoid technology accessible to all. Our mission is to create a world of abundance and drive equitable economic growth through innovation, while providing our members with unparalleled hands-on experience and opportunities to shape the future of robotics and global development.', ''), NULLIF('tritondroids@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton A Cappella Community', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('The purpose of tACC is to foster community and camaraderie amongst the various a cappella groups at UC San Diego while facilitating special events which promote a cappella such as auditions, concerts, fundraisers, and music workshops.', ''), NULLIF('tacc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tritons For Israel', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Tritons For Israel is the pro-Israel student organization at UC San Diego. We are dedicated to raising awareness about Israel and celebrating Israeli culture, educating students and encouraging dialogue, as well as promoting peace in the Middle East.', ''), NULLIF('tritons.israel@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Actuarial Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Triton Actuarial Society provides undergraduate students with resources and support to explore careers in actuarial science. Actuaries play a key role in managing insurance and risk analysis, which significantly impact our daily lives. Through workshops, professional development events, and information sessions, we help students prepare for actuarial exams and build successful careers.', ''), NULLIF('tas@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Engineering Student Council', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('TESC wants to develop engineers who exhibit leadership through excellence in all aspects of life: - Prepare students for, and connect them with, professional opportunities; - Coordinate, and collaborate with, engineering student organizations; - Create and maintain a vibrant community for engineering students; and - Champion engineering and engineers in the school, community, and beyond.', ''), NULLIF('tesc@tesc.ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Auto Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('As a car club at the University of California, San Diego, Triton Auto Club aims to build a community for car enthusiasts to gather and share their collective knowledge about automobiles and motor sports. Our goals include teaching members about various aspects of automotive knowledge while constructing a network to develop strong connections in the automotive industry. We also strive to create a safe environment where we can test and improve the performance of our cars as well as our driving skills. Highly discouraging street racing, Triton Auto Club gives members the opportunity to go to the race track to satisfy their high performance driving needs. Using all of these resources and connections, members of Triton Auto Club can become strong leaders who are extremely knowledgeable in the automotive field and enthusiastic about everything they do. Even the slightest passion for cars will not be overlooked and is all that one must posses to become a proud and capable member of Triton Auto Club.', ''), NULLIF('tritonautoclub@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tritons Roll Out', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Tritons Roll Out is a student-led roller skating organization dedicated to building community, promoting wellness, and encouraging self-expression through skating. Our purpose is to create a fun, inclusive space where students of all skill levels can connect, learn, and enjoy the art and sport of roller skating both on and off campus.', ''), NULLIF('tritonsrollout@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Fighters', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Fighters seeks to offer a place where fans of fighting games of any kind can meet up to play and form a community. We host weekly meetups at which students can bring setups for their favorite games to play with others, allowing them to meet new people that share common interests.', ''), NULLIF('fighters@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('TritonThenix', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('TritonThenix allows students to achieve a deeper understanding and ability in the art of calisthenics. TritonThenix supports students in developing confidence through consistent training and community involvement. All experience levels are welcome in the organization.', ''), NULLIF('tritonthenix@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Baja', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Our mission at Triton Baja is to provide a challenging platform for students to apply their theoretical knowledge in designing, building, and racing an off-road vehicle. We aim to foster innovation, collaboration, and excellence in engineering while promoting hands-on experience and professional development.', ''), NULLIF('baja@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Film Society', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of the club is to provide an environment where University of California San Diego students can discuss and watch films with their peers. We are an inclusive club, and any students are welcome to follow our social media and attend any events we host.', ''), NULLIF('tritonfilm.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Foodie', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Foodie is a cooking community aimed at beginners and advanced cooks alike. We will make members more confident in the kitchen through assisted cooking sessions, and keep advanced Foodies engaged with new recipe suggestions. We hope to bring Foodies together to form a supportive and friendly community.', ''), NULLIF('tritonfoodie@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Turning Point USA at UC San Diego', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('Turning Point USA''''s purpose is to promote American values and free market capitalism while sparking civil and productive discourse amongst participants who may disagree with one another.', ''), NULLIF('tpusaatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Tzu Chi Collegiate Association at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Tzu Chi Collegiate Association at UC San Diego is a non-profit student organization, which aims to inspire college-level students in the mindful practice of the Tzu Chi Foundation’s principles of Gratitude, Respect, and Love through service at the local community level. Tzu Ching promote the universal value of “Great Love” through the Tzu Chi Foundation’s missions of Charity, Medicine, Education, Culture, International Relief, Bone Marrow Donation, Environmental Protection and Community Service. Through mindful practice of Founder Dharma Master Cheng Yen’s teachings, Tzu Ching hope to purify people''''s minds and bring positive influence into the community.', ''), NULLIF('tcatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Investment Banking', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of Triton Investment Banking is to empower students to explore and pursue careers in investment banking and related fields through practical training, hands-on deal experience, and professional preparation. The organization aims to bridge the gap between classroom learning and the professional investment banking environment by simulating real-world workflows of investment banks. Members will develop technical and soft skills essential to the field, including valuation, financial modeling, due diligence, client communication, and transaction execution. Through structured training programs, networking opportunities, and live or simulated deal projects, members will gain the knowledge, confidence, and experience to compete for internships and full-time roles in finance, consulting, and corporate strategy. Ultimately, the Triton Investment Banking strives to cultivate a culture of professionalism, excellence, and teamwork—preparing its members to become ethical, capable, and impactful future leaders in the financial industry.', ''), NULLIF('ibclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton League and TFT at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Our club seeks to provide both a recreational, social, and competitive community for players of the game League of Legends within UCSD and the greater San Diego area. By providing an environment of social interaction, friendly competition, and in-game support, we seek to give all of our members a positive gaming experience and the competitive drive to succeed in any gaming or non-gaming endeavor.', ''), NULLIF('leagueoftritons@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Undergraduate Bioinformatics Club (UBIC)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('UBIC is a non-profit organization whose purpose is to serve Undergraduates interested in Bioinformatics by providing resources for students entering the growing discipline; furthering access to job, internship, and research opportunities; facilitating an open forum for discussion, collaboration, and socialization; holding 2-3 events per week; and acting as a collective voice for bioinformatics students at UCSD.', ''), NULLIF('ubic@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Mario Kart', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Mario Kart is a community based around the game Mario Kart. We will have events such as tournaments, meetups, etc. The club for competitive and casual Mario Kart on campus. We primarily play Mario Kart 8 Deluxe (Switch).', ''), NULLIF('mariokart@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('TRUTH Club', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('The TRUTH Club (Taking Real Understanding to Heart) focuses on learning the Bible and putting into practice the commands of God, rather than following man-made traditions.', ''), NULLIF('truthclub.sd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Melee', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Our mission is to provide a safe and engaging environment for everyone at UCSD who wishes to enjoy the amazing game that is Super Smash Bros. Melee. We plan on running events on campus so that we can create an engaging and compassionate environment for our UCSD Melee players.', ''), NULLIF('rbelista@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Minecraft', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Minecraft is a worldly renowned sand box game. You can unleash your creativity in building or sparkle your competitive side in fighting. The club serves to gather all UC San Diego Minecraft players together and organize Minecraft related events and tournaments, offering an exciting, diverse, and all-inclusive gaming environment for every player to relax and play.', ''), NULLIF('tritonminecraftorg@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Gaming', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Gaming is a group of collegiate organizers that team up to create epic entertainment experiences for student gamers at the University of California, San Diego. Our organization is the product of several independent on-campus gaming organizations that each represent a different gaming genre and student community. Through Triton Gaming, our team strives to create an exciting, diverse, and all-inclusive gaming environment on campus through high-quality live events.', ''), NULLIF('tritongamingofficial@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Photography Club', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Making photography accessible to all students at UCSD. Join us for events like guest speakers, photography workshops, gallery exhibitions, photo walks, school break trips, and professional opportunities. Our club consists of 7 communities ranging from landscape to fashion.', ''), NULLIF('tritonphotoclub@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Pokémon League', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('We aim to provide a hub for students at UCSD to participate in different aspects of Pokemon, from Pokemon Go, Competitive VGC, TCG or casual fun. We are the one stop shop for all things Pokemon related at UCSD!', ''), NULLIF('tritonpokemonleague@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Prosthetics Society (TPS)', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Our purpose is to bring together like-minded students interested in the field of prosthetics and tackle challenges present with current prosthetics.', ''), NULLIF('tps@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Quantitative Trading', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The primary goals of our student organization are to establish a collaborative ecosystem that fosters the joint creation of algorithmic, statistical, and trading models by students, while also ensuring they have access to comprehensive resources for continuous learning. We strive to facilitate interactions with industry experts, providing valuable insights and to connect students with the industry for practical experiences and mentorship from esteemed professors. TQT actively participates in trading competitions held nationally.', ''), NULLIF('tquantt@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Restoration Initiative (TRI)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Inspired by our primary project renovating the clock in front of Jacobs Hall, TRI is a student organization that strives for innovation through engineering design. TRI encourages its members to share improvement and restoration ideas to standing structures or new ideas with the opportunity to enact them. No matter how small or big the idea is, our purpose is to nurture creativity and teamwork in the engineering community and beyond for design and problem-solving.', ''), NULLIF('triclubatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Rivals', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Triton Rivals is a community for players of all skill levels across UC San Diego and the greater San Diego area for the game Marvel Rivals. Our goal is to bring players together to create a friendly environment where people can interact socially through matches and tournaments.', ''), NULLIF('tritonrivals@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Undergraduate Communication Society', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('The Undergraduate Communication Society (UCS) provides Communication majors and related fields with opportunities to build connections, develop skills, and explore career paths. By working closely with faculty, UCS helps students learn more about the major, gain professional guidance, and discover post-graduation possibilities. Through social and academic events, community outreach, and an active social media presence, UCS fosters a supportive community within the department and across UC San Diego. Students can also join committees including Graphic Design, Public Relations, Event Planning, Social Media, Administration, and Media Journalism to gain hands-on experience and grow in areas that match their interests.', ''), NULLIF('', ''), NULLIF('', ''), NULLIF('', '')),
  ('Undergraduate Economics Society at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of the Organization is to develop a community of students and faculty members interested in business and economics while providing students with resources and opportunities to start their careers.', ''), NULLIF('ues@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Undergraduate History Network', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('The Undergraduate History Network is a student-led organization focused on working with the undergraduate history department at UCSD, serving as a student voice on department initiatives and events aimed at supporting undergraduates. The UHN also works to create resources, events, programs, and networks for undergraduate history students, and supporting them during their time at UC San Diego.', ''), NULLIF('uhn@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Triton Pickleball', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('To have a pickleball community on the UCSD campus by fostering a fun, social, and competitive environment. Open play sessions will be hosted regularly at the Warren and Muir courts, with hopes to eventually grow into participating in and hosting clinics and matches.', ''), NULLIF('realtritonpickleball@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Undergraduate MD-PhD Society (UMPS) at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The Undergraduate MD/PhD Society (UMPS) is a student-led 501(c)(3) nonprofit dedicated to empowering all undergraduate students—especially those who are underserved or underrepresented—to pursue MD/PhD, MD, PhD, and other graduate-level careers in medicine and science. With over 1,200 members across UC San Diego, UCLA, and UC Irvine, UMPS provides clinical training, research preparation, mentorship, and leadership opportunities to help students thrive on their path to advanced study.', ''), NULLIF('umps@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Undergraduate Women in Computing at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('WIC is a non-profit student organization committed to fostering a supportive and informative environment for women in computing related fields through technical, professional development, and social events. We also focus on high school outreach programs to bring more young women into the field. Keynote speakers, career fair information, interview preparation, and awareness about relevant CS conferences are few of the opportunities that will be provided for our members. Furthermore, we strive to empower our members to leave UCSD with the goal of making a positive difference in the world by promoting equity, diversity, inclusion, leadership, and accessibility throughout their career paths. Through our initiatives and programs, we aim to instill in our members a sense of responsibility to contribute to a more equitable and inclusive tech industry and society at large.', ''), NULLIF('wic.at.ucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Unheard Cries', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('We are a Christ-inspired nonprofit organization that dents Middle Eastern poverty through supporters like you.', ''), NULLIF('mfarag@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('United Accounting Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The United Accounting Society at UC San Diego strives to assist students in pursuing their interests and goals with respect to the accounting industry. We seek to provide students opportunities to learn more about the accounting industry, form connections with professionals, and meet other students with interests in accounting. We hope to help students achieve a smooth transition into the professional working world by helping them develop professionally.', ''), NULLIF('uasatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('United Taiwanese Association at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('UTA’s purpose is to ensure the success of United Taiwanese Association (UTA) and its continuation as one of the largest non-profit student-run Asian-interest socio cultural organizations at UC San Diego. UTA aims to strengthen social networks, celebrate Asian culture, and promote academic merit.', ''), NULLIF('uta.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Urban Changemakers', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Urban Changemakers serves as a placemaking, project-based organization to promote & improve the well-being of students, faculty, and staff. We seek to foster a greater sense of community through healthy placemaking both on and off-campus.', ''), NULLIF('urbanchangemakers@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('VAW Global at UC San Diego', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('The purpose of Volunteers Around the World Global Health Alliances Health Outreach is to provide medical education and organize free mobile clinics to underserved communities, both locally and internationally. The organization aims to enhance the well-being of individuals through volunteer services, educational programs, and community outreach initiatives. Additionally, the organization fosters a supportive community among members and encourages professional development, cultural exchange, and a commitment to service. The primary focus of club meetings is to develop a plan for a medical-related internship in underserved communities abroad (ex. Guatemala, Dominican Republic, Peru, Cambodia, Uzbekistan, etc.).', ''), NULLIF('vawmedatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Venture Capital Finance and Innovation Club', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Founded in 2018, our club strives to educate Rady School students about the venture capital and finance industries. We believe in using our analytical skill-sets, combined with quality communication, to bring together teams and innovative ideas for the benefit of the San Diego Community. Building upon the entrepreneurial spirit of the Rady School, our club offers members insight into how new companies are created, pitched, evaluated, and funded.', ''), NULLIF('venturecapitalclub@rady.ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Vertical Flight Society @ UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('To showcase and educate to all students the growing engineering industry that is vertical flight.', ''), NULLIF('vfsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Video Game Development Club (VGDC) at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of the Video Game Development Club is to aid students interested in video game development to produce games and learn skills relating to game design, game programming, art & animation, music & sound effect production, dialogue & story writing, and more. The club shall serve as an interdisciplinary forum where members can discuss video games and seek like-minded teammates from various disciplines to participate in club and personal projects. The club shall provide structure in hosting various projects and game making competitions, in addition to hosting educational workshops for all skill levels to learn and participate.', ''), NULLIF('vgdc@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Undergraduate Law Review at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Undergraduate Law Review at UC San Diego offers an accessible platform for students interested in legal discussion and reflection. The journal aims to publish exemplary works submitted by undergraduate students on relevant and impactful issues, with an emphasis on legal scholarship. Through publication, we hope to not only provide resources for, but also encourage intellectual exploration for students interested in a legal or academic career.', ''), NULLIF('undergraduatelawreviewatucsd@gmail.com', ''), NULLIF('@ulr_atucsd', ''), NULLIF('', '')),
  ('Volleyball Enthusiasts @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of the Volleyball Enthusiasts is to be a hub where those harboring any amount of interest in volleyball can come together and learn more about the sport. Unlike the current competitive nature of volleyball organizations on campus currently, this organization is being built as a relaxed environment where everybody can learn about how to play the game at their own pace, along with learning about related topics such as general fitness and the professional sport.', ''), NULLIF('volleyballenthusiasts.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Watch Altars', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('Academics Discipleship Learning and Innovation Vocation and Expertise Leadership Development Word of Faith Prayer Mission to Nations and Peoples', ''), NULLIF('admin@watchaltars.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('WAV Church', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('WAV stands for "with a vision." We are a community of believers in San Diego committed to help college students discover who Jesus is & grow deeper in their relationship with Him. We want to inspire students to share in God’s vision for our campuses & beyond.', ''), NULLIF('ischon@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('WAV Rec', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('We are WAV Rec—a group of students who wants to build connection and memories during our time in college. We host a variety of social events and fun workshops, like cooking classes, food trips around SD, board game and snack nights, and (ofc) sports like volleyball and basketball! Beyond a purely social org, we also like to engage in deeper conversation as we spend time together—exploring themes like the meaning and purpose of life, significance and worth, each others'''' passion and interests, and what God has to do in any of this. Though we share views from a Christian perspective (and invite you to ask questions and explore!), we warmly welcome anyone from any background.', ''), NULLIF('ischon@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('We the Redeemed', NULLIF('Spiritual', ''), NULLIF('Spiritual', ''), NULLIF('We the Redeemed is the English-speaking congregation of San Diego Korean United Presbyterian Church. Members of We the Redeemed strive to be transformed people who genuinely know and love God and are part of a community that seeks to obey His will wholeheartedly. This student organization exists to provide a campus community, accountability, and outreach for college students—both committed members and those exploring Christianity—to grow in and share the good news of Christ.', ''), NULLIF('college@wetheredeemed.org', ''), NULLIF('', ''), NULLIF('', '')),
  ('Vietnamese American Pharmacy Student Association', NULLIF('Health Professions', ''), NULLIF('Professional', ''), NULLIF('The Vietnamese American Pharmacy Student Association (VAPSA) is a cultural and professional organization that welcomes pharmacy students from all backgrounds, promoting Vietnamese heritage, community, and leadership. VAPSA seeks to support academic, professional, and personal growth among its members, foster mentorship and leadership development, and advocate for representation in pharmacy and healthcare. Through educational initiatives, community outreach, and service, VAPSA strives to improve the health and well-being of the communities we serve while empowering future leaders in pharmacy.', ''), NULLIF('vapsa.atucsd@gmail.com', ''), NULLIF('@vapsaatucsd', ''), NULLIF('', '')),
  ('Weightlifting at UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Weightlifting at UC San Diego is a community that aims to promote growth in the practice and community of the sport of Olympic Weightlifting. We seek to create a friendly, welcoming environment in which anyone, regardless of experience or goals, can learn to improve their strength, especially in the Snatch and Clean and Jerk.', ''), NULLIF('weightliftingatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Vietnamese Student Association', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('To promote and preserve the Vietnamese culture and awareness among the UCSD students through various cultural, social, community, and educational events.', ''), NULLIF('vsaatucsd@gmail.com', ''), NULLIF('@vsaatucsd', ''), NULLIF('', '')),
  ('Women in Chemical Sciences @ UC San Diego (WiCS)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('Our mission is to foster a community for inspiring the pursuit of gender equality in STEM. We work toward our mission in four areas. First, we raise gender bias awareness and teach prevention of unconscious bias in STEM workplaces. Through professional development we prepare for success through informative career-building events such as seminars and networking opportunities. With outreach we inspire the next generation of scientists, with an emphasis on underrepresented groups. Finally, we promote well-being by improving mental and physical wellness through community activities, social gatherings, and individualized mentorship.', ''), NULLIF('wics@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Women in Business', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Women in Business @ UC San Diego is committed to empowering women from all backgrounds to become leaders in today’s dynamic world. Through a combination of business education, networking opportunities, mentorship, leadership development workshops, and social events, members will join a supportive community dedicated to helping one another succeed. By fostering both professional and personal growth, Women in Business @ UC San Diego aims to equip women pursuing business with the tools to drive change not only within themselves and the university but also in the broader world they aspire to impact.', ''), NULLIF('wib.atucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Women in ECE (WeCe)', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('To build a community among graduate women in Electrical and Computer Engineering to enhance their career opportunities. While this organizations targets women in ECE, they welcome members from all gender identities', ''), NULLIF('wece@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Women in Math', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('The purpose of this club is to create an inclusive space for women who are majoring, minoring, or simply interested in the field of mathematics. We will host events to offer study breaks, provide opportunities to meet new people, and organize collaborative study sessions. Through our events, members can connect with their peers outside of the classroom and help foster a supportive community on campus.', ''), NULLIF('womeninmath@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Women in Science Society at UC San Diego', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Women in Science Society (WSS) at UC San Diego is dedicated to empowering, supporting, and uplifting women pursuing careers in science, technology, engineering, and mathematics (STEM). Through informative workshops, networking events, and high-impact volunteer opportunities, we provide resources and opportunities to help our members thrive both academically and personally during their studies at UC San Diego. Our goal is to foster a community of respect, motivation, and inclusivity within the scientific field.', ''), NULLIF('wss.at.ucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Women of Aeronautics and Astronautics', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('The purpose of this organization is to support and empower marginalized genders in the aeronautic and astronautic fields. Women currently make up less than 20% of the aeronautics and astronautics industry, and while there are many reasons for that, WoAA seeks to inspire a change in that statistic. Through organization, networking, and volunteering, WoAA empowers individuals to grow and challenge themselves both personally and professionally.', ''), NULLIF('jmb004@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Women''''s Club Basketball @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Our club’s purpose is to bring together a group of students who are passionate about playing basketball together and in a competitive and structured environment. We aim to create an empowering and supportive space where students of all skill levels can confidently play, grow, and thrive in basketball, fostering community, learning, and a love for the game in a safe and welcoming environment. The club is focused on women-identifying students but is open to all who are interested. The club will be composed of players that have tried out and were selected to play on our competitive team by the coaching staff and officers. Along with this roster of players, we welcome anyone who did not make the official roster to the club also, as well as anyone else who is interested in playing basketball to join us at our practices as our goal is to provide a safe and welcoming environment to students interested in expanding their game.', ''), NULLIF('skaloghlian@ucsd.edu', ''), NULLIF('@wbballclubatucsd', ''), NULLIF('', '')),
  ('Xclusive Dance Showcase', NULLIF('Music and Performance', ''), NULLIF('Social', ''), NULLIF('Xclusive Dance Showcase at UC San Diego is a sustainable and community-based platform, dedicated to celebrating the creativity, passion, and care that permeates the UC San Diego dance community. Through hosting various events, including an annual showcase, Xclusive aims to not only celebrate the dancers, but to create a supportive, welcoming space for the dancers to share their performances/works.', ''), NULLIF('xclusivedanceshowcase@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Y.E.S - Youth Empowerment in Science', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('Youth Empowerment in Science is a volunteer organization dedicated to inspiring a passion for science in underrepresented areas of San Diego by developing and implementing hands-on workshops in elementary schools. We understand that not all communities have the same access to STEM education opportunities. That''''s why we''''re committed to reaching those underserved areas, sparking curiosity, and breaking down barriers to learning. Our workshops are designed to engage and inspire students, connecting science to their everyday lives and interests. With Y.E.S., you''''re not just teaching science, you''''re empowering the next generation of scientists, engineers, and innovators from all backgrounds. Join us in creating a future where every child has the opportunity to say ''''YES'''' to the amazing world of science. To find out more or apply to be a general member check out our instagram @yesatucsd.', ''), NULLIF('yesatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Yalla, Lets Talk! at UC San Diego', NULLIF('Cultural', ''), NULLIF('Cultural', ''), NULLIF('The purpose and goal of this organization is to provide a space for MENA (Middle Eastern and North African) students and those who are interested in learning various dialects in the Arabic language. The organization will be promoting the unity that languages should bring instead of the isolation of communities and culture. Organization members will be able to practice and strengthen their use of the Arabic language. They will also be joining a much larger supportive community in learning the various dialects in the language and be exposed to MENA cultures through food and drink tasting, music, dancing, etc.', ''), NULLIF('yallaletstalk89@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Wushu club @ UC San Diego', NULLIF('Social', ''), NULLIF('Social', ''), NULLIF('Wushu Club at UC San Diego strives to develop the trainings and techniques of Wushu to anyone interested in the Chinese martial art, whether experienced or not. We aim to establish a community where those who participate can feel welcomed to learn and practice forms, train their bodies physically and mentally, compete and perform, and create new bonds with fellow peers.', ''), NULLIF('wushu@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Yonder Deep', NULLIF('Academic Department Affiliated', ''), NULLIF('Academic', ''), NULLIF('At Yonder Deep we are working towards being the first undergraduate organization to develop a 3D printed, low cost, Autonomous Underwater Vehicle (AUV) which allows for the implementation of several sensor types for the purpose of oceanographic and climate change research. Every member will have access to lab space at MESOM laboratory at the Scripps Institute of Oceanography where we conduct all of our exciting rapid prototyping, software development and testing!', ''), NULLIF('yonderdeep@ucsd.edu', ''), NULLIF('@yonderdeep', ''), NULLIF('', '')),
  ('Yonder Dynamics', NULLIF('Educational', ''), NULLIF('Academic', ''), NULLIF('To provide hands-on robotics experience to students by developing a Mars rover to compete in the international University Rover Challenge. Students will gain both specialized and interdisciplinary experience in the mechanical, electrical, scientific, and software subsystems essential to the success of a competitive Mars rover.', ''), NULLIF('yonderdynamics@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Young Americans for Freedom', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('To advocate for public policies consistent with the Sharon Statement.', ''), NULLIF('yafatucsandiego@gmail.com', ''), NULLIF('yaf_at_ucsd', ''), NULLIF('', '')),
  ('Young People''''s Alliance at UC San Diego', NULLIF('Political', ''), NULLIF('Social', ''), NULLIF('The Young People''''s Alliance at UC San Diego is a nonpartisan movement of students across the US, fighting for youth voices in politics. We mobilize young people to get engaged in politics through student voter registration, election turnout promotion, various civic engagement events, and opportunities to advocate to policymakers. We plan to host guest legislator speaker events, debate & election couch parties, and voter registration drives at UC San Diego every quarter to engage young people in politics. We also support youth-based advocacy across the US, advocating for innovative initiates to increase youth power in US politics.', ''), NULLIF('ypaatucsandiego@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Young Planners Society', NULLIF('Pre-Professional', ''), NULLIF('Professional', ''), NULLIF('Young Planners'''' Society (YPS) is a career oriented network for undergraduate USP students and those who are interested in city planning and related careers. Founded in Fall 2018, YPS hosts events that alternate between social opportunities and professional/educational development. Each year, YPS also incorporates faculty involvement and community site visits. In addition, YPS aims to connect students with both regional planning-oriented companies and local jurisdiction planning agencies to facilitate professional mentorship opportunities for students. Young Planners'''' Society is represented as a nationally registered planning student organization under the American Planning Association (APA) California chapter, and is locally represented under the San Diego APA section.', ''), NULLIF('ypsatucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', '')),
  ('Youth Movement Against Alzheimers, The', NULLIF('Service & Changemaking', ''), NULLIF('Service', ''), NULLIF('To promote understanding of Alzheimer’s and healthy aging among youth and young adults by providing unique opportunities to volunteer with those afflicted by Alzheimer’s and advocate for change. Our purpose is to raise funds for research and support treatment and care, ultimately contributing to the movement in finding a cure for this neurodegenerative disease. Interest form here: https://forms.gle/D1ky98iKgecgLLrA8', ''), NULLIF('ymaa@ucsd.edu', ''), NULLIF('', ''), NULLIF('', '')),
  ('Zor (Hindi Film) Dance Team at UC San Diego', NULLIF('Dance', ''), NULLIF('Social', ''), NULLIF('Zor is UCSD''''s premier competitive Bollywood-Fusion dance team. We travel across the country to compete in the collegiate Bollywood circuit. Additionally, we hope to explore and express aspects of South Asian culture through dance.', ''), NULLIF('zoratucsd@gmail.com', ''), NULLIF('', ''), NULLIF('', ''));
